insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-8b9f91fa4c8b', 'en', 'B1', 'The Basic Passive Voice in English', 'A voz passiva é usada quando queremos dar mais importância à ação ou ao objeto que a recebe, em vez de quem a pratica. Neste tópico, você vai aprender a formar e usar a voz passiva no presente e no passado simples, com exemplos práticos e exercícios.', 'A voz passiva é formada com o verbo ''to be'' (no tempo correto) + o particípio passado do verbo principal. No presente simples: am/is/are + particípio passado. No passado simples: was/were + particípio passado. O agente (quem faz a ação) pode ser mencionado com ''by'' ou omitido se for óbvio ou irrelevante.', '["Quando o foco está na ação ou no objeto, não no agente.","Quando o agente é desconhecido ou não importante.","Em textos formais, científicos ou jornalísticos.","Para ser mais objetivo ou impessoal."]'::jsonb, '["Esquecer de usar o verbo ''to be'' no tempo correto.","Usar o particípio passado no lugar do passado simples em frases ativas.","Confundir o particípio com o passado de verbos irregulares.","Adicionar ''by'' quando o agente é desnecessário."]'::jsonb, '["Lembre-se: o particípio passado de verbos regulares termina em -ed, mas os irregulares têm formas próprias.","Na voz passiva, o sujeito da frase ativa vira o agente (introduzido por ''by'').","Se o agente for ''people'', ''they'', ''someone'' etc., geralmente é omitido.","O verbo ''to be'' concorda com o novo sujeito."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b1-8b9f91fa4c8b-exercise-01', 'en', 'B1', 'Exercise 1: Choose the correct form', 'Na voz passiva, usamos ''is/are'' + particípio passado. O sujeito ''The letters'' é plural, então usamos ''are''.', 'The letters ___ sent yesterday.', 'Choose the correct form to complete the sentence.', '["is","are","was","were"]'::jsonb, 1, 1, true, 'generated-grammar-en-b1-8b9f91fa4c8b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b1-8b9f91fa4c8b-exercise-02', 'en', 'B1', 'Exercise 2: Identify the passive sentence', 'Na voz passiva, o verbo ''to be'' + particípio passado. ''The cake was made by my mother'' é passiva; as outras são ativas.', 'Which sentence is in the passive voice?', 'Identify the passive sentence.', '["She wrote a book.","The book was written by her.","She is writing a book.","The book has many pages."]'::jsonb, 1, 2, true, 'generated-grammar-en-b1-8b9f91fa4c8b')
