insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b1-8b9f91fa4c8b-exercise-04', 'en', 'B1', 'Exercise 4: Choose the correct by agent', 'Quando queremos dizer quem fez a ação, usamos ''by'' + agente. Como a frase está no passado, usamos ''was painted by''.', 'The painting ___ Picasso.', 'Choose the option with the correct use of ''by''.', '["was painted by","is painted by","painted by","was painted for"]'::jsonb, 0, 4, true, 'generated-grammar-en-b1-8b9f91fa4c8b')
