insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b1-8b9f91fa4c8b-exercise-05', 'en', 'B1', 'Exercise 5: Passive or active?', 'Quando o agente é desconhecido, usamos a voz passiva sem ''by''. ''The house was built in 1900'' é passiva e adequada.', 'Choose the best sentence if you don''t know who built the house.', 'Select the most appropriate sentence.', '["Someone built the house in 1900.","The house was built in 1900.","They built the house in 1900.","The house built in 1900."]'::jsonb, 1, 5, true, 'generated-grammar-en-b1-8b9f91fa4c8b')
