insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-d67994fdfb98', 'en', 'B1', 'Introduction to Reported Speech', 'Nesta lição, você vai aprender a usar o discurso indireto (reported speech) para relatar o que alguém disse. Vamos focar nas mudanças de tempo verbal e pronomes quando transformamos uma fala direta em indireta.', 'Para formar o discurso indireto, geralmente usamos um verbo introdutório no passado, como ''said'' ou ''told'', e mudamos o tempo verbal da fala original um passo para trás. Por exemplo, ''I am tired'' (present simple) vira ''She said she was tired'' (past simple). Os pronomes também mudam para refletir a perspectiva de quem relata.', '["Relatar o que alguém disse em uma conversa.","Contar uma notícia ou informação que você ouviu.","Repassar instruções ou pedidos.","Descrever o que alguém perguntou."]'::jsonb, '["Esquecer de mudar o tempo verbal (ex: ''She said she is tired'' em vez de ''was tired'').","Usar ''say'' com objeto direto (ex: ''She said me...'' em vez de ''She told me...'').","Não mudar os pronomes (ex: ''He said I am happy'' em vez de ''He said he was happy'').","Confundir a ordem das palavras em perguntas indiretas (ex: ''He asked where was the station'' em vez de ''He asked where the station was'')."]'::jsonb, '["Podemos usar ''say'' sem objeto direto, mas com objeto usamos ''tell''.","Em perguntas indiretas, a ordem das palavras é a mesma de uma afirmação.","As mudanças de tempo podem ser ignoradas se a informação ainda for verdadeira ou relevante, mas no nível B1 é seguro sempre mudar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

