insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-194c0d6cd44f', 'en', 'B1', 'Modal Verbs for Deduction, Obligation, and Advice', 'Nesta lição, você vai aprender a usar os verbos modais em inglês para fazer deduções (must, might, can''t), expressar obrigação (must, have to) e dar conselhos (should, ought to). Esses verbos são essenciais para se comunicar de forma mais natural e precisa em situações do dia a dia, como dar opiniões, fazer sugestões e falar sobre regras.', 'Os verbos modais são seguidos da forma base do verbo principal (sem ''to''), exceto ''ought to''. Eles não mudam de forma para a terceira pessoa do singular (he/she/it). Para formar negativas, adicionamos ''not'' após o modal (must not, should not) e para perguntas, invertemos a ordem: ''Must I...?'', ''Should I...?''. ''Have to'' é um semi-modal e muda com o sujeito: ''has to'' para he/she/it.', '["Dedução: usar ''must'' para algo quase certo, ''might'' para possibilidade, e ''can''t'' para impossibilidade.","Obrigação: usar ''must'' para obrigação forte (pessoal), ''have to'' para obrigação externa (regras, leis).","Conselho: usar ''should'' e ''ought to'' para dar recomendações.","Proibição: usar ''must not'' para algo proibido.","Falta de obrigação: usar ''don''t have to'' para algo não necessário."]'::jsonb, '["Usar ''must'' no passado: para obrigação passada, use ''had to''.","Usar ''should'' para deduções: para deduções, use ''must'' ou ''might''.","Usar ''to'' após modais: diga ''I must go'' e não ''I must to go''.","Confundir ''mustn''t'' com ''don''t have to'': ''mustn''t'' é proibido, ''don''t have to'' é não necessário."]'::jsonb, '["''Could'' também pode ser usado para possibilidade, mas é mais incerto que ''might''.","''Ought to'' tem o mesmo significado de ''should'', mas é menos comum.","''Have to'' é mais usado no dia a dia para obrigações externas, como regras de trabalho ou leis.","''Must'' é mais comum em inglês britânico para obrigação; no inglês americano, ''have to'' é preferido.","Para dedução no passado, use ''must have + past participle'' (ex: ''She must have left.'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

