insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-f340cc7f1b72', 'en', 'B1', 'Narrative Discourse Markers', 'Os marcadores discursivos são palavras ou expressões que conectam ideias e organizam a narrativa, tornando-a mais clara e coesa. Nesta lição, você aprenderá a usar marcadores como ''first'', ''then'', ''after that'', ''finally'', ''however'', ''because'', e ''so'' para contar histórias e descrever sequências de eventos.', 'Os marcadores discursivos são geralmente advérbios ou locuções adverbiais que podem ser usados no início, meio ou fim das frases. Eles ajudam a indicar ordem cronológica (first, then, next, after that, finally), causa e efeito (because, so, therefore), contraste (but, however, although) e adição (also, moreover). Por exemplo: ''First, I woke up. Then, I had breakfast. After that, I went to work. Finally, I came home.''', '["Para indicar a sequência de eventos em uma narrativa: First, I woke up. Then, I had breakfast.","Para mostrar causa e consequência: I was tired, so I went to bed early.","Para introduzir um contraste: I wanted to go out, but it was raining.","Para adicionar informação: She is intelligent. Moreover, she is very kind.","Para concluir uma história: Finally, they lived happily ever after."]'::jsonb, '["Usar ''although'' com ''but'' na mesma frase: Although it was raining, but we went out. (errado)","Usar ''because'' com ''so'' juntos: Because I was hungry, so I ate. (errado)","Colocar ''finally'' no lugar errado: I finally arrived at home. (pode ser aceito, mas normalmente se usa ''finally'' no início ou fim da frase)","Usar ''then'' para indicar causa: I was sick, then I stayed home. (deveria ser ''so'' ou ''therefore'')","Usar ''firstly'' em vez de ''first'' em contextos informais: Firstly, I want to say... (embora correto, é mais formal)"]'::jsonb, '["Em narrativas, é comum usar o passado simples com esses marcadores para contar eventos concluídos.","Os marcadores podem ser usados no início da frase ou entre orações, e a pontuação varia (vírgula após o marcador quando no início).","Prática: conte uma história curta usando pelo menos cinco marcadores diferentes."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

