insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-36f73a0c135d', 'en', 'B1', 'Conditionals: Zero, First, and Second', 'Vamos explorar as três principais estruturas condicionais do inglês: zero, primeira e segunda condicional. Você vai aprender quando usar cada uma para falar sobre fatos, situações reais e situações imaginárias.', 'Zero conditional: If + present simple, present simple. First conditional: If + present simple, will + base verb. Second conditional: If + past simple, would + base verb.', '["Zero conditional: para fatos gerais e verdades científicas.","First conditional: para situações possíveis no futuro.","Second conditional: para situações hipotéticas ou improváveis no presente ou futuro.","Zero conditional: para instruções e rotinas.","First conditional: para fazer promessas e ameaças.","Second conditional: para dar conselhos (If I were you...)."]'::jsonb, '["Usar ''will'' na cláusula ''if'' na first conditional.","Usar ''would'' na cláusula ''if'' na second conditional.","Confundir zero e first conditional ao falar de hábitos.","Esquecer de usar o passado simples na cláusula ''if'' da second conditional.","Usar ''was'' em vez de ''were'' para todas as pessoas na second conditional."]'::jsonb, '["Na second conditional, use ''were'' para todas as pessoas, especialmente em situações formais.","A vírgula é usada quando a cláusula ''if'' vem primeiro.","Condicionais podem ser usadas com outros verbos modais como ''can'', ''might'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

