insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-50a482ce1af0', 'en', 'B1', 'Reported Speech: Introduction', 'Nesta lição, você vai aprender a usar o discurso indireto (reported speech) em inglês. Vamos focar em como relatar o que alguém disse, fazendo as mudanças necessárias nos pronomes, tempos verbais e expressões de tempo.', 'Para formar o discurso indireto, geralmente usamos um verbo introdutório como ''say'' ou ''tell'' e mudamos o tempo verbal do que foi dito. Se o verbo introdutório estiver no passado (said, told), o tempo verbal da frase original geralmente ''volta'' um tempo: presente vira passado simples, passado simples vira passado perfeito, etc. Também mudamos pronomes e advérbios de tempo e lugar (ex.: ''now'' vira ''then'', ''here'' vira ''there'').', '["Relatar o que alguém disse em uma conversa.","Transmitir informações que ouvimos de outras pessoas.","Referir-se a declarações, perguntas e pedidos feitos anteriormente.","Escrever resumos de entrevistas ou notícias.","Contar histórias ou anedotas usando discurso indireto."]'::jsonb, '["Usar o mesmo tempo verbal da fala original, sem recuar o tempo.","Esquecer de mudar os pronomes (ex.: ''I'' para ''he/she'').","Confundir ''say'' e ''tell'' (tell exige objeto).","Esquecer de mudar expressões de tempo e lugar.","Usar a mesma ordem de palavras de uma pergunta direta em indireta."]'::jsonb, '["O discurso indireto é muito usado em conversas do dia a dia e em contextos profissionais.","A mudança de tempo é chamada de ''backshift''.","Mesmo que o conteúdo seja verdadeiro, muitas vezes o backshift é feito em inglês.","Em perguntas indiretas, a ordem das palavras é de afirmação, não de pergunta.","Com ''say'', não usamos objeto direto: ''He said (that)...'' já com ''tell'' usamos: ''He told me (that)...''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

