insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-23d309d3f5a7', 'en', 'B1', 'Gerund or Infinitive? Making the Right Choice', 'Nesta lição, você vai aprender quando usar o gerúndio (-ing) ou o infinitivo (to + verbo) em inglês. Vamos explorar os padrões mais comuns com verbos como ''enjoy'', ''want'', ''decide'' e ''suggest'', e como escolher a forma correta. Isso vai ajudar você a soar mais natural e evitar erros comuns.', 'Para formar o gerúndio, adicione -ing ao verbo (ex.: ''playing'', ''eating''). Para o infinitivo, use ''to'' antes do verbo (ex.: ''to play'', ''to eat''). Alguns verbos são seguidos por gerúndio (ex.: ''enjoy playing''), outros por infinitivo (ex.: ''want to play''), e alguns podem ser seguidos por ambos, mas com mudança de significado (ex.: ''stop to smoke'' vs. ''stop smoking'').', '["Use gerúndio após preposições: ''interested in learning''.","Use gerúndio como sujeito da frase: ''Swimming is good for you''.","Use infinitivo para expressar propósito: ''I study to pass the exam''.","Use gerúndio após verbos como ''enjoy'', ''finish'', ''suggest''.","Use infinitivo após verbos como ''want'', ''decide'', ''hope''.","Alguns verbos como ''stop'', ''remember'', ''forget'' mudam de significado dependendo da forma."]'::jsonb, '["Dizer ''I enjoy to play'' em vez de ''I enjoy playing''.","Dizer ''I want going'' em vez de ''I want to go''.","Confundir ''stop to do'' (parar para fazer) com ''stop doing'' (parar de fazer).","Usar gerúndio após ''would like'' (correto: ''would like to do'').","Esquecer o ''to'' após certos verbos como ''decide'', ''hope'', ''need''."]'::jsonb, '["Lembre-se: após preposições, sempre use gerúndio.","Alguns verbos como ''love'', ''like'', ''hate'' podem ser seguidos por gerúndio ou infinitivo com pouca diferença.","Cuidado com verbos que mudam de significado, como ''remember'' e ''forget''.","Pratique com listas de verbos comuns para memorizar os padrões."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

