insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-3e3bc0c7a6eb', 'en', 'B1', 'Narrative Discourse Markers', 'Os marcadores discursivos são palavras ou expressões que ajudam a organizar uma narrativa, conectando ideias e guiando o ouvinte ou leitor através da história. Em inglês, esses marcadores são essenciais para contar histórias de forma clara e natural, indicando sequência, causa, contraste, e conclusão. Nesta lição, você aprenderá os marcadores mais comuns usados em narrativas no nível B1, como ''first'', ''then'', ''after that'', ''suddenly'', ''in the end'', etc., e como usá-los para tornar suas histórias mais envolventes e fáceis de seguir.', 'Os marcadores de narrativa são geralmente advérbios, locuções adverbiais ou expressões fixas que aparecem no início de uma oração ou entre orações. Eles são frequentemente seguidos por uma vírgula quando usados no início de uma frase. Estrutura básica: [Marcador], [oração]. Exemplos: ''First, I woke up.'', ''Then, I had breakfast.'', ''Suddenly, the phone rang.'' Alguns marcadores podem também aparecer no meio da frase, como ''however'' (no entanto), ''meanwhile'' (enquanto isso), e ''finally'' (finalmente).', '["Sequência: first, then, next, after that, finally - para ordenar eventos cronologicamente.","Contraste: but, however, on the other hand - para mostrar oposição entre ideias.","Causa e consequência: because, so, therefore, as a result - para explicar razões e efeitos.","Surpresa ou clímax: suddenly, unexpectedly, out of nowhere - para introduzir eventos inesperados.","Conclusão: in the end, eventually, at last - para encerrar a narrativa."]'::jsonb, '["Usar ''then'' repetidamente sem variação - tente variar com ''next'', ''after that'', ''later''.","Esquecer de usar vírgula após o marcador no início da frase - ex.: ''First I woke up.'' (incorreto) vs. ''First, I woke up.'' (correto).","Confundir ''finally'' (após muita espera) com ''at the end'' (posição final).","Usar ''however'' sem ponto e vírgula ou nova frase - é formal e deve ser usado corretamente."]'::jsonb, '["Em narrativas informais, muitos marcadores podem ser omitidos, mas usá-los torna a história mais coesa.","Pratique com histórias curtas do seu dia a dia, usando pelo menos cinco marcadores diferentes.","Observe como marcadores são usados em filmes, séries e músicas em inglês para internalizar o uso natural.","Cuidado com a pronúncia: ''suddenly'' tem ênfase na primeira sílaba."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

