insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-7ff7ee131fa7', 'en', 'B1', 'Past Continuous and Narrative Tenses', 'Nesta lição, você vai aprender a usar o Past Continuous para descrever ações em andamento no passado e como combiná-lo com o Simple Past para contar histórias de forma mais rica e natural.', 'O Past Continuous é formado com o passado do verbo ''to be'' (was/were) + o gerúndio (verbo terminado em -ing). Para a negativa, adiciona-se ''not'' após was/were; para a interrogativa, inverte-se a posição do sujeito e do verbo ''to be''. Exemplos: I was studying, You were not studying, Was she studying?', '["Descrever uma ação que estava em andamento em um momento específico do passado.","Descrever ações que estavam acontecendo simultaneamente no passado.","Descrever uma ação que estava em andamento quando outra ação a interrompeu (com Simple Past).","Fornecer contexto ou atmosfera em uma narrativa no passado.","Descrever ações temporárias ou hábitos no passado (com significado de mudança)."]'::jsonb, '["Usar o Past Continuous com verbos estativos (like, love, believe, know) em vez do Simple Past.","Confundir o uso com o Simple Past: usar Past Continuous para ações curtas e completas.","Errar a forma do verbo ''to be'' (usar ''was'' com ''you'' ou ''were'' com ''he/she'').","Esquecer de adicionar -ing ao verbo principal."]'::jsonb, '["Use ''while'' antes de Past Continuous e ''when'' antes de Simple Past para conectar duas ações.","O Past Continuous é frequentemente usado para descrever o cenário de uma história, enquanto o Simple Past narra os eventos principais.","A forma negativa contraída: wasn''t (was not) e weren''t (were not).","A forma interrogativa: Was/Were + sujeito + verbo -ing?"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

