insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-914d792dc0dc', 'en', 'B1', 'The Passive Voice: Focus on the Action', 'A voz passiva em inglês é usada para destacar a ação ou o objeto que a recebe, em vez de quem a realiza. Nesta lição, você aprenderá a formar a voz passiva no presente e no passado simples, e a usar ''by'' para indicar o agente quando necessário. Isso tornará seu inglês mais flexível e profissional.', 'Para formar a voz passiva, usamos o verbo ''to be'' no tempo adequado + o particípio passado do verbo principal. No presente simples: am/is/are + particípio. No passado simples: was/were + particípio. Exemplos: ''The report is written by the team'' (presente) e ''The report was written by the team'' (passado).', '["O foco está na ação ou no resultado, não em quem a fez.","O agente é desconhecido ou óbvio, como em ''The window was broken''.","Em textos formais, científicos ou notícias, para dar impessoalidade.","Para variar o discurso e evitar repetição."]'::jsonb, '["Esquecer de usar o verbo ''to be'' no tempo correto: ''The cake made'' (errado) -> ''The cake is made'' (correto).","Usar o particípio errado: ''I was very excited'' (correto) vs. ''I was very exciting'' (errado, pois ''exciting'' descreve algo que causa excitação).","Incluir o agente quando não é necessário: ''The letter was written by me'' (geralmente prefere-se ''I wrote the letter'' na voz ativa).","Confundir com o present perfect: ''The book has been read'' (correto) vs. ''The book has read'' (errado)."]'::jsonb, '["A voz passiva é formada com o particípio passado, que para verbos regulares termina em -ed, mas os irregulares têm formas próprias (ex: written, eaten, seen).","Para transformar uma frase ativa em passiva, o objeto da ativa vira o sujeito da passiva, e o sujeito da ativa vira o agente (precedido por ''by'').","Em inglês, é comum omitir o agente quando ele é óbvio ou irrelevante (ex: ''The room was cleaned'').","A voz passiva pode ser usada em qualquer tempo verbal, mas nesta lição focamos no presente e passado simples."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b1-914d792dc0dc-exercise-01', 'en', 'B1', 'Choose the correct passive form', 'Complete a frase com a forma correta da voz passiva no presente simples.', 'English is spoken in many countries.', 'The project ______ by the students every semester.', '["is presented","was presented","presents","is presenting"]'::jsonb, 0, 1, true, 'generated-grammar-en-b1-914d792dc0dc')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

