insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-a16e84535b4a', 'en', 'B1', 'Reported Speech: Introduction', 'Nesta lição, você vai aprender a usar o discurso indireto (reported speech) para relatar o que alguém disse. Vamos focar nas mudanças de tempo verbal, pronomes e palavras de tempo, além de verbos como ''say'' e ''tell''. A ideia é que você consiga contar conversas e notícias de forma clara e natural em inglês.', 'Para formar o discurso indireto, geralmente mudamos o verbo da frase original para um tempo passado. Se a frase original está no presente simples, muda para passado simples. Se está no presente contínuo, muda para passado contínuo. Pronomes e advérbios de tempo também mudam de acordo com a perspectiva do falante. Por exemplo: ''I am tired'' (presente) vira ''She said she was tired'' (passado). O verbo ''say'' é usado sem objeto direto (''He said that...''), enquanto ''tell'' exige o objeto (''He told me that...'').', '["Relatar o que alguém disse em uma conversa ou entrevista.","Contar notícias ou informações que você ouviu de outra pessoa.","Recontar uma história ou piada.","Transmitir instruções ou pedidos de forma indireta."]'::jsonb, '["Esquecer de mudar o tempo verbal (ex: usar ''is'' em vez de ''was'').","Confundir ''say'' e ''tell'' (ex: ''he said me'' em vez de ''he told me'').","Manter os pronomes da frase original sem ajustar para a perspectiva do relator.","Não modificar expressões de tempo como ''now'' para ''then''."]'::jsonb, '["Em inglês falado, ''that'' é frequentemente omitido: ''She said she was tired''.","Para perguntas, usamos ''if'' ou ''whether'' para perguntas de sim/não.","O discurso indireto é comum em narrativas e relatos jornalísticos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

