insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-5442ebff0a83', 'en', 'B1', 'Modal Verbs: Deduction, Obligation, and Advice', 'Nesta lição, você vai aprender a usar os verbos modais em inglês para fazer deduções (must, might, can''t), falar sobre obrigação (must, have to) e dar conselhos (should, ought to). Vamos explorar as formas e os usos, com exemplos práticos para o dia a dia.', 'Estrutura: sujeito + modal + verbo principal (na forma base) + complemento. Exemplos: ''She must be tired'' (dedução), ''You must wear a seatbelt'' (obrigação), ''You should see a doctor'' (conselho). Modais não mudam com o sujeito (he/she/it). Para o passado, usamos ''must have + particípio'' para deduções, ''had to'' para obrigação, e ''should have + particípio'' para conselhos no passado.', '["Dedução presente: must (certeza), might (possibilidade), can''t (impossibilidade). Ex.: ''He must be at work now.''","Dedução passada: must have, might have, can''t have + particípio. Ex.: ''She must have forgotten the meeting.''","Obrigação presente: must (obrigação interna), have to (obrigação externa). Ex.: ''I must study harder.'' / ''We have to pay taxes.''","Obrigação passada: had to (obrigação passada). Ex.: ''Yesterday I had to work late.''","Conselho: should/ought to. Ex.: ''You should eat more vegetables.''","Conselho passado: should have/ought to have + particípio. Ex.: ''You should have called me.''"]'::jsonb, '["Usar ''to'' após modais: ''must to go'' (errado) → ''must go'' (correto).","Confundir ''must'' e ''have to'': em frases negativas, ''mustn''t'' significa proibição, enquanto ''don''t have to'' significa não haver necessidade.","Adicionar ''s'' na terceira pessoa do singular: ''he must goes'' (errado) → ''he must go'' (correto).","Usar ''must'' para obrigação passada: ''I must go yesterday'' (errado) → ''I had to go yesterday'' (correto)."]'::jsonb, '["Modais não têm forma de futuro: usamos ''will have to'' para obrigação futura.","Para fazer perguntas, invertemos o modal com o sujeito: ''Must I?'', ''Should we?''.","As formas negativas: must not (mustn''t), cannot (can''t), should not (shouldn''t).","A forma ''ought to'' é mais formal que ''should''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

