insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-054c48d415ef', 'en', 'B1', 'Gerunds and Infinitives: Choosing the Right Form', 'Nesta lição, você vai aprender quando usar o gerúndio (forma -ing) e o infinitivo (to + verbo) em inglês. Essa é uma escolha importante porque muitos verbos têm preferências específicas. Vamos ver os padrões mais comuns e praticar com exercícios.', 'O gerúndio é formado adicionando -ing ao verbo: play → playing, go → going. O infinitivo é formado com ''to'' + a forma básica do verbo: to play, to go. Alguns verbos são seguidos por gerúndio (ex.: enjoy, avoid, finish), outros por infinitivo (ex.: want, decide, hope), e alguns podem ser seguidos por ambos, mas com mudança de significado (ex.: remember, forget, stop).', '["Use gerúndio após preposições (ex.: interested in learning, good at cooking).","Use gerúndio como sujeito da frase (ex.: Swimming is good exercise).","Use infinitivo para expressar propósito ou intenção (ex.: I went to the store to buy milk).","Use gerúndio ou infinitivo após certos verbos conforme a preferência (ex.: enjoy + -ing, want + to).","Use gerúndio após certas expressões como ''it''s no use'', ''can''t help'', ''feel like''."]'::jsonb, '["Erro: I enjoy to play soccer. Correto: I enjoy playing soccer.","Erro: I want going home. Correto: I want to go home.","Erro: She is interested in to learn English. Correto: She is interested in learning English.","Erro: I stopped to smoke last year. (significado errado) Correto: I stopped smoking last year. (parei de fumar)","Erro: To swim is good exercise. (técnicamente correto, mas incomum) Prefira: Swimming is good exercise."]'::jsonb, '["Lembre-se: após preposições, sempre use gerúndio.","Alguns verbos como ''start'', ''begin'', ''continue'' podem ser seguidos por gerúndio ou infinitivo sem grande mudança de significado.","Cuidado com verbos que mudam de significado: ''remember to do'' (lembrar de fazer) vs. ''remember doing'' (lembrar de ter feito).","Use o gerúndio após ''enjoy'', ''avoid'', ''finish'', ''mind'', ''suggest''.","Use o infinitivo após ''want'', ''need'', ''decide'', ''hope'', ''plan'', ''promise'', ''learn''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

