insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-e8304f81affd', 'en', 'B1', 'Frequent Phrasal Verbs for Everyday Conversations', 'Phrasal verbs são combinações de um verbo com uma preposição ou advérbio que criam um significado novo, muitas vezes diferente do verbo original. No nível B1, é essencial conhecer os phrasal verbs mais comuns para entender e participar de conversas do dia a dia, já que eles são usados com muita frequência por falantes nativos. Este material foca em phrasal verbs frequentes e apresenta exercícios para praticar seu uso em contextos reais.', 'Phrasal verbs são formados por um verbo + uma partícula (preposição ou advérbio). Exemplos: ''get up'' (levantar-se), ''turn on'' (ligar), ''look after'' (cuidar de). Alguns phrasal verbs são separáveis, ou seja, o objeto pode ficar entre o verbo e a partícula (ex.: ''turn the TV on''), enquanto outros são inseparáveis e o objeto sempre vem depois da partícula (ex.: ''look after the children'').', '["Usamos phrasal verbs em situações informais e cotidianas, como conversas com amigos, família ou colegas de trabalho.","São usados para expressar ações concretas, como ''pick up'' (pegar), ''put on'' (vestir), ''take off'' (tirar).","Também expressam ações abstratas, como ''give up'' (desistir), ''find out'' (descobrir), ''come up with'' (criar/inventar).","Em inglês falado, os phrasal verbs são preferidos em vez de verbos mais formais (ex.: ''give up'' em vez de ''surrender'')."]'::jsonb, '["Traduzir phrasal verbs literalmente do português: ''look for'' não é ''olhar para'', mas sim ''procurar''.","Separar phrasal verbs inseparáveis: dizer ''look the children after'' em vez de ''look after the children''.","Esquecer de mudar o phrasal verb quando o objeto é um pronome: com pronomes, é obrigatório separar (ex.: ''turn it on'', não ''turn on it'').","Confundir phrasal verbs com significados parecidos, como ''look for'' (procurar) e ''look after'' (cuidar)."]'::jsonb, '["Phrasal verbs são muito comuns em inglês falado e escrito informal.","Muitos phrasal verbs têm mais de um significado, dependendo do contexto.","É útil aprender phrasal verbs em grupos de tópicos, como rotina diária, trabalho ou viagens.","Preste atenção se o phrasal verb é separável ou não, especialmente com pronomes."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

