insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-24892d2a7db4', 'en', 'B1', 'Narrative Discourse Markers', 'Os marcadores discursivos de narrativa são palavras e expressões que usamos para organizar uma história, conectar ideias e guiar o ouvinte ou leitor através dos eventos. Neste tópico, você vai aprender a usar conectores como ''first'', ''then'', ''after that'', ''suddenly'', ''in the end'' e outros para contar histórias de forma clara e envolvente em inglês.', 'Não há uma formação gramatical rígida; os marcadores são usados no início de frases ou orações. Exemplos: ''First, I woke up.'' ''Then, I had breakfast.'' ''After that, I went to work.'' ''Suddenly, the phone rang.'' ''In the end, we decided to stay home.'' Eles podem ser advérbios, locuções adverbiais ou conjunções.', '["Para sequenciar eventos em ordem cronológica: first, then, next, after that, finally.","Para indicar mudanças repentinas: suddenly, unexpectedly, all of a sudden.","Para mostrar causa e efeito: because of that, as a result, therefore.","Para contrastar: however, on the other hand, but.","Para concluir: in the end, finally, at last."]'::jsonb, '["Usar ''at the end'' em vez de ''in the end'' para conclusão.","Colocar vírgula erroneamente: ''First I woke up'' sem vírgula pode ser aceito, mas em B1 é melhor usá-la para clareza.","Traduzir literalmente do português: ''depois'' vira ''after'' mas em narrativa é ''after that'' ou ''then''.","Repetir o mesmo marcador em toda frase; variar é melhor.","Confundir ''then'' com ''than''."]'::jsonb, '["Em narrativas, os marcadores ajudam a criar coesão e ritmo.","Em inglês, usamos ''firstly'' para listar argumentos, mas ''first'' para tempo.","É comum usar o passado simples com esses marcadores.","Em diálogos, podem ser mais informais: ''so'', ''then''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

