insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-87945ce4e97f', 'en', 'B1', 'Present Perfect vs Past Simple', 'Nesta lição, você vai aprender a diferença entre o Present Perfect e o Past Simple em inglês. O Present Perfect conecta o passado com o presente, enquanto o Past Simple fala de ações completamente terminadas. Você vai ver quando usar cada um e como formar frases corretamente.', 'Present Perfect: have/has + past participle (ex.: I have visited, She has eaten). Past Simple: verbo no passado (ex.: I visited, She ate).', '["Use Present Perfect para ações que aconteceram em um tempo não especificado: ''I have traveled to Brazil.''","Use Present Perfect para ações que começaram no passado e continuam no presente: ''She has lived here for five years.''","Use Past Simple para ações com tempo específico: ''I traveled to Brazil in 2019.''","Use Past Simple para ações completamente terminadas: ''She lived here from 2010 to 2015.''"]'::jsonb, '["Usar Past Simple com since ou for quando a ação continua no presente.","Usar Present Perfect com tempo específico (ex.: yesterday, last week)."]'::jsonb, '["No inglês americano, muitas vezes se usa Past Simple no lugar do Present Perfect com ''just'' ou ''already''.","O Past Participle dos verbos regulares é o mesmo que o passado simples (ex.: visited).","Verbos irregulares têm formas diferentes (ex.: go - went - gone)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

