insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-0d8e63eb6dbb', 'en', 'B1', 'Past Continuous and Narrative Tenses', 'Nesta lição, você vai aprender a usar o passado contínuo e outros tempos narrativos para contar histórias em inglês. Vamos focar em como descrever ações em andamento no passado e como combiná-las com o passado simples para criar narrativas claras e interessantes. Este conteúdo é ideal para o nível B1, pois ajuda a enriquecer sua comunicação e compreensão de textos e conversas sobre experiências passadas.', 'O passado contínuo é formado com o passado do verbo ''to be'' (was/were) + o verbo principal com ''ing''. Exemplos: ''I was walking'', ''They were eating''. Já o passado simples é formado com o verbo no passado (regular ou irregular). Em narrativas, usamos o passado contínuo para ações em andamento e o passado simples para ações curtas que interrompem ou acontecem em sequência. Também podemos usar o passado perfeito para ações que aconteceram antes de outra ação no passado.', '["Descrever uma ação em andamento em um momento específico do passado: ''At 8 PM, I was watching TV.''","Descrever ações simultâneas no passado: ''While she was cooking, he was reading.''","Descrever uma ação em andamento interrompida por outra ação: ''I was sleeping when the phone rang.''","Descrever o cenário ou a atmosfera de uma história: ''The sun was shining and birds were singing.''"]'::jsonb, '["Usar o passado contínuo com verbos de estado (like, want, need) que normalmente não são usados em contínuo.","Confundir o uso do passado contínuo e do passado simples para ações curtas e completas.","Esquecer de usar ''was/were'' corretamente de acordo com o sujeito.","Usar o passado contínuo para ações rotineiras no passado (nesse caso, use ''used to'' ou ''would'')."]'::jsonb, '["Lembre-se de que alguns verbos (like, love, hate, know, believe) geralmente não são usados no contínuo.","Na narrativa, o passado contínuo costuma aparecer no início para contextualizar.","Você pode usar ''when'' com passado simples e ''while'' com passado contínuo.","O passado perfeito é formado com ''had'' + particípio passado."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

