insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-511291306132', 'en', 'B1', 'Introduction to Reported Speech', 'Nesta lição, você aprenderá a usar o discurso reportado (também chamado de discurso indireto) para relatar o que alguém disse. Vamos focar nas mudanças de tempo verbal e nos pronomes quando passamos do discurso direto para o indireto.', 'Para formar o discurso reportado, use um verbo introdutório como ''say'' ou ''tell'' no passado (said/told) e mude o tempo verbal do que foi dito: presente simples vira passado simples, presente contínuo vira passado contínuo, passado simples vira passado perfeito, etc. Além disso, mude pronomes e advérbios de tempo e lugar conforme necessário.', '["Relatar o que alguém disse em uma conversa.","Repassar informações ou notícias ouvidas de outras pessoas.","Contar o que alguém perguntou ou pediu.","Descrever conversas passadas em histórias ou relatos.","Transmitir opiniões ou crenças de outras pessoas."]'::jsonb, '["Esquecer de mudar o tempo verbal (ex: dizer ''She says she is tired'' em vez de ''She said she was tired'' quando o reporting verb está no passado).","Confundir ''say'' e ''tell'': usamos ''tell'' quando há um objeto (ex: ''He told me''), e ''say'' sem objeto (ex: ''He said'').","Não ajustar pronomes (ex: ''He said: \"I am happy\"'' vira ''He said he was happy'', não ''He said I was happy'').","Manter expressões de tempo como ''now'' em vez de mudar para ''then''."]'::jsonb, '["No discurso reportado, o verbo introdutório geralmente fica no passado (said/told), mas se o que foi dito é uma verdade geral, o presente pode ser mantido.","As mudanças de tempo seguem um padrão: volta-se um tempo no passado (present -> past, past -> past perfect).","É comum usar ''that'' após o verbo de relato, mas ele é opcional em muitos casos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

