insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-e8e7b96c7e1b', 'en', 'B1', 'Modals for Deduction, Obligation, and Advice', 'Nesta lição, você vai aprender a usar os verbos modais em inglês para fazer deduções (must, might, can''t), expressar obrigação (must, have to, should) e dar conselhos (should, ought to, had better). Esses verbos são essenciais para se comunicar de forma natural em situações do dia a dia.', 'Os verbos modais são seguidos da forma base do verbo principal (sem ''to''). Eles não mudam com o sujeito (he, she, it não recebem ''s''). Para formar negativas, adicione ''not'' após o modal (ex: must not, should not). Para perguntas, inverta o sujeito e o modal (ex: Should I...?).', '["Dedução: usamos ''must'' quando temos certeza de algo, ''might'' para possibilidade, e ''can''t'' para algo impossível. Ex: ''She must be tired.''","Obrigação: usamos ''must'' e ''have to'' para obrigações fortes, mas ''have to'' é mais comum em conversas. Ex: ''You have to pay taxes.''","Conselho: usamos ''should'' e ''ought to'' para dar conselhos. ''Had better'' é mais forte, sugere consequências negativas. Ex: ''You should see a doctor.''"]'::jsonb, '["Usar ''to'' após o modal: ''I must to go'' (errado) -> ''I must go'' (correto).","Adicionar ''s'' para he/she/it: ''She musts go'' (errado) -> ''She must go'' (correto).","Confundir ''must not'' (proibição) com ''don''t have to'' (não é necessário).","Usar ''must'' para o passado: para o passado, use ''had to''."]'::jsonb, '["''Must'' e ''have to'' são frequentemente intercambiáveis no presente, mas ''must'' é mais pessoal e ''have to'' é mais externo.","''Might'' e ''may'' são usados para possibilidade, mas ''might'' é mais comum na fala.","''Should'' e ''ought to'' são sinônimos, mas ''ought to'' é mais formal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

