insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-1e48deca106c', 'en', 'B1', 'Gerunds and Infinitives: Patterns of Use', 'Neste tópico, você vai aprender a usar o gerúndio (verb + -ing) e o infinitivo (to + verb) corretamente em inglês. Vamos ver quais verbos são seguidos de gerúndio, quais de infinitivo, e também quando o significado muda dependendo da forma escolhida.', 'Gerúndio: verbo + -ing (ex.: playing, eating). Infinitivo: to + verbo (ex.: to play, to eat). Alguns verbos são seguidos de gerúndio (ex.: enjoy playing), outros de infinitivo (ex.: want to play), e alguns podem ser seguidos de ambos, mas com significados diferentes (ex.: stop smoking vs stop to smoke).', '["Use gerúndio após preposições: She is good at dancing.","Use gerúndio como sujeito da frase: Swimming is fun.","Use infinitivo para expressar propósito: I study to learn.","Use infinitivo após adjetivos: It is important to sleep.","Use gerúndio após certos verbos como enjoy, finish, suggest.","Use infinitivo após certos verbos como decide, hope, plan.","Use gerúndio após expressões como ''be used to'', ''look forward to''.","Use infinitivo após verbos modais: I can to swim? (errado) -> I can swim."]'::jsonb, '["Usar gerúndio após ''want'': I want to go (não I want going).","Usar infinitivo após ''enjoy'': I enjoy playing (não I enjoy to play).","Confundir ''stop to do'' e ''stop doing''.","Esquecer o ''to'' após ''look forward to'': I look forward to hearing from you.","Usar gerúndio após ''would like'': I would like to travel (não I would like traveling)."]'::jsonb, '["Alguns verbos mudam de significado com gerúndio ou infinitivo, como ''remember'' e ''forget''.","Com ''need'', o gerúndio tem sentido passivo: The house needs cleaning.","Aprenda os verbos mais comuns de cada lista para melhorar sua fluência."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

