insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-b22bf78e6bc1', 'en', 'B1', 'Frequent Phrasal Verbs in English', 'Phrasal verbs são combinações de um verbo com uma partícula (preposição ou advérbio) que juntos formam um significado diferente do verbo original. Eles são muito comuns no inglês falado e escrito, e conhecer os mais frequentes é essencial para a comunicação do dia a dia. Nesta lição, você vai aprender alguns phrasal verbs importantes e como usá-los corretamente.', 'Os phrasal verbs são formados por um verbo + partícula(s). A partícula pode ser uma preposição (como ''in'', ''on'', ''up'') ou um advérbio (como ''away'', ''back''). Alguns phrasal verbs são separáveis, ou seja, o objeto pode ficar entre o verbo e a partícula (ex: ''turn the TV off'') ou depois da partícula (ex: ''turn off the TV''). Outros são inseparáveis, e o objeto sempre vem depois da partícula (ex: ''look after the children'').', '["Para expressar ações cotidianas: ''get up'', ''wake up'', ''go out''.","Para falar sobre relacionamentos: ''get along with'', ''break up'', ''make up''.","Para comunicação: ''call back'', ''talk about'', ''point out''.","Para situações de trabalho/estudo: ''carry out'', ''figure out'', ''look into''.","Para movimento e direção: ''come in'', ''go back'', ''run away''."]'::jsonb, '["Traduzir literalmente cada palavra do phrasal verb, o que resulta em significado errado.","Separar phrasal verbs que são inseparáveis: ''look after the children'' (não ''look the children after'').","Usar a partícula errada: ''depend of'' em vez de ''depend on''.","Esquecer de usar o phrasal verb com o tempo verbal correto: ''I wake up early'' (presente) vs. ''I woke up early'' (passado).","Colocar o objeto no lugar errado em phrasal verbs separáveis com pronomes: ''turn it off'' (não ''turn off it'')."]'::jsonb, '["Os phrasal verbs são usados tanto na fala quanto na escrita, mas são mais comuns em contextos informais.","Alguns phrasal verbs têm significados múltiplos dependendo do contexto; por isso, é importante prestar atenção ao contexto.","Pratique phrasal verbs em frases completas para internalizar seu uso.","Preste atenção à entonação: em muitos casos, a partícula é enfatizada na fala.","Existem dicionários específicos de phrasal verbs que podem ajudar na hora de estudar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

