insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-214b2bb1b824', 'en', 'B1', 'The Passive Voice: Basic Formation', 'A voz passiva é usada quando queremos focar na ação ou no objeto que recebe a ação, e não em quem a realiza. Nesta unidade, você vai aprender como formar frases na voz passiva em inglês no presente e no passado simples.', 'Para formar a voz passiva, usamos o verbo ''to be'' no mesmo tempo do verbo principal da frase ativa, seguido do particípio passado do verbo principal. No presente simples: am/is/are + particípio passado. No passado simples: was/were + particípio passado. O agente (quem faz a ação) pode ser introduzido por ''by'', mas muitas vezes é omitido.', '["Quando o agente é desconhecido ou não é importante: ''My car was stolen.'' (Meu carro foi roubado.)","Quando queremos dar ênfase ao objeto ou à ação: ''The letter was sent.'' (A carta foi enviada.)","Em textos formais, notícias e relatórios: ''The new policy was approved.'' (A nova política foi aprovada.)","Quando queremos ser impessoais ou diplomáticos: ''Mistakes were made.'' (Erros foram cometidos.)"]'::jsonb, '["Esquecer de usar o verbo ''to be'' corretamente no tempo certo: ''The cake baked.'' em vez de ''The cake was baked.''","Usar o particípio passado como se fosse passado simples: ''The window was broke.'' em vez de ''The window was broken.''","Inverter o sujeito e o objeto na transformação: ''The dog bit the man'' vira ''The dog was bitten by the man'' e não ''The man was bitten by the dog'' (embora ambas as frases sejam válidas, mas com significado diferente).","Usar ''by'' com objetos quando não é necessário: ''The book was read by me.'' é correto, mas muitas vezes é mais natural omitir o agente."]'::jsonb, '["O particípio passado de verbos regulares é formado com -ed, mas os irregulares têm formas próprias (ex.: write -> wrote -> written).","Em frases passivas, o agente pode ser omitido se não for importante para a mensagem.","A voz passiva é comum em manuais, instruções e textos científicos.","Para transformar uma frase ativa em passiva, identifique o objeto direto e o transforme em sujeito da passiva."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

