insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-2cbfb7dba3cd', 'en', 'B1', 'Reported Speech: Introduction', 'Nesta lição, você vai aprender a usar o discurso indireto (reported speech) para relatar o que alguém disse. Vamos focar nas mudanças de tempo verbal e pronomes, essenciais para uma comunicação clara em inglês.', 'Para formar o discurso indireto, geralmente mudamos o verbo da frase original para um tempo passado. Por exemplo: ''I am tired'' (discurso direto) vira ''She said (that) she was tired'' (discurso indireto). Observe as mudanças: presente simples vira passado simples; presente contínuo vira passado contínuo; passado simples vira passado perfeito. Os pronomes também mudam para refletir a perspectiva de quem relata.', '["Para relatar o que alguém disse em uma conversa: ''He said he was happy.''","Para contar notícias ou informações: ''The news reported that the president would visit.''","Para expressar opiniões ou pensamentos: ''She thought that the movie was great.''","Para transmitir pedidos ou ordens: ''He asked me to close the door.''","Para relatar perguntas: ''She asked where I lived.''"]'::jsonb, '["Esquecer de mudar o tempo verbal: dizer ''She said she is tired'' em vez de ''She said she was tired''.","Não mudar os pronomes: dizer ''He said I am busy'' quando na verdade é ''He said he was busy''.","Usar ''that'' em perguntas indiretas: ''She asked me that where I lived'' (errado) - correto: ''She asked me where I lived''.","Manter a mesma ordem de palavras da pergunta direta em perguntas indiretas: ''She asked me where was I going'' (errado) - correto: ''She asked me where I was going''."]'::jsonb, '["Em inglês falado, ''that'' pode ser omitido após ''say'' e ''tell''.","As mudanças de tempo são chamadas de ''backshift''.","Cuidado com as exceções, como quando o fato ainda é verdadeiro: ''She said she is a doctor'' (ainda é verdade).","Para pedidos, usamos ''ask someone to do something''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

