insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-e4656d65c150', 'en', 'B1', 'Modal Verbs for Deduction, Obligation, and Advice', 'Nesta lição, você vai aprender a usar os verbos modais must, have to, should, might, could e can''t para expressar dedução, obrigação e conselho. Vamos focar em situações do dia a dia, como dar opiniões, fazer sugestões e falar sobre probabilidades.', 'Os modais são seguidos da forma base do verbo (sem ''to''). Não mudam de forma para he/she/it. Exemplos: ''She must go'', ''They should study''. Para formar negativas, adicionamos ''not'' após o modal: ''must not'' (mustn''t), ''should not'' (shouldn''t). Para perguntas, invertemos o modal com o sujeito: ''Should I go?''.', '["Dedução: must (certeza), might/could (possibilidade), can''t (impossibilidade)","Obrigação: must e have to (forte), should/ought to (fraca)","Conselho: should, ought to, had better","Falta de obrigação: don''t have to","Proibição: must not"]'::jsonb, '["Usar ''to'' após modal: ''must to go'' (errado) -> ''must go'' (certo)","Confundir ''mustn''t'' (proibição) com ''don''t have to'' (não precisa)","Usar ''must'' para dedução negativa: ''must not'' para impossibilidade (deve ser ''can''t'')","Esquecer de usar a forma base: ''should goes'' (errado) -> ''should go'' (certo)"]'::jsonb, '["Em inglês britânico, ''shall'' é usado para sugestões, mas no inglês americano é menos comum.","Para conselhos, ''had better'' é mais forte que ''should'', implicando consequências negativas se não for seguido."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

