insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-09efecc172a7', 'en', 'B1', 'Defining and Non-Defining Relative Clauses', 'Nesta lição, você vai aprender a diferença entre orações relativas restritivas (defining) e não restritivas (non-defining) em inglês. As restritivas são essenciais para identificar a pessoa ou coisa de que falamos, enquanto as não restritivas apenas adicionam informação extra. Vamos ver como usá-las corretamente, com exemplos práticos e exercícios para fixar o conteúdo.', 'Para formar orações relativas, usamos pronomes relativos como ''who'' (para pessoas), ''which'' (para coisas) e ''that'' (para pessoas ou coisas, apenas em orações restritivas). Nas orações restritivas, não usamos vírgulas. Exemplo: ''The woman who lives next door is a doctor.'' Nas não restritivas, usamos vírgulas e não podemos usar ''that''. Exemplo: ''My sister, who lives in São Paulo, is an engineer.''', '["Use defining relative clauses para identificar qual pessoa ou coisa específica você está falando.","Use non-defining relative clauses para adicionar informação extra sobre algo que já está claro.","Em defining, você pode usar ''that'' no lugar de ''who'' ou ''which''.","Em non-defining, você deve usar ''who'' ou ''which'', e sempre com vírgulas."]'::jsonb, '["Usar ''that'' em orações não restritivas: ''My car, that is blue, is fast.'' → errado. O correto é ''My car, which is blue, is fast.''","Esquecer as vírgulas em orações não restritivas: ''My brother who lives in Rio is a teacher.'' → sem vírgulas, muda o sentido.","Usar ''which'' para pessoas: ''The man which called you is my boss.'' → errado. Use ''who'' ou ''that''."]'::jsonb, '["Em orações restritivas, você pode omitir o pronome relativo quando ele é objeto da oração: ''The book I read is great.'' (sem ''that'').","Em orações não restritivas, o pronome relativo não pode ser omitido.","Cuidado com a pontuação: as não restritivas exigem vírgulas, que podem mudar completamente o sentido da frase."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

