insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-c72a0a0357e6', 'en', 'B1', 'Gerund or Infinitive? Patterns That Work', 'Nesta lição, você vai aprender a usar o gerúndio (-ing) e o infinitivo (to + verbo) corretamente em inglês. Vamos focar nos padrões mais comuns: verbos que sempre usam gerúndio, verbos que sempre usam infinitivo, e verbos em que o significado muda dependendo da forma escolhida.', 'Formação: O gerúndio é formado acrescentando -ing ao verbo (ex.: play -> playing). O infinitivo é formado com a partícula ''to'' + forma base do verbo (ex.: to play). Alguns verbos são seguidos apenas de gerúndio (ex.: enjoy, avoid, consider). Outros são seguidos apenas de infinitivo (ex.: want, decide, hope). Há também verbos como ''like'', ''love'', ''hate'' que podem ser seguidos de ambas as formas com pouca diferença de significado. E verbos como ''remember'' e ''stop'' onde a escolha muda o sentido.', '["Usamos gerúndio após preposições (ex.: interested in learning, good at cooking).","Usamos infinitivo para expressar propósito ou intenção (ex.: I study to improve my English).","Usamos gerúndio como sujeito da frase (ex.: Swimming is great exercise).","Usamos infinitivo após adjetivos (ex.: It''s important to practice).","Verb + gerund: enjoy, avoid, consider, finish (ex.: She avoids eating fast food).","Verb + infinitive: want, decide, hope, need (ex.: They hope to travel soon)."]'::jsonb, '["Usar gerúndio após ''want'' (ex.: I want going -> I want to go).","Usar infinitivo após ''enjoy'' (ex.: I enjoy to dance -> I enjoy dancing).","Confundir ''stop to do'' (parar para fazer) com ''stop doing'' (parar de fazer).","Usar ''to'' após preposição (ex.: I''m good to swim -> I''m good at swimming).","Esquecer o ''to'' após ''decide'' (ex.: I decided go -> I decided to go)."]'::jsonb, '["Com ''like'', ''love'', ''hate'' e ''prefer'', as duas formas são possíveis, mas o gerúndio é mais comum em inglês britânico.","''Try'' também muda de significado: ''try to do'' (tentar) e ''try doing'' (experimentar).","Atenção: ''need'' pode ser seguido de gerúndio com sentido passivo (ex.: The car needs washing)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

