insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-9afe39684cdb', 'en', 'B1', 'Narrative Discourse Markers in English', 'Os marcadores discursivos de narrativa são palavras e expressões que usamos para organizar uma história, mostrar a sequência dos eventos, indicar mudanças de tempo ou lugar, e conectar ideias de forma clara. Eles ajudam o ouvinte ou leitor a acompanhar a narrativa com facilidade. Nesta lição, você vai aprender alguns marcadores comuns e como usá-los para contar histórias de maneira mais fluente e natural.', 'Os marcadores discursivos de narrativa são usados geralmente no início de uma frase ou oração, seguidos por vírgula. Aqui estão os principais tipos: **Sequência**: first, then, next, after that, finally. **Tempo**: meanwhile, at the same time, later, earlier, suddenly. **Causa e consequência**: because of that, as a result, therefore, so. **Contraste**: however, but, although, even though. **Conclusão**: in the end, eventually, finally, to sum up. Eles podem aparecer em diferentes posições na frase, mas no início são mais comuns para organizar a narrativa.', '["Para sequenciar eventos em uma história: ''First, we arrived at the airport. Then, we checked in our luggage.''","Para indicar mudanças de tempo: ''Meanwhile, the rain started to fall.''","Para mostrar causa e consequência: ''He missed the bus. Because of that, he was late for work.''","Para introduzir contraste: ''She wanted to go out. However, she was too tired.''","Para concluir uma narrativa: ''Finally, they reached the top of the mountain.''"]'::jsonb, '["Usar ''then'' e ''after that'' como sinônimos, mas ''after that'' indica um intervalo maior.","Esquecer a vírgula após o marcador no início da frase.","Usar ''however'' como ''but'' no início da frase, mas ''however'' é mais formal e exige vírgula.","Confundir ''meanwhile'' com ''afterwards'' - ''meanwhile'' ocorre ao mesmo tempo, ''afterwards'' depois.","Repetir o mesmo marcador muitas vezes, tornando a narrativa monótona."]'::jsonb, '["Os marcadores discursivos são mais comuns na fala e na escrita informal, mas alguns como ''however'' e ''therefore'' são usados em contextos formais.","Use uma variedade de marcadores para enriquecer sua narrativa.","Lembre-se de que o contexto determina a escolha do marcador.","Pratique contando histórias em inglês usando esses marcadores para melhorar sua fluência."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

