insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-27ad2991cc7d', 'en', 'B1', 'Present Perfect vs Past Simple', 'Nesta lição, você vai aprender a diferença entre o Present Perfect e o Past Simple em inglês. O Present Perfect conecta o passado com o presente, enquanto o Past Simple é usado para ações completamente terminadas em um tempo específico no passado. Vamos explorar como formar cada um e quando usá-los corretamente.', 'Present Perfect: sujeito + have/has + particípio passado (ex: I have visited, She has eaten). Past Simple: sujeito + verbo no passado (regular: -ed, irregular: lista para memorizar) (ex: I visited, She ate).', '["Usamos Present Perfect para experiências de vida sem tempo definido (ex: I have traveled to Brazil).","Usamos Past Simple para ações com tempo definido (ex: I traveled to Brazil in 2019).","Present Perfect para ações que começaram no passado e continuam no presente (ex: She has lived here for five years).","Past Simple para ações completamente terminadas (ex: She lived here for five years, then moved).","Present Perfect com palavras como ''already'', ''yet'', ''just'', ''ever'', ''never''."]'::jsonb, '["Usar Past Simple com ''already'' ou ''yet'' (ex: I already ate é comum, mas mais formal: I have already eaten).","Esquecer o particípio passado irregular (ex: I have went em vez de I have gone).","Usar Present Perfect com tempo definido (ex: I have seen him yesterday é incorreto; use I saw him yesterday).","Confundir ''been'' e ''gone'' (ex: She has been to Paris significa que visitou e voltou; she has gone to Paris significa que está lá agora)."]'::jsonb, '["Em inglês americano, é comum usar Past Simple com ''just'', ''already'', ''yet'', especialmente em conversas informais.","As palavras ''for'' e ''since'' são frequentemente usadas com Present Perfect para indicar duração.","Alguns verbos têm particípios passados irregulares que precisam ser memorizados.","A diferença entre ''ever'' (em perguntas) e ''never'' (em negativas) é importante."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

