insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-813d668e5065', 'en', 'B1', 'Understanding the Passive Voice in English', 'Nesta lição, você vai aprender a voz passiva em inglês. A voz passiva é usada para focar na ação e no objeto que a recebe, em vez de quem realiza a ação. Isso é muito comum em notícias, textos acadêmicos e situações formais. Vamos entender como formar frases na voz passiva, quando usá-la e evitar erros comuns.', 'Para formar a voz passiva, usamos o verbo ''to be'' no tempo certo + o particípio passado do verbo principal. No presente, usamos ''am/is/are'' + particípio. No passado, usamos ''was/were'' + particípio. O objeto da frase ativa vira o sujeito da passiva. Exemplo: ''They build houses.'' → ''Houses are built.''', '["Quando o agente é desconhecido ou não é importante.","Para enfatizar a ação ou o objeto.","Em textos formais, como notícias e relatórios.","Quando queremos ser impessoais."]'::jsonb, '["Esquecer o verbo ''to be''.","Usar o particípio errado (por exemplo, ''ed'' em verbos irregulares).","Misturar o objeto com o sujeito.","Usar a voz passiva quando a ativa é mais clara."]'::jsonb, '["A voz passiva é formada com ''be'' + particípio passado.","O particípio passado de verbos regulares termina em ''-ed''.","Verbos irregulares têm particípios específicos (ex: ''written'', ''eaten'').","Podemos usar ''by'' para indicar o agente, se necessário."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

