insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b1-ab9b0bd019af', 'en', 'B1', 'Zero, First, and Second Conditionals', 'Nesta lição, você vai aprender a usar os três tipos principais de condicionais em inglês: zero conditional, first conditional e second conditional. Essas estruturas são essenciais para falar sobre fatos, possibilidades futuras e situações hipotéticas. Vamos explorar como formá-las e quando usá-las.', 'Zero conditional: If + sujeito + presente simples, sujeito + presente simples (ex.: If you heat ice, it melts.)
First conditional: If + sujeito + presente simples, sujeito + will + verbo (ex.: If it rains, we will stay home.)
Second conditional: If + sujeito + passado simples, sujeito + would + verbo (ex.: If I had a car, I would drive to work.)', '["Zero conditional para fatos gerais e verdades científicas.","First conditional para situações reais e possíveis no futuro.","Second conditional para situações imaginárias ou improváveis no presente ou futuro.","Dicas: use ''unless'' como alternativa a ''if not''."]'::jsonb, '["Usar ''will'' na cláusula ''if'' (ex.: If it will rain, we will stay home.) - incorreto.","Confundir o uso do primeiro e segundo condicionais: primeiro para possível, segundo para improvável.","Esquecer o ''would'' no segundo condicional (ex.: If I had money, I buy a car.) - incorreto.","Usar ''would'' na cláusula ''if'' (ex.: If I would have time, I''d help.) - incorreto."]'::jsonb, '["A ordem das cláusulas pode ser invertida sem mudar o significado, mas use vírgula quando a cláusula ''if'' vier primeiro.","Contrações comuns: ''will'' -> ''ll'', ''would'' -> ''d''.","No segundo condicional, ''were'' é usado para todas as pessoas em situações formais (ex.: If I were you...)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

