insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-7863ee0591a5', 'es', 'B1', 'Expanded Imperative in Spanish', 'Neste tópico, vamos expandir o uso do imperativo em espanhol, focando nas formas de dar ordens, conselhos e sugestões de maneira mais rica e natural. Você aprenderá a usar o imperativo com pronomes, a forma negativa e algumas expressões úteis para diferentes contextos do dia a dia.', 'O imperativo afirmativo tem formas específicas para cada pessoa. Para ''tú'', usa-se a forma do presente do indicativo sem o ''s'' (ex.: hablar -> habla). Para ''vosotros'', troca-se o ''r'' final do infinitivo por ''d'' (ex.: hablar -> hablad). Para ''usted'' e ''ustedes'', usa-se a forma do presente do subjuntivo (ex.: hable, hablen). O imperativo negativo é formado com ''no'' + presente do subjuntivo para todas as pessoas (ex.: no hables, no hablen). Além disso, os pronomes reflexivos e de objeto são colocados depois do verbo no afirmativo (ex.: levántate) e antes no negativo (ex.: no te levantes).', '["Dar instruções claras: ''Abre la puerta, por favor.''","Dar conselhos: ''Descansa un poco; estás trabajando mucho.''","Fazer pedidos educados: ''Pásame la sal, si puedes.''","Dar permissão: ''Entra, no tengas miedo.''","Expressar desejos ou votos: ''Que tengas un buen viaje.''"]'::jsonb, '["Usar o infinitivo em vez do imperativo: ''¡Cerrar la puerta!'' (errado) em vez de ''¡Cierra la puerta!''.","Colocar o pronome incorretamente na negativa: ''No levanta te'' (errado) em vez de ''No te levantes''.","Confundir as formas de ''tú'' e ''usted'': ''Habla'' vs. ''Hable''.","Usar ''vosotros'' em contextos onde se usa ''ustedes'' na América Latina."]'::jsonb, '["Na América Latina, ''vosotros'' é pouco usado; prefira ''ustedes''.","O imperativo pode ser suavizado com expressões como ''por favor'' ou ''si puedes''.","Para dar conselhos, também se usa o condicional: ''Deberías descansar''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

