insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-aef94447f72d', 'es', 'B1', 'Reported Speech: Cómo Contar lo que Dijo Alguien', 'No nível B1, você aprende a reportar o que outras pessoas disseram. Isso é essencial para conversas do dia a dia, como contar uma fofoca, transmitir uma notícia ou relatar uma instrução. Em espanhol, o ''estilo indirecto'' (discurso indireto) envolve mudanças nos tempos verbais, pronomes e expressões de tempo e lugar.', 'Para formar o discurso indireto, usamos um verbo introdutório como ''decir'', ''preguntar'', ''pedir'' e transformamos a frase original. As mudanças principais:
- Presente → Pretérito Imperfecto (dice → dijo que + imperfecto)
- Pretérito Perfecto/Indefinido → Pretérito Pluscuamperfecto (ha dicho/dijo → había dicho)
- Futuro (ir a + infinitivo) → Condicional Simple (va a → iría)
- Imperativo → Subjuntivo Imperfecto (dijo que + subjuntivo)
- Pronomes e possessivos mudam conforme o contexto.
- Expressões de tempo e lugar mudam: hoy → ese día, mañana → al día siguiente, aquí → allí.', '["Relatar afirmações: ''María dijo que estaba cansada.''","Relatar perguntas: ''Preguntó si teníamos tiempo.''","Transmitir pedidos ou ordens: ''Me pidió que cerrara la puerta.''","Contar o que alguém disse sobre planos futuros: ''Dijo que viajaría a Brasil.''","Reportar fatos ou opiniões: ''Explicó que el agua hierve a 100 grados.''"]'::jsonb, '["Esquecer de mudar o tempo verbal: ''Dijo que está cansado'' (incorreto) → ''Dijo que estaba cansado'' (correto).","Confundir a conjunção ''si'' em perguntas sim/não: usar ''qué'' em vez de ''si''.","Não ajustar pronomes: ''Me dijo que yo estaba equivocado'' em vez de ''me dijo que estaba equivocado'' (dependendo do contexto).","Manter o imperativo em vez de usar subjuntivo: ''Me pidió que cierra la puerta'' (incorreto) → ''que cerrara'' (correto).","Não mudar expressões de tempo: ''hoy'' em vez de ''ese día''."]'::jsonb, '["O verbo introdutor geralmente está no pretérito (dijo, preguntó, pidió).","Em espanhol, o Presente do Subjuntivo pode ser usado em vez do Imperfeito quando o verbo principal está no presente (dice que esté).","O discurso indireto é comum em narrativas, notícias e conversas informais.","A entonação na fala não muda, mas na escrita pode-se usar aspas para citar diretamente."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-aef94447f72d-exercise-01', 'es', 'B1', 'Mudança de tempo verbal', 'Complete com a forma correta do verbo no discurso indireto. Lembre-se de que o presente muda para pretérito imperfeito.', 'María: ''Estoy feliz.'' → María dijo que estaba feliz.', 'Juan: ''Voy al cine.'' → Juan dijo que ____ al cine.', '["iba","fue","va","iría"]'::jsonb, 0, 1, true, 'generated-grammar-es-b1-aef94447f72d')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-aef94447f72d-exercise-02', 'es', 'B1', 'Perguntas indiretas', 'Para perguntas com resposta sim/não, usamos ''si'' e invertemos a ordem se necessário. O tempo verbal muda como nas afirmações.', 'Él: ''¿Tienes hambre?'' → Él preguntó si tenía hambre.', 'Ella: ''¿Vienes mañana?'' → Ella preguntó si ____ al día siguiente.', '["venía","viene","vendría","viniera"]'::jsonb, 0, 2, true, 'generated-grammar-es-b1-aef94447f72d')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-aef94447f72d-exercise-03', 'es', 'B1', 'Pedidos e ordens', 'Para pedidos, usamos o verbo ''pedir'' e o subjuntivo (presente ou imperfeito, dependendo do tempo do verbo principal).', 'Padre: ''Cierra la ventana.'' → El padre pidió que cerrara la ventana.', 'Profesora: ''Estudien para el examen.'' → La profesora pidió que ____ para el examen.', '["estudiaran","estudian","estudien"]'::jsonb, 0, 3, true, 'generated-grammar-es-b1-aef94447f72d')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-aef94447f72d-exercise-04', 'es', 'B1', 'Mudança de pronomes', 'Os pronomes possessivos e pessoais mudam de acordo com o contexto do relato.', 'Ana: ''Mi casa es grande.'' → Ana dijo que su casa era grande.', 'Carlos: ''Tengo un perro.'' → Carlos dijo que ____ tenía un perro.', '["él","yo","ella","tú"]'::jsonb, 0, 4, true, 'generated-grammar-es-b1-aef94447f72d')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-aef94447f72d-exercise-05', 'es', 'B1', 'Expressões de tempo', 'Palavras como ''hoy'', ''mañana'', ''aquí'' mudam no discurso indireto.', 'Hoy → ese día, mañana → al día siguiente.', 'Ayer, Pedro dijo: ''Hoy hace calor.'' → En el discurso indirecto, diríamos: Pedro dijo que ____ hacía calor.', '["ese día","hoy","ayer","el día siguiente"]'::jsonb, 0, 5, true, 'generated-grammar-es-b1-aef94447f72d')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-5a83b877e198', 'es', 'B1', 'La voz pasiva y el ''se'' impersonal', 'Nesta unidade, você vai aprender a usar a voz passiva e o ''se'' impessoal em espanhol para dar ênfase à ação em vez de ao agente, e para fazer afirmações gerais sem mencionar quem realiza a ação. Vamos explorar como formar essas estruturas e quando usá-las no dia a dia.', 'A voz passiva é formada com o verbo ''ser'' no tempo verbal desejado + particípio passado do verbo principal, que concorda em gênero e número com o sujeito. Exemplo: ''La casa es construida por los trabajadores.'' O ''se'' impessoal (ou passiva reflexa) usa ''se'' + verbo na terceira pessoa do singular ou plural, sem mencionar o agente. Exemplo: ''Se habla español en muchos países.''', '["Para dar ênfase na ação e não em quem a realiza: ''El informe fue escrito por María.''","Para expressar processos ou fatos gerais: ''El pan se hace con harina.''","Para evitar mencionar quem faz a ação: ''Se alquila apartamento.''","Com verbos de comunicação em notícias: ''Se reporta un accidente.''"]'::jsonb, '["Confundir ''se'' impessoal com pronome reflexivo: ''Se lava'' pode ser reflexivo (ele se lava) ou impessoal (lava-se).","Esquecer a concordância do particípio na passiva com ''ser'': ''Las casas son construida'' → ''construidas''.","Usar ''se'' + verbo no singular quando o sujeito é plural: ''Se venden casas'' e não ''Se vende casas''.","Traduzir literalmente do português: em espanhol, nem sempre se usa a passiva; muitas vezes o ''se'' é mais natural."]'::jsonb, '["Na B1, focamos na passiva com ''ser'' e no ''se'' impessoal, evitando a passiva com ''estar''.","O ''se'' impessoal é muito comum em anúncios, avisos e receitas.","Lembre-se de que o ''se'' impessoal pode ser singular ou plural dependendo do objeto direto."]'::jsonb, 0, true)
