insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-4efef60a405a', 'es', 'B1', 'Perífrasis verbales expandidas en español', 'Nesta unidade, você vai aprender as perífrasis verbales expandidas, que são combinações de verbos que expressam nuances de tempo, aspecto e modo. Vamos focar nas mais comuns no nível B1, como ''estar a punto de + infinitivo'', ''acabar de + infinitivo'', ''volver a + infinitivo'', ''seguir + gerundio'' e ''llevar + gerundio''. Essas estruturas são muito usadas na comunicação diária e vão enriquecer sua expressão oral e escrita.', 'As perífrasis verbales são formadas por um verbo auxiliar conjugado (ou em forma impessoal) + um verbo principal em infinitivo, gerúndio ou particípio, podendo haver ou não preposições ou conjunções entre eles. Exemplos: ''Estoy a punto de salir'' (auxiliar + prep. + infinitivo), ''Acabo de comer'' (auxiliar + de + infinitivo), ''Vuelvo a intentar'' (auxiliar + a + infinitivo), ''Sigo trabajando'' (auxiliar + gerúndio), ''Llevo dos horas esperando'' (auxiliar + gerúndio). A escolha da forma depende do significado que se quer transmitir.', '["Estar a punto de + infinitivo: expressa uma ação iminente, que está prestes a acontecer. Exemplo: ''El tren está a punto de llegar.''","Acabar de + infinitivo: expressa uma ação que aconteceu há pouco tempo. Exemplo: ''Acabo de terminar el informe.''","Volver a + infinitivo: indica a repetição de uma ação. Exemplo: ''Voy a volver a llamar al cliente.''","Seguir + gerúndio: expressa a continuação de uma ação. Exemplo: ''Sigue lloviendo desde ayer.''","Llevar + gerúndio: indica o tempo acumulado de uma ação contínua. Exemplo: ''Llevamos dos horas buscando el documento.''"]'::jsonb, '["Confundir ''acabar de'' com ''acabar por'' (que significa ''finalmente fazer algo'').","Usar ''volver a'' sem a preposição ''a'' quando seguido de infinitivo (ex.: ''Vuelvo hacer'' em vez de ''Vuelvo a hacer'').","Usar ''seguir'' com infinitivo em vez de gerúndio (ex.: ''Sigo trabajar'' em vez de ''Sigo trabajando'').","Em ''llevar + gerúndio'', esquecer de incluir o tempo (ex.: ''Llevo esperar'' em vez de ''Llevo esperando'').","Usar ''estar a punto de'' com gerúndio em vez de infinitivo (ex.: ''Estoy a punto saliendo'' em vez de ''Estoy a punto de salir'')."]'::jsonb, '["Em espanhol, as perífrasis são muito frequentes na fala e na escrita, e dão naturalidade ao idioma.","Atenção à concordância: o verbo auxiliar é conjugado e o principal permanece na forma não pessoal.","Algumas perífrases podem ter mais de um significado dependendo do contexto, por isso é importante praticar com exemplos variados.","Em situações formais, também são usadas, mas é importante dominar as combinações corretas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

