insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-143367635db1', 'es', 'B1', 'Pretérito Indefinido vs. Pretérito Imperfecto', 'Nesta lição, você vai aprender a diferença entre o Pretérito Indefinido e o Pretérito Imperfecto em espanhol. O Indefinido é usado para ações concluídas em um momento específico do passado, enquanto o Imperfecto descreve ações habituais, contínuas ou que estavam em andamento. Vamos praticar com exercícios variados!', '**Pretérito Indefinido**: Para verbos regulares, usa-se: -ar: -é, -aste, -ó, -amos, -asteis, -aron; -er/-ir: -í, -iste, -ió, -imos, -isteis, -ieron. Exemplos: hablé (falei), comí (comi), viví (vivi).

**Pretérito Imperfecto**: Para verbos regulares, usa-se: -ar: -aba, -abas, -aba, -ábamos, -abais, -aban; -er/-ir: -ía, -ías, -ía, -íamos, -íais, -ían. Exemplos: hablaba (falava), comía (comia), vivía (vivia).', '["Indefinido: ação concluída em um momento específico do passado. Exemplo: Ayer comí paella.","Indefinido: sequência de ações no passado. Exemplo: Entré, saludé y me senté.","Imperfecto: ação habitual no passado. Exemplo: Cuando era niño, jugaba todos los días.","Imperfecto: descrição de estado, clima, hora no passado. Exemplo: Hacía sol y las flores eran bonitas.","Imperfecto: ação em progresso no passado. Exemplo: Mientras leía, sonó el teléfono."]'::jsonb, '["Usar Indefinido para ações habituais: *Cuando era joven, trabajé en una fábrica* (errado). Correto: trabajaba.","Usar Imperfecto para ações concluídas com tempo definido: *Ayer comía a las 8* (errado). Correto: comí a las 8.","Confundir as conjugações: *Yo comí* (Indefinido) vs. *Yo comía* (Imperfecto).","Esquecer que o Imperfecto descreve o cenário e o Indefinido os eventos: *Era una noche oscura. De repente, oí un ruido.*","Usar Indefinido com marcadores de habitualidade como ''siempre'', ''todos los días'' quando a ação não é pontual."]'::jsonb, '["O Pretérito Indefinido também é chamado de ''Pretérito Perfecto Simple''.","O Imperfecto é usado para dar informações de fundo em narrativas.","Alguns verbos têm conjugações irregulares no Indefinido, como ''ser'' (fui), ''ir'' (fui), ''estar'' (estuve), ''tener'' (tuve).","O Imperfecto de ''ser'' é ''era, eras, era, éramos, erais, eran''.","Praticar com histórias curtas ajuda a fixar a diferença."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

