insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-4d765b6d78e8', 'es', 'B1', 'Futuro e Condicional em Espanhol', 'Nesta lição, você vai aprender a usar o futuro simples e o condicional simples em espanhol. O futuro é usado para expressar ações que acontecerão, enquanto o condicional expressa situações hipotéticas ou futuras em relação ao passado, além de ser usado para fazer pedidos educados.', 'Para o futuro simples, adicionamos as terminações -é, -ás, -á, -emos, -éis, -án ao infinitivo do verbo. Por exemplo: ''hablar'' -> ''hablaré'', ''hablarás'', ''hablará'', etc. O condicional simples é formado com as terminações -ía, -ías, -ía, -íamos, -íais, -ían adicionadas ao infinitivo. Por exemplo: ''hablar'' -> ''hablaría'', ''hablarías'', ''hablaría'', etc. Lembre-se de que os verbos irregulares têm formas próprias no futuro e no condicional, como ''tener'' -> ''tendré'' (futuro) e ''tendría'' (condicional).', '["Para expressar ações futuras: ''Mañana estudiaré para el examen.''","Para fazer previsões ou suposições sobre o futuro: ''Creo que lloverá mañana.''","Para expressar probabilidade ou possibilidade no presente: ''Serán las cinco.'' (deve ser cinco horas)","Para fazer pedidos de forma educada: ''¿Me ayudarías con esta tarea?''","Para expressar desejos ou sonhos: ''Me gustaría viajar por el mundo.''","Para falar sobre fatos hipotéticos ou imaginários: ''Si tuviera dinero, compraría un coche nuevo.''"]'::jsonb, '["Confundir as terminações do futuro e do condicional. Por exemplo, dizer ''hablaré'' quando quer dizer ''hablaría''.","Não usar o acento nas terminações do futuro (hablaré, hablarás, etc.) e do condicional (hablaría, hablarías, etc.).","Usar o condicional para expressar uma ação futura simples, em vez do futuro. Por exemplo, dizer ''Iría mañana al cine'' quando quer dizer ''Iré mañana al cine''.","Não aprender as formas irregulares do futuro e do condicional (como ''tener'' -> ''tendré'' e ''tendría'')."]'::jsonb, '["Em espanhol, o contraste entre futuro e condicional é essencial para expressar certeza versus incerteza ou cortesia.","O condicional também é usado para expressar o futuro em relação a um passado, como em ''Dijo que vendría'' (Ele disse que viria).","A prática com frases condicionais (se + presente de indicativo + futuro) é comum, mas o condicional é usado com o pretérito imperfeito do subjuntivo (ex: ''Si tuviera tiempo, viajaría'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

