insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-f1f3bfb5da58', 'es', 'B1', 'Reported Speech (Discurso Indireto)', 'No discurso indireto, relatamos o que alguém disse sem usar aspas. Em espanhol, isso geralmente envolve mudanças no tempo verbal, pronomes e advérbios. Para estudantes de nível B1, é essencial dominar as transformações básicas do presente para o passado.', 'Formação básica: Verbo introdutor (dizer, contar, perguntar) + que + oração subordinada. Para perguntas, usa-se ''si'' (se) ou palavras interrogativas. Mudanças típicas: presente -> pretérito imperfecto; pretérito perfecto -> pretérito pluscuamperfecto; futuro -> condicional. Alterações em pronomes e demonstrativos: yo -> él/ella, mi -> su, aquí -> allí, hoy -> ese día.', '["Relatar o que alguém disse em uma conversa anterior.","Transmitir perguntas e respostas de forma indireta.","Reportar notícias ou informações ouvidas.","Recontar histórias ou eventos."]'::jsonb, '["Esquecer de mudar o tempo verbal (ex: ''dijo que viene'' em vez de ''dijo que venía'').","Não ajustar os pronomes (ex: ''dijo que yo tengo'' em vez de ''dijo que él tiene'').","Usar ''que'' em perguntas diretas (ex: ''preguntó que dónde vives'' em vez de ''preguntó dónde vivías'').","Manter advérbios de tempo e lugar sem alteração."]'::jsonb, '["Atenção: em espanhol, o pretérito perfecto (ha comido) vira pluscuamperfecto (había comido) no discurso indireto.","O imperativo se transforma em subjuntivo (ex: ''dijo que vinieras'').","Verbos como ''decir'' e ''contar'' têm usos distintos: ''decir'' para afirmações, ''contar'' para narrar histórias.","Para perguntas indiretas, não se usa o ponto de interrogação.","Se o verbo introdutor estiver no presente, o tempo verbal da oração subordinada não muda."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

