insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-081db10016e4', 'es', 'B1', 'Conectores del discurso en español: organiza tus ideas', 'Os conectores do discurso são palavras ou expressões que ligam ideias, frases e parágrafos, tornando a comunicação mais clara e fluida. Nesta lição, você vai aprender a usar alguns conectores básicos para adicionar informação, contrastar, explicar causa, mostrar consequência e concluir. Isso vai ajudar você a escrever textos mais organizados e a falar de forma mais natural.', 'Os conectores são invariáveis e podem ser classificados conforme a relação que estabelecem. Na tabela abaixo, você encontra os principais conectores do nível B1, com sua função e exemplos em espanhol:

- **Adição**: ''además'' (além disso), ''también'' (também), ''incluso'' (inclusive).
  - Exemplo: *Me gusta el cine; además, me encanta el teatro.*
- **Contraste**: ''pero'' (mas), ''sin embargo'' (no entanto), ''en cambio'' (em compensação).
  - Exemplo: *Quería salir, pero estaba lloviendo.*
- **Causa**: ''porque'' (porque), ''ya que'' (já que), ''debido a'' (devido a).
  - Exemplo: *No fui a la fiesta porque estaba enfermo.*
- **Consequência**: ''por lo tanto'' (portanto), ''así que'' (então), ''en consecuencia'' (em consequência).
  - Exemplo: *Estudié mucho, así que aprobé el examen.*
- **Conclusão**: ''en resumen'' (em resumo), ''en conclusión'' (em conclusão), ''para terminar'' (para terminar).
  - Exemplo: *En conclusión, viajar es una experiencia enriquecedora.*', '["Para agregar información a una idea anterior: ''además'', ''también''.","Para contrastar dos ideas opuestas: ''pero'', ''sin embargo''.","Para explicar la razón de algo: ''porque'', ''ya que''.","Para expresar una consecuencia: ''así que'', ''por lo tanto''.","Para cerrar un texto o una idea: ''en conclusión'', ''para terminar''."]'::jsonb, '["Usar ''pero'' y ''sin embargo'' indistintamente: ''pero'' une dos ideas contrastantes, mientras que ''sin embargo'' es más formal y se usa generalmente al inicio de la oración.","Confundir ''además'' con ''también'': ''además'' se usa para añadir una idea nueva, mientras que ''también'' indica que algo se aplica a otra cosa.","Olvidar la coma después de conectores como ''sin embargo'', ''en conclusión'' cuando están al inicio de la oración.","No diferenciar entre ''porque'' (causa) y ''así que'' (consecuencia): ''porque'' introduce la razón, ''así que'' introduce el resultado."]'::jsonb, '["Em espanhol, os conectivos são essenciais para a coesão textual. Preste atenção à pontuação: quando o conector está no início da frase, usa-se vírgula.","Os conectores de contraste como ''sin embargo'' e ''en cambio'' podem ficar no início ou no meio da oração, mas a vírgula é obrigatória quando estão no início.","Muitos conectores são intercambiáveis, mas o nível de formalidade muda: ''pero'' é mais coloquial, ''sin embargo'' é mais formal.","Lembre-se de que ''también'' pode ser usado para concordar com uma opinião, enquanto ''además'' adiciona uma ideia nova.","Pratique a pronúncia dos conectores, pois eles ajudam a dar fluidez à fala e à escrita."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

