insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-7ebdfd37c0d5', 'es', 'B1', 'Reported Speech (Discurso Indireto)', 'Nesta lição, você aprenderá a relatar o que outras pessoas disseram, usando o discurso indireto em espanhol. Vamos ver como transformar frases diretas em indiretas, ajustando os tempos verbais, pronomes e expressões de tempo e lugar.', 'Para formar o discurso indireto, geralmente usamos um verbo introdutório como ''decir'', ''preguntar'', ''pedir'', etc., seguido de ''que''. Os tempos verbais mudam de acordo com o tempo do verbo introdutório: se for presente, o tempo do verbo original não muda; se for passado (pretérito), ocorrem mudanças (ex.: presente vira pretérito imperfeito, pretérito perfeito vira pretérito pluscuamperfecto, futuro vira condicional). Os pronomes e possessivos também mudam para refletir a perspectiva do falante.', '["Relatar afirmações: Ela disse que estava cansada.","Relatar perguntas: Ele perguntou se eu tinha tempo.","Relatar pedidos: Pediram que eu fechasse a porta.","Relatar informações ouvidas: O professor explicou que a prova seria na sexta."]'::jsonb, '["Não mudar o tempo verbal quando o verbo introdutório está no passado.","Esquecer de ajustar os pronomes (ex.: ''yo'' vira ''él/ella'').","Confundir a ordem das palavras em perguntas indiretas (não inverter sujeito e verbo).","Usar ''que'' em perguntas indiretas que começam com palavra interrogativa (ex.: ''preguntó qué hora era'', não ''preguntó que qué hora era'')."]'::jsonb, '["No discurso indireto, os tempos mais comuns que mudam são: presente → pretérito imperfeito, pretérito perfeito → pretérito pluscuamperfecto, futuro simples → condicional simples.","Expressões de tempo e lugar também mudam: ''hoy'' → ''ese día'', ''ayer'' → ''el día anterior'', ''aquí'' → ''allí''.","As perguntas indiretas com resposta sim/não usam ''si'' após o verbo introdutório.","Os pedidos e ordens são frequentemente expressos com ''que'' + subjuntivo.","Em espanhol, é comum omitir o ''que'' em alguns contextos informais, mas na forma escrita é preferível usar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

