insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-fe32134c6657', 'es', 'B1', 'Conectores del discurso (B1)', 'Os conectores do discurso são palavras ou expressões que usamos para ligar ideias e organizar o texto, tornando a comunicação mais clara e fluida. Nesta lição, você vai aprender conectores comuns para adicionar informações, contrastar ideias, explicar causas e consequências, e ordenar eventos.', 'Os conectores podem ser palavras únicas (como ''pero'', ''además'') ou expressões com várias palavras (como ''sin embargo'', ''por lo tanto''). Eles aparecem geralmente no início de uma oração, seguidos de vírgula quando introduzem uma ideia nova. Por exemplo: ''Quiero viajar. Sin embargo, no tengo dinero.'' Também podem aparecer no meio da frase: ''Estudió mucho, así que aprobó.''', '["Para adicionar informação: ''y'', ''además'', ''también''.","Para contrastar ideias: ''pero'', ''sin embargo'', ''aunque''.","Para expressar causa: ''porque'', ''ya que'', ''debido a que''.","Para expressar consequência: ''por eso'', ''así que'', ''por lo tanto''.","Para ordenar ideias: ''primero'', ''después'', ''finalmente''."]'::jsonb, '["Usar ''pero'' e ''sin embargo'' juntos: ''pero sin embargo'' (incorreto).","Colocar vírgula depois de ''porque'' quando está no meio da frase: ''No fui porque, estaba enfermo'' (incorreto).","Confundir ''sino'' com ''si no'': ''No es rojo, sino azul'' vs. ''Si no estudias, fallarás''.","Usar ''además'' para iniciar uma frase com verbo no subjuntivo (incorreto)."]'::jsonb, '["Os conectores são invariáveis, ou seja, não mudam de forma.","Em textos formais, prefira ''sin embargo'' a ''pero''.","''Aunque'' pode ser seguido de indicativo ou subjuntivo, dependendo do sentido.","Pratique a entonação: pausa após conectores no início da frase."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

