insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-6f05c2740b8c', 'es', 'B1', 'Uso frecuente del presente de subjuntivo', 'Nesta lição, você vai aprender os usos mais comuns do presente de subjuntivo em espanhol, um tempo verbal essencial para expressar desejos, dúvidas, emoções e situações hipotéticas. Vamos focar em contextos do dia a dia para que você possa usar o subjuntivo com confiança.', 'Para formar o presente de subjuntivo, pegue a primeira pessoa do singular (yo) do presente do indicativo, remova a terminação -o e adicione as terminações do subjuntivo: para verbos -ar: -e, -es, -e, -emos, -éis, -en; para verbos -er/-ir: -a, -as, -a, -amos, -áis, -an. Verbos irregulares têm formas próprias, como ''sea'' (ser), ''esté'' (estar), ''haga'' (hacer), ''tenga'' (tener), ''vaya'' (ir).', '["Expressar desejos e vontades: Espero que você tenha um bom dia.","Expressar dúvidas ou negação: Não creio que ele venha.","Expressar sentimentos e emoções: Me alegro de que você esteja aqui.","Expressar opiniões pessoais (em orações com ''es + adjetivo''): É importante que você estude.","Expressar finalidade com ''para que'': Falo alto para que todos ouçam."]'::jsonb, '["Usar o indicativo após ''espero que'': Errado: ''Espero que você vem.'' Correto: ''Espero que você venha.''","Confundir ''para'' com ''para que'': Use subjuntivo com ''para que'', e não com ''para''.","Esquecer de usar subjuntivo após ''cuando'' para futuro: Use subjuntivo quando a ação ainda não aconteceu: ''Cuando llegue, me llama.''","Usar subjuntivo após ''creo que'' sem negação: Use indicativo para crenças positivas: ''Creo que es verdad.'' Use subjuntivo na negativa: ''No creo que sea verdad.''"]'::jsonb, '["Em espanhol, o subjuntivo é usado mais frequentemente do que em português.","Preste atenção aos gatilhos: expressões de desejo, dúvida, emoção e impessoais.","Aprenda as formas irregulares mais comuns, pois aparecem com frequência."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

