insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-96fb75f80894', 'es', 'B1', 'El Imperativo Ampliado: Instrucciones, Consejos y Sugerencias', 'Nesta lição, você vai aprender a usar o imperativo em espanhol de forma mais ampla e natural. Além das formas básicas (tú, usted, nosotros, vosotros, ustedes), vamos explorar como dar instruções, conselhos e sugestões de maneira educada, usando também o imperativo com pronomes e formas negativas. Isso vai ajudar você a se comunicar melhor em situações do dia a dia, como dar direções, recomendar lugares e expressar opiniões.', 'O imperativo é formado de maneiras diferentes dependendo do pronome. Para ''tú'', a forma afirmativa é igual à 3ª pessoa do singular do presente do indicativo (ex.: ''habla'', ''come'', ''escribe''). Para ''usted'' e ''ustedes'', usamos as formas do presente do subjuntivo (ex.: ''hable'', ''hablen''). Para ''nosotros'', usamos ''vamos a'' + infinitivo ou a forma do subjuntivo (ex.: ''hablemos''). Para ''vosotros'', substituímos o ''r'' final do infinitivo por ''d'' (ex.: ''hablad'', ''comed''). Nas formas negativas, usamos sempre o subjuntivo: ''no hables'', ''no hable'', ''no hablemos'', ''no habléis'', ''no hablen''. Além disso, podemos incluir pronomes átonos (me, te, lo, la, le, nos, os, les) antes ou depois do verbo, dependendo se é afirmativo ou negativo. Por exemplo, ''dímelo'' (diga-mo) vs ''no me lo digas'' (não me diga).', '["Dar instruções passo a passo, como em receitas de culinária ou uso de aparelhos.","Oferecer conselhos e sugestões, como em ''Descansa más'' ou ''Prueba este restaurante''.","Dar ordens ou comandos em situações de emergência, como ''Llama a la policía''.","Fazer convites ou sugestões de forma mais direta, como ''Ven con nosotros''.","Dar permissão, como em ''Pasa, por favor''."]'::jsonb, '["Confundir as formas afirmativa e negativa para ''tú'': ''No habla'' em vez de ''No hables''.","Esquecer de usar o subjuntivo após ''no'' para outras pessoas: ''No come'' em vez de ''No comas''.","Colocar o pronome incorretamente: ''Me diga'' em vez de ''Dígame'' no afirmativo, e ''No dígame'' em vez de ''No me diga'' no negativo.","Usar ''vosotros'' em contextos formais ou da América Latina, onde se usa ''ustedes''."]'::jsonb, '["No espanhol da América Latina, ''vosotros'' é raramente usado; prefira ''ustedes''.","Em contextos formais ou para demonstrar educação, use ''usted'' e ''ustedes'' com frequência.","Lembre-se de que a entonação da voz é importante para transmitir polidez, especialmente com imperativos.","O imperativo pode ser suavizado com expressões como ''por favor'', ''si no es mucha molestia''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

