insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-df516b32ede9', 'es', 'B1', 'Reported Speech in Spanish (B1)', 'No discurso relatado, transmitimos o que alguém disse sem usar aspas. Em espanhol, usamos verbos como "decir", "preguntar", "pedir" e mudamos os pronomes, tempos verbais e expressões de tempo e lugar. Este tópico ajuda você a contar histórias e relatar conversas de forma natural.', 'Para formar o discurso relatado, geralmente mudamos o verbo principal para o pretérito (passado) e ajustamos o resto da frase. Se o verbo introdutório está no presente (dice, pregunta, pide), os tempos não mudam muito. Se está no passado (dijo, preguntó, pidió), os tempos recuam: presente vira pretérito imperfecto ou indefinido, futuro vira condicional, etc. Também alteramos pronomes e expressões como ''hoy'' para ''ese día''.', '["Relatar o que alguém disse, perguntou ou pediu.","Contar notícias ou informações que ouvimos.","Transmitir conselhos, ordens ou sugestões.","Expressar o que pensamos ou acreditamos que outros disseram.","Em narrativas, para reportar diálogos e pensamentos."]'::jsonb, '["Não mudar os tempos verbais quando o verbo introdutório está no passado.","Manter os pronomes originais em vez de ajustá-los ao contexto.","Usar ''que'' incorretamente: em perguntas indiretas, não se usa ''que'' sozinho, mas sim ''si'' ou palavras interrogativas.","Esquecer de mudar expressões de tempo e lugar (ex.: ''ahora'' -> ''entonces'').","Confundir o uso de ''decir'' e ''contar''."]'::jsonb, '["Quando o verbo introdutório está no presente, o tempo do verbo subordinado geralmente não muda: ''Dice que está cansado''.","Nas perguntas indiretas, a ordem das palavras é de afirmação, não de pergunta.","Se a informação relatada ainda é verdadeira, podemos manter o tempo original em alguns contextos.","O discurso relatado é comum em notícias e textos escritos.","Verbos como ''decir'', ''explicar'', ''responder'', ''gritar'' são comuns.","Para ordens, usamos a estrutura: ''Me dijo que + subjuntivo''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-df516b32ede9-exercise-01', 'es', 'B1', 'Presente para pretérito', 'Quando o verbo introdutório está no passado, o presente muda para pretérito imperfecto ou indefinido. Aqui, usamos imperfecto para expressar uma ação contínua.', 'Directo: ''Estoy cansado.'' -> Relatado: ''Dijo que estaba cansado.''', 'Transforme para o discurso relatado: ''Ana dice: ''Vivo en São Paulo.''', '["Ana dijo que vivo en São Paulo.","Ana dijo que vivía en São Paulo.","Ana dijo que vivió en São Paulo.","Ana dice que vivía en São Paulo."]'::jsonb, 1, 1, true, 'generated-grammar-es-b1-df516b32ede9')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-df516b32ede9-exercise-02', 'es', 'B1', 'Futuro para condicional', 'No discurso relatado com verbo introdutório no passado, o futuro vira condicional.', 'Directo: ''Iré mañana.'' -> Relatado: ''Dijo que iría al día siguiente.''', 'Transforme: ''Pedro dice: ''Terminaré el proyecto.''', '["Pedro dijo que termina el proyecto.","Pedro dijo que terminará el proyecto.","Pedro dijo que terminaría el proyecto.","Pedro dice que terminaría el proyecto."]'::jsonb, 2, 2, true, 'generated-grammar-es-b1-df516b32ede9')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-df516b32ede9-exercise-03', 'es', 'B1', 'Pergunta indireta', 'Em perguntas indiretas, usamos ''si'' para perguntas de sim/não e palavras interrogativas; a ordem é de afirmação.', 'Directo: ''¿Dónde vives?'' -> Relatado: ''Me preguntó dónde vivía.''', 'Transforme: ''María pregunta: ''¿Tienes hambre?''', '["María preguntó si tenía hambre.","María preguntó que tenía hambre.","María preguntó si tienes hambre.","María pregunta si tenía hambre."]'::jsonb, 0, 3, true, 'generated-grammar-es-b1-df516b32ede9')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-df516b32ede9-exercise-04', 'es', 'B1', 'Mudança de pronomes', 'Ajustar os pronomes de acordo com o contexto do relato.', 'Directo: ''Yo quiero café.'' -> Relatado: ''Dijo que él quería café.''', 'Transforme: ''Carlos dice: ''Yo no puedo venir.''', '["Carlos dijo que yo no podía venir.","Carlos dijo que él no podía venir.","Carlos dijo que no puede venir.","Carlos dice que él no podía venir."]'::jsonb, 1, 4, true, 'generated-grammar-es-b1-df516b32ede9')
