insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-df516b32ede9-exercise-05', 'es', 'B1', 'Expressões de tempo', 'Expressões de tempo mudam no discurso relatado: ''hoy'' vira ''ese día'', ''mañana'' vira ''el día siguiente''.', 'Directo: ''Hoy es lunes.'' -> Relatado: ''Dijo que ese día era lunes.''', 'Transforme: ''Ellos dicen: ''Mañana viajaremos.''', '["Ellos dijeron que mañana viajarían.","Ellos dijeron que el día siguiente viajarían.","Ellos dijeron que al día siguiente viajarían.","Ellos dijeron que ese día viajarían."]'::jsonb, 2, 5, true, 'generated-grammar-es-b1-df516b32ede9')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-d7fc0ba32422', 'es', 'B1', 'Voz Pasiva e Impersonal con ''Se''', 'Nesta lição, você vai aprender a usar a voz passiva e as construções impessoais com ''se'' em espanhol. Essas estruturas são muito comuns para falar de ações sem dizer quem as faz, ou para dar informações gerais.', 'A voz passiva com ''ser'' é formada com o verbo ''ser'' no tempo desejado + particípio passado, concordando com o sujeito. Exemplo: ''La casa es construida'' (A casa é construída). Já o ''se'' impessoal usa ''se'' + verbo na terceira pessoa (singular ou plural). Exemplo: ''Se habla español'' (Fala-se espanhol).', '["Para falar de ações sem mencionar quem as faz: ''Se vende ropa''.","Para dar informações gerais: ''Se dice que...'' (Diz-se que...).","Na passiva com ''ser'', quando queremos dar ênfase ao objeto: ''El libro fue escrito por él''.","Em notícias e manchetes para impessoalizar: ''Se ha encontrado un tesoro''."]'::jsonb, '["Usar ''es'' com ''se'' junto: ''Se es habla'' (incorreto). O correto é ''Se habla''.","Confundir o ''se'' impessoal com o reflexivo. No impessoal, não há pessoa específica agindo.","Esquecer a concordância na passiva: ''Las casas son construidas'' (não ''es construidas'').","Usar a passiva com ''ser'' onde o espanhol prefere o ''se'': ''La puerta es abierta'' (soa estranho; melhor ''La puerta se abre'')."]'::jsonb, '["O ''se'' impessoal é muito comum no espanhol, especialmente em instruções e placas.","Na passiva com ''ser'', o particípio concorda em gênero e número com o sujeito.","Em frases com ''se'' impessoal, o verbo pode estar no singular ou plural, dependendo do objeto: ''Se vende casa'' (singular) e ''Se venden casas'' (plural)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

