insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-ed61e1562931', 'es', 'B1', 'Conectores del discurso en español (B1)', 'En esta lección, aprenderás a usar los conectores del discurso para unir ideas, organizar tu texto y hacer tu comunicación más clara y fluida.', 'Los conectores son palabras o frases que enlazan oraciones y párrafos. Los clasificamos según su función: aditivos (y, además), adversativos (pero, sin embargo), causales (porque, ya que), consecutivos (así que, por lo tanto), y ordenadores (primero, luego, finalmente).', '["Para añadir información: ''Me gusta el español y también el portugués.''","Para contrastar ideas: ''Quería salir, pero llovía.''","Para expresar causa: ''No fui porque estaba enfermo.''","Para expresar consecuencia: ''Estudiaste mucho, así que aprobarás.''","Para ordenar el discurso: ''Primero, prepara los ingredientes; luego, mézclalos.''"]'::jsonb, '["Confundir ''sino'' con ''si no''.","Usar ''pero'' en lugar de ''sino'' en oraciones negativas.","Colocar coma después de ''aunque'' cuando es innecesaria.","Usar ''porque'' en lugar de ''por qué'' en preguntas.","No usar coma antes de ''y'' cuando se enumeran más de dos elementos."]'::jsonb, '["Os conectores são essenciais para a coesão textual.","Na escrita formal, evite começar frases com ''y''.","Pratique usando conectores em conversas do dia a dia."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

