insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-b04a7c14ee4b', 'es', 'B1', 'Pretérito Perfecto vs. Pretérito Indefinido', 'Nesta lição, vamos comparar dois tempos passados em espanhol: o pretérito perfecto e o pretérito indefinido. Você vai aprender quando usar cada um deles, como formá-los e evitar erros comuns.', 'O pretérito perfecto é formado com o verbo ''haber'' no presente + particípio passado (ex: he hablado, has comido, ha vivido). O pretérito indefinido tem terminações próprias para verbos regulares e irregulares (ex: hablé, comí, viví; fui, estuve, tuve).', '["Pretérito perfecto para ações em um período de tempo que ainda não terminou (hoje, esta semana, este ano).","Pretérito perfecto para experiências de vida sem especificar quando.","Pretérito indefinido para ações concluídas em um momento específico do passado (ontem, semana passada, em 2010).","Pretérito indefinido para narrar eventos sequenciais no passado."]'::jsonb, '["Usar o pretérito perfecto com marcadores de tempo específicos como ''ayer'' ou ''la semana pasada''.","Confundir ''he estado'' (estive/permaneci) com ''estuve''.","Usar o pretérito indefinido para experiências sem menção de tempo.","Esquecer que ''hoy'' pode usar pretérito perfecto, mas se a ação acabou de terminar."]'::jsonb, '["Na Espanha, o pretérito perfecto é mais usado que na América Latina para ações recentes.","No Brasil, o pretérito perfeito composto (tenho feito) é diferente do pretérito perfecto em espanhol.","Preste atenção aos verbos irregulares comuns: fui, vi, di, hice, tuve, estuve, pude, puse, supe, anduve, quisve, vine."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

