insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-447b326205a3', 'es', 'B1', 'O Subjuntivo Presente: Usos Frequentes', 'O modo subjuntivo é usado em espanhol para expressar desejos, dúvidas, emoções, e ações futuras incertas. Nesta unidade, vamos focar nos usos mais frequentes do presente do subjuntivo, especialmente após expressões impessoais, verbos de vontade e em orações relativas.', 'Para formar o presente do subjuntivo, pegue a primeira pessoa do singular (yo) do presente do indicativo, retire a terminação -o, e adicione as terminações: para verbos -ar: -e, -es, -e, -emos, -éis, -en; para verbos -er/-ir: -a, -as, -a, -amos, -áis, -an. Exemplos: hablar -> hable, hables, hable, hablemos, habléis, hablen; comer -> coma, comas, coma, comamos, comáis, coman; vivir -> viva, vivas, viva, vivamos, viváis, vivan. Verbos irregulares comuns: ser -> sea, esté, haya, vaya, tenga, etc.', '["Após expressões impessoais como ''es importante que'', ''es necesario que'', ''es posible que''.","Após verbos de vontade, desejo ou influência, como ''querer que'', ''desear que'', ''pedir que''.","Em orações relativas para indicar algo incerto ou inexistente, por exemplo, ''busco un libro que sea interesante''.","Após conjunções temporais para expressar futuro, como ''cuando'', ''hasta que'', ''en cuanto''.","Para expressar emoções: ''me alegra que'', ''me preocupa que'', ''siento que''."]'::jsonb, '["Usar o indicativo após ''es importante que'' em vez do subjuntivo.","Confundir as terminações entre verbos -ar e -er/-ir.","Esquecer que ''cuando'' é seguido de subjuntivo quando se refere ao futuro.","Usar ''para que'' com indicativo em vez de subjuntivo."]'::jsonb, '["O subjuntivo não é um tempo, mas um modo, portanto pode ser usado no presente, passado, etc.","Em frases afirmativas e negativas, o subjuntivo aparece em contextos diferentes.","Alguns verbos têm subjuntivo irregular, como ''tener'' (tenga) e ''decir'' (diga).","É comum usar o subjuntivo em cláusulas que começam com ''que'' após certos verbos e expressões."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

