insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-e47b4ff5e453', 'es', 'B1', 'El imperativo expandido: órdenes y sugerencias con pronombres', 'Nesta aula, você vai aprender a usar o imperativo expandido em espanhol, que inclui formas com pronomes átonos (me, te, lo, la, nos, os, les) e combinações com ''usted/ustedes''. Vamos ver como dar ordens, conselhos e sugestões de forma mais natural e fluente, além de conhecer as formas negativas e as irregularidades mais comuns.', 'O imperativo afirmativo para ''tú'' usa a terceira pessoa do singular do presente do indicativo (e.g., ''habla'', ''come'', ''vive''), para ''vosotros'' substitui-se o ''r'' final do infinitivo por ''d'' (e.g., ''hablad''). Para ''usted'' e ''ustedes'', usa-se a forma do presente do subjuntivo (e.g., ''hable'', ''hablen''). Nas formas negativas, usa-se o presente do subjuntivo para todas as pessoas. Os pronomes átonos são ligados ao verbo no afirmativo (e.g., ''dime'') e colocados antes no negativo (e.g., ''no me digas'').', '["Dar instruções diretas: ''Limpia la casa antes de salir''.","Fazer pedidos educados com ''usted'': ''Siéntese, por favor''.","Aconselhar: ''Descansa un poco''.","Dar ordens negativas: ''No comas tanta azúcar''.","Combinar com pronomes: ''Tráeme un café'' ou ''No me molestes''."]'::jsonb, '["Usar o infinitivo após ''no'' em vez do subjuntivo: ''No fumar'' em vez de ''No fumes''.","Colocar o pronome depois do verbo no negativo: ''Dime no'' em vez de ''No me digas''.","Confundir as formas de ''tú'' e ''usted'': ''Habla'' vs. ''Hable''.","Esquecer a irregularidade em ''ver'': ''Ve'' (tú) e ''Vea'' (usted)."]'::jsonb, '["No imperativo afirmativo, o pronome é anexado ao verbo, mas no negativo fica separado.","As formas de ''vosotros'' são menos usadas na América Latina, onde se prefere ''ustedes''.","Alguns verbos têm irregularidades no imperativo, como ''hacer'' -> ''haz'' e ''poner'' -> ''pon''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

