insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-0e5f8b3d823b', 'es', 'B1', 'Discurso Indirecto en Español', 'O discurso indireto é usado para relatar o que alguém disse sem usar aspas. Em espanhol, é muito comum em conversas do dia a dia, notícias e narrativas. Neste tópico, você aprenderá a transformar frases do discurso direto para o indireto, fazendo os ajustes necessários nos pronomes, tempos verbais e expressões de tempo e lugar.', 'Para formar o discurso indireto, geralmente usamos um verbo introdutor como ''decir'', ''preguntar'', ''contar'' ou ''explicar''. Depois, fazemos as seguintes mudanças: 1) Se o verbo introdutor está no presente (dice, pregunta), o tempo verbal da frase original não muda. 2) Se está no passado (dijo, preguntó), geralmente mudamos o tempo: presente vira pretérito imperfecto, futuro vira condicional, pretérito perfeito vira pretérito pluscuamperfecto. 3) Mudamos os pronomes pessoais e possessivos para concordar com a pessoa que relata. 4) Ajustamos expressões de tempo e lugar (hoy -> ese día, aquí -> allí).', '["Para relatar uma fala ou notícia: ''Ella dijo que estaba cansada.''","Para transmitir perguntas: ''Me preguntó si quería café.''","Para reportar ordens ou pedidos: ''El profesor nos pidió que hiciéramos la tarea.''","Para expressar o que alguém pensa ou acredita: ''Juan cree que mañana va a llover.''"]'::jsonb, '["Esquecer de mudar o tempo verbal quando o verbo introdutor está no passado: ''Dijo que está cansado'' (incorreto) -> ''Dijo que estaba cansado'' (correto).","Manter os pronomes originais sem ajuste: ''María dijo: Yo quiero ir'' -> ''María dijo que ella quería ir'', não ''dijo que yo quería ir''.","Confundir as expressões de tempo: mudar ''hoy'' para ''ese día'', ''mañana'' para ''el día siguiente'', etc.","Usar ''que'' incorretamente em perguntas indiretas: ''Preguntó qué queríamos'' (não ''que queríamos'' sem acento)."]'::jsonb, '["Em perguntas indiretas, usamos ''si'' para perguntas de sim/não e palavras interrogativas (qué, dónde, cuándo) para perguntas abertas, sem inverter sujeito e verbo.","Quando o verbo introdutor está no presente, o discurso indireto pode ser feito sem mudanças drásticas, mas ainda ajustamos pronomes e expressões temporais se necessário.","O imperativo no discurso direto se transforma em subjuntivo no indireto: ''Me dijo: Hazlo'' -> ''Me dijo que lo hiciera''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-0e5f8b3d823b-exercise-01', 'es', 'B1', 'Transformando presente para passado', 'Quando o verbo introdutor ''dice'' está no presente, o tempo verbal da frase original pode ser mantido. No entanto, quando usamos ''dijo'' passado, devemos mudar o presente para o pretérito imperfecto.', 'Directo: dice: ''Estoy cansado.'' -> Indirecto: Dice que está cansado. / Directo: dijo: ''Estoy cansado.'' -> Indirecto: Dijo que estaba cansado.', 'Transforme a frase para o discurso indireto, começando com ''Dijo que...'': ''Estoy enfermo.''', '["Dijo que está enfermo.","Dijo que estaba enfermo.","Dijo que estará enfermo.","Dijo que estuvo enfermo."]'::jsonb, 1, 1, true, 'generated-grammar-es-b1-0e5f8b3d823b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-0e5f8b3d823b-exercise-02', 'es', 'B1', 'Ajustando pronomes e possessivos', 'No discurso indireto, os pronomes pessoais e possessivos devem mudar para refletir a perspectiva de quem relata. Exemplo: ''Yo'' pode virar ''él'' ou ''ella''.', 'Directo: ''Yo quiero mi libro.'' -> Indirecto: Dijo que él quería su libro.', 'Transforme: ''Yo compré mi casa.'' começando com ''Ella dijo que...''', '["Ella dijo que yo compré mi casa.","Ella dijo que ella compró su casa.","Ella dijo que compré su casa.","Ella dijo que compró mi casa."]'::jsonb, 1, 2, true, 'generated-grammar-es-b1-0e5f8b3d823b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-0e5f8b3d823b-exercise-03', 'es', 'B1', 'Transformando perguntas', 'Para perguntas no discurso indireto, usamos ''si'' para perguntas de sim/não e a palavra interrogativa correspondente para outras. A ordem da frase torna-se afirmativa.', 'Directo: ''¿Tienes hambre?'' -> Indirecto: Me preguntó si tenía hambre.', 'Transforme: ''¿Dónde vives?'' começando com ''Me preguntó...''', '["Me preguntó dónde vivía.","Me preguntó dónde vives.","Me preguntó si vivía.","Me preguntó que dónde vivía."]'::jsonb, 0, 3, true, 'generated-grammar-es-b1-0e5f8b3d823b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-0e5f8b3d823b-exercise-04', 'es', 'B1', 'Mudando expressões de tempo e lugar', 'Expressões como ''hoy'', ''mañana'', ''aquí'' mudam no discurso indireto: ''hoy'' -> ''ese día'', ''mañana'' -> ''el día siguiente'', ''aquí'' -> ''allí''.', 'Directo: ''Hoy estoy aquí.'' -> Indirecto: Dijo que ese día estaba allí.', 'Transforme: ''Mañana iré al cine.'' começando com ''Dijo que...''', '["Dijo que mañana iría al cine.","Dijo que el día siguiente iría al cine.","Dijo que el día siguiente va al cine.","Dijo que mañana irá al cine."]'::jsonb, 1, 4, true, 'generated-grammar-es-b1-0e5f8b3d823b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b1-0e5f8b3d823b-exercise-05', 'es', 'B1', 'Transformando ordens e pedidos', 'Para ordens ou pedidos, usamos ''que'' + subjuntivo. O imperativo original se transforma em subjuntivo.', 'Directo: ''¡Cierra la puerta!'' -> Indirecto: Me dijo que cerrara la puerta.', 'Transforme: ''No fume aquí.'' (ordem) começando com ''El médico me dijo que...''', '["El médico me dijo que no fumara allí.","El médico me dijo que no fume aquí.","El médico me dijo que no fumo aquí.","El médico me dijo que no fumar allí."]'::jsonb, 0, 5, true, 'generated-grammar-es-b1-0e5f8b3d823b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-b95188f11924', 'es', 'B1', 'La voz pasiva y el ''se'' impersonal', 'Nesta unidade, você vai aprender a usar a voz passiva e o ''se'' impessoal em espanhol para falar de ações sem mencionar quem as realiza. Isso é muito útil em contextos formais, notícias, instruções e descrições de processos.', 'A voz passiva é formada com o verbo ''ser'' + particípio passado, concordando em gênero e número com o sujeito. O ''se'' impessoal é formado com ''se'' + verbo na terceira pessoa (singular ou plural), sem sujeito específico.', '["Para enfatizar a ação em vez do agente: ''El puente fue construido en 1900.'' (A ponte foi construída em 1900.)","Quando o agente é desconhecido ou irrelevante: ''Se habla español en muchos países.'' (Fala-se espanhol em muitos países.)","Em instruções e receitas: ''Se mezclan los ingredientes.'' (Misturam-se os ingredientes.)","Em notícias e textos formais: ''Fue anunciado el nuevo plan.'' (Foi anunciado o novo plano.)","Para generalizações: ''Se dice que...'' (Diz-se que...)","Em processos industriais ou científicos: ''El hierro se extrae de la mina.'' (O ferro é extraído da mina.)"]'::jsonb, '["Confundir o particípio com o pretérito: ''es escribido'' em vez de ''es escrito''.","Não concordar o particípio com o sujeito: ''Los libros fue publicados'' em vez de ''Los libros fueron publicados''.","Usar ''se'' com verbos que não aceitam: ''se gusto'' em vez de ''me gusta''.","Omitir o ''se'' em construção impessoal: ''vende casas'' em vez de ''se venden casas''.","Usar a voz passiva quando o impessoal é mais natural: ''La carta fue escrita por mí'' em vez de ''escribí la carta''.","Traduzir literalmente do português: ''se hace'' pode ser ''faz-se'' ou ''é feito''."]'::jsonb, '["No espanhol, o particípio passado regular termina em -ado/-ido, mas há muitos irregulares que devem ser memorizados.","A voz passiva é menos comum no espanhol falado do que no português; prefere-se a voz ativa ou o ''se'' impessoal.","O ''se'' impessoal é usado apenas com verbos transitivos; para intransitivos usa-se a terceira pessoa do plural.","Com o ''se'' impessoal, o objeto direto concorda com o verbo: ''Se venden flores.'' (Flores é o sujeito).","A preposição ''por'' introduz o agente da passiva: ''La casa fue vendida por mi abuela.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

