values ('generated-grammar-es-b1-27ae025420ad-exercise-03', 'es', 'B1', 'Escolha a opção que expressa contraste', 'Qual conector ou expressão indica oposição de ideias?', 'Ejemplo: ''Aunque es tarde, me quedo.'' ''Aunque'' expressa contraste.', '¿Qué opción expresa contraste?', '["porque","aunque","por eso","también"]'::jsonb, 1, 3, true, 'generated-grammar-es-b1-27ae025420ad')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

