insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-00a21a1ab1bc', 'es', 'B1', 'O Presente do Subjuntivo: Usos Frequentes', 'O presente do subjuntivo em espanhol é um tempo verbal fundamental para expressar desejos, dúvidas, emoções, conselhos e situações hipotéticas. Nesta lição, você aprenderá as formas regulares e irregulares e os usos mais comuns no nível B1, com exemplos práticos para o dia a dia.', 'Para formar o presente do subjuntivo, pegue a primeira pessoa do singular (yo) do presente do indicativo, remova a terminação ''-o'' e adicione as terminações específicas: para verbos ''-ar'': -e, -es, -e, -emos, -éis, -en; para verbos ''-er'' e ''-ir'': -a, -as, -a, -amos, -áis, -an. Exemplos: ''hablar'' (yo hablo) -> hable, hables, hable, hablemos, habléis, hablen. ''comer'' (yo como) -> coma, comas, coma, comamos, comáis, coman. ''vivir'' (yo vivo) -> viva, vivas, viva, vivamos, viváis, vivan. Verbos irregulares: ''tener'' -> tenga, tengas...; ''hacer'' -> haga, hagas...; ''ir'' -> vaya, vayas...; ''ser'' -> sea, seas...; ''estar'' -> esté, estés...', '["Expressar desejos e esperanças: Espero que você tenha um bom dia.","Expressar dúvidas e negação: Não creio que ele venha hoje.","Expressar emoções e sentimentos: Me alegro de que você esteja bem.","Dar conselhos e recomendações: Recomendo que você estude mais.","Expressar opiniões negativas: Não me parece que seja uma boa ideia."]'::jsonb, '["Usar o indicativo após ''espero que'' em vez do subjuntivo.","Confundir as formas do subjuntivo com as do indicativo.","Usar o subjuntivo depois de ''creo que'' em frases afirmativas.","Esquecer de usar o subjuntivo após ''cuando'' para ações futuras."]'::jsonb, '["O subjuntivo também é usado em cláusulas adjetivas com antecedente indefinido ou negado.","Aprenda as conjunções que disparam o subjuntivo: ''cuando'', ''aunque'', ''para que'', ''antes de que'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

