insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b1-91d20951363a', 'es', 'B1', 'La Voz Pasiva y el ''Se'' Impersonal', 'Nesta lição, você vai aprender a usar a voz passiva e o ''se'' impessoal em espanhol. A voz passiva é usada para dar ênfase à ação ou ao objeto, e não à pessoa que realiza a ação. Já o ''se'' impessoal é uma construção muito comum para falar de ações de forma geral, sem especificar quem as realiza.', '1. **Voz Passiva com ''ser''**: [objeto] + [verbo ''ser'' conjugado] + [particípio passado] + [por + agente]. Exemplo: ''La carta fue escrita por María.'' (A carta foi escrita por Maria.)
2. **''Se'' Impessoal**: [se] + [verbo na 3ª pessoa do singular] + [objeto]. Exemplo: ''Se habla español en muchos países.'' (Fala-se espanhol em muitos países.)', '["Para enfatizar a ação ou o objeto em vez do agente.","Quando não se sabe ou não se quer dizer quem realiza a ação.","Para expressar regras gerais ou fatos.","Em textos formais, notícias e instruções."]'::jsonb, '["Confundir o ''se'' impessoal com o ''se'' reflexivo ou recíproco.","Usar a voz passiva com verbos intransitivos, como ''ir'' ou ''existir''.","Concordar incorretamente o particípio passado na voz passiva com ''ser''."]'::jsonb, '["Na voz passiva, o particípio concorda em gênero e número com o sujeito.","O ''se'' impessoal sempre leva o verbo na terceira pessoa do singular.","Em espanhol, a voz passiva com ''ser'' é menos comum do que em português; muitas vezes, prefere-se a construção com ''se'' ou a voz ativa.","O ''se'' impessoal pode ser usado com pronomes de objeto direto e indireto, por exemplo: ''Se les ve felices'' (Eles parecem felizes)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

