insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-7b55742a5081', 'fr', 'B1', 'Le Plus-que-Parfait : Introduction', 'O plus-que-parfait é um tempo verbal do passado usado para expressar uma ação que ocorreu antes de outra ação passada. Nesta introdução, você aprenderá como formá-lo e quando usá-lo para enriquecer suas narrativas em francês.', 'O plus-que-parfait é formado com o verbo auxiliar (avoir ou être) no imparfait, seguido do particípio passado do verbo principal. Por exemplo: ''J''avais mangé'' (Eu tinha comido). Com o verbo être, o particípio concorda em gênero e número com o sujeito: ''Elle était partie'' (Ela tinha partido).', '["Expressar uma ação passada anterior a outra ação passada (ex: Quand je suis arrivé, il avait déjà mangé.).","Descrever um estado ou situação que existia antes de um momento no passado (ex: Elle était fatiguée parce qu''elle avait beaucoup travaillé.).","Usar em relatos para indicar a causa de um evento passado (ex: Il était en retard car il avait raté le bus.)."]'::jsonb, '["Confundir o plus-que-parfait com o passé composé; o plus-que-parfait é usado para ações anteriores a outras ações passadas.","Escolher o auxiliar errado; lembre-se de que verbos de movimento e pronominais usam ''être''.","Esquecer a concordância do particípio passado com o sujeito quando o auxiliar é ''être''.","Usar o plus-que-parfait em ações simultâneas no passado; para isso, usa-se o imparfait."]'::jsonb, '["O plus-que-parfait é frequentemente usado em frases com ''quand'', ''lorsque'', ou ''après que''.","Na linguagem falada, é comum usar o plus-que-parfait para contar histórias ou explicar razões.","A forma negativa é feita com ''ne ... pas'' ao redor do auxiliar: ''Je n''avais pas vu''."]'::jsonb, 0, true)
