insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-79f77be3a9c1', 'fr', 'B1', 'Passé Composé vs Imparfait', 'Neste módulo, você vai aprender a diferença entre o passé composé e o imparfait, dois tempos verbais essenciais para contar histórias e descrever situações no passado em francês. Vamos ver quando usar cada um e como eles trabalham juntos para dar ritmo à narrativa. Prepare-se para dominar o passado em francês!', 'O passé composé é formado com o presente do verbo auxiliar (avoir ou être) + o particípio passado do verbo principal. Por exemplo, ''j''ai parlé'' (eu falei) ou ''elle est allée'' (ela foi). O imparfait é formado a partir da raiz do verbo na primeira pessoa do plural (nous) no presente, adicionando as terminações: -ais, -ais, -ait, -ions, -iez, -aient. Por exemplo, ''je parlais'' (eu falava), ''nous finissions'' (nós terminávamos), ''elle était'' (ela era/estava).', '["Passé composé para ações pontuais e concluídas: ''J''ai mangé une pomme''.","Passé composé para sequência de eventos: ''Il est entré, il a dit bonjour''.","Imparfait para descrições no passado: ''Il faisait beau''.","Imparfait para ações habituais ou repetidas: ''Quand j''étais petit, je jouais au foot''.","Imparfait para ações em progresso no passado: ''Je lisais quand tu as appelé''."]'::jsonb, '["Usar o imparfait para ações pontuais: ''Hier, je mangeais une pomme'' (errado) em vez de ''Hier, j''ai mangé une pomme''.","Usar o passé composé para descrições: ''La maison a été grande'' (errado) em vez de ''La maison était grande''.","Confundir o uso com ações simultâneas: ''Je regardais la télé quand le téléphone a sonné'' (correto).","Esquecer que alguns verbos usam ''être'' no passé composé: ''Elle est allée'' (não ''a allé'')."]'::jsonb, '["Em narrativas, o imparfait define o cenário e o passé composé avança a ação.","O passe composé pode ser usado para ações que aconteceram uma vez, enquanto o imparfait para ações repetidas.","O imparfait é frequentemente usado com expressões como ''souvent'', '' toujours'', ''chaque jour''.","O passé composé é usado com marcadores de tempo específicos: ''hier'', ''l''année dernière''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

