insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-5b6fc17f81cb', 'fr', 'B1', 'Introduction au Plus-que-parfait', 'O plus-que-parfait é um tempo composto do passado que expressa uma ação anterior a outra ação passada. Nesta unidade, você vai aprender a formar e usar esse tempo para narrar eventos de forma mais rica e precisa.', 'O plus-que-parfait é formado com o auxiliar avoir ou être no imparfait, seguido do particípio passado do verbo principal. A escolha entre avoir e être segue as mesmas regras do passé composé: a maioria dos verbos usa avoir, mas alguns verbos de movimento e os pronominais usam être. Exemplos: ''j''avais mangé'' (eu tinha comido), ''elle était partie'' (ela tinha partido).', '["Indicar uma ação passada que ocorreu antes de outra ação passada: ''Quand je suis arrivé, il avait déjà fini.''","Expressar um fato passado com um resultado no passado: ''Elle était fatiguée parce qu''elle avait travaillé toute la journée.''","Falar de experiências passadas com ''déjà'': ''Nous avions déjà visité ce musée.''","Em relatos e narrativas para contextualizar ações anteriores: ''Le film avait commencé quand nous sommes entrés.''"]'::jsonb, '["Usar o passé composé no lugar do plus-que-parfait quando há duas ações passadas, uma anterior à outra.","Confundir a concordância do particípio com être: ex. ''elle est partie'' (passé composé) mas ''elle était partie'' (plus-que-parfait).","Esquecer de usar o imparfait do auxiliar: ex. ''j''avais fini'' e não ''j''ai eu fini'' (que é passé antérieur)."]'::jsonb, '["O plus-que-parfait equivale ao ''past perfect'' em inglês e é usado em contextos semelhantes.","Na forma negativa, o ''ne'' e o ''pas'' envolvem o auxiliar: ''je n''avais pas mangé''.","Na linguagem falada, é comum usar o passé composé no lugar do plus-que-parfait, mas ele é essencial na escrita formal."]'::jsonb, 0, true)
