insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-74ffb9c8a94c', 'fr', 'B1', 'Passé Composé vs Imparfait: Como Contar Histórias em Francês', 'No francês, para contar histórias no passado, usamos dois tempos principais: o passé composé e o imparfait. Eles têm funções diferentes: o imparfait descreve o cenário, hábitos e ações em andamento, enquanto o passé composé relata ações pontuais e concluídas. Dominar essa diferença é essencial para narrar experiências de forma clara e natural.', 'O passé composé é formado com o presente do verbo auxiliar (avoir ou être) + o particípio passado do verbo principal. Por exemplo: ''j''ai mangé'' (eu comi), ''elle est partie'' (ela saiu). O imparfait, por sua vez, é formado a partir da raiz da primeira pessoa do plural (nous) do presente, acrescentando as terminações: -ais, -ais, -ait, -ions, -iez, -aient. Por exemplo: ''je mangeais'' (eu comia), ''elle partait'' (ela saía).', '["Usamos o imparfait para descrever características, estados e condições no passado.","Usamos o imparfait para ações habituais ou repetidas no passado.","Usamos o imparfait para ações em progresso no passado (quando outra ação interrompe).","Usamos o passé composé para ações pontuais, únicas e concluídas.","Usamos o passé composé para uma sequência de eventos que avançam a narrativa.","Usamos o passé composé para ações que aconteceram em um momento definido."]'::jsonb, '["Confundir o uso: usar o passé composé para descrições ou hábitos, e o imparfait para ações concluídas.","Errar a formação do imparfait, esquecendo a raiz do ''nous'' no presente.","Errar a concordância do particípio passado com o sujeito quando o auxiliar é ''être''.","Usar o passé composé para ações simultâneas de longa duração.","Usar o imparfait para ações que aconteceram em um momento específico."]'::jsonb, '["Em francês, a escolha entre passé composé e imparfait muda o sentido da frase.","Para narrar, o imparfait estabelece o contexto, e o passé composé traz os eventos principais.","Alguns verbos têm particípios passados irregulares; é importante memorizá-los.","Na fala coloquial, o passé composé é mais usado que o passé simple."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

