insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-7a9a01bc3530', 'fr', 'B1', 'O Futuro e o Condicional em Francês', 'Nesta lição, você vai aprender a usar o futuro simples e o condicional presente em francês. O futuro é usado para falar de ações que acontecerão, enquanto o condicional expressa hipóteses, desejos e cortesia. Vamos explorar a formação e os usos, com exercícios para praticar.', 'Futuro simples: a maioria dos verbos usa o infinitivo + terminações (-ai, -as, -a, -ons, -ez, -ont). Exceções comuns: être → ser-, avoir → aur-, faire → fer-, aller → ir-, venir → viendr-. Condicional presente: usa o radical do futuro + terminações do imperfeito (-ais, -ais, -ait, -ions, -iez, -aient). Exemplos: parler → je parlerai, je parlerais; être → je serai, je serais.', '["Futuro: para ações futuras certas ou planejadas: ''Demain, je voyagerai à Paris.''","Condicional: para expressar cortesia: ''Je voudrais un café, s''il vous plaît.''","Condicional: para hipóteses com ''si'': ''Si j''avais le temps, je viendrais.''","Condicional: para conselhos: ''Tu devrais te reposer.''","Futuro: para previsões: ''Il fera beau demain.''"]'::jsonb, '["Confundir as terminações do futuro e do condicional (futuro: -ai, -as, -a; condicional: -ais, -ais, -ait).","Esquecer que o condicional usa o radical do futuro (ex.: ''je serais'', não ''je suis -ais'').","Usar o futuro após ''si'' em vez do presente: correto é ''Si je peux, je viendrai'', não ''Si je pourrai''."]'::jsonb, '["O futuro e o condicional são frequentemente usados em frases com ''quand'' e ''si''.","Alguns verbos têm radicais irregulares no futuro e no condicional (ex.: ''avoir'' → ''aur-'', ''être'' → ''ser-'').","Para formar o condicional, use o radical do futuro + terminações do imperfeito."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

