insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-fd5bdd0eca0e', 'fr', 'B1', 'Les pronoms relatifs composés (B1)', 'Neste nível, você vai aprender a usar os pronomes relativos compostos: lequel, auquel, duquel e suas variações (laquelle, lesquels, lesquelles, auxquels, auxquelles, desquels, desquelles). Esses pronomes substituem nomes de coisas ou pessoas e vêm sempre depois de uma preposição (à, de, avec, pour, etc.). Eles são essenciais para conectar ideias de forma mais natural e evitar repetições.', 'Para formar os pronomes relativos compostos, combine a preposição com o pronome relativo ''lequel'', que concorda em gênero e número com o substantivo que substitui. Veja a estrutura:

- Masculino singular: à + lequel = auquel; de + lequel = duquel; avec + lequel = avec lequel
- Feminino singular: à + laquelle = à laquelle; de + laquelle = de laquelle; avec + laquelle = avec laquelle
- Masculino plural: à + lesquels = auxquels; de + lesquels = desquels; avec + lesquels = avec lesquels
- Feminino plural: à + lesquelles = auxquelles; de + lesquelles = desquelles; avec + lesquelles = avec lesquelles

Exemplo: ''Le livre'' (masculino singular) → ''le livre auquel je pense''.', '["Para ligar uma frase a um objeto ou pessoa que já foi mencionado, quando há uma preposição (à, de, avec, pour, etc.). Exemplo: ''C''est le projet auquel je travaille.''","Depois de verbos ou adjetivos que exigem a preposição ''à'' ou ''de''. Exemplo: ''La ville dans laquelle j''habite est grande.''","Em situações formais ou escritas, para dar mais clareza e elegância à frase. Exemplo: ''Les personnes auxquelles je pense sont mes amis.''","Para expressar posse ou origem com ''duquel'' e suas variações. Exemplo: ''Le pays duquel je viens est le Brésil.''"]'::jsonb, '["Confundir ''auquel'' com ''au quel'' (a forma correta é junta, exceto com ''à laquelle'' que é separado).","Esquecer de fazer a concordância com o gênero e número do substantivo. Exemplo: ''la femme à lequel'' (errado) → ''la femme à laquelle'' (correto).","Trocar ''dont'' por ''duquel'' quando não há preposição. Exemplo: ''Le livre dont je parle'' (errado: ''duquel'').","Usar ''lequel'' sem preposição, quando se deve usar ''qui'' ou ''que''."]'::jsonb, '["Lembre-se de que ''lequel'' também pode ser usado como pronome interrogativo, mas aqui focamos no relativo.","Em francês falado, é comum usar ''que'' + preposição, mas em registros formais prefira os relativos compostos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

