insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-b1971ed86c7d', 'fr', 'B1', 'La voix passive au présent', 'A voz passiva é usada para focar na ação ou no objeto que recebe a ação, em vez de quem a realiza. No presente, ela é formada com o verbo ''être'' no presente + o particípio passado do verbo principal. Este tópico é essencial para entender textos jornalísticos, instruções e descrições de processos.', 'Para formar a voz passiva no presente, use: sujeito (que recebe a ação) + être (conjugado no presente) + particípio passado do verbo principal. O particípio concorda em gênero e número com o sujeito. Exemplos: ''Le livre est lu par Marie'' (O livro é lido por Marie). ''Les lettres sont écrites par Paul'' (As cartas são escritas por Paul).', '["Quando o agente é desconhecido ou irrelevante: ''La Tour Eiffel est visitée chaque année.''","Para enfatizar a ação ou o objeto: ''Le gâteau est préparé par le chef.''","Em descrições de processos: ''Le café est cultivé au Brésil.''","Em notícias e relatos: ''Le président est élu par le peuple.''"]'::jsonb, '["Confundir o particípio passado com o infinitivo: ''Le devoir est faire'' (errado) em vez de ''Le devoir est fait'' (correto).","Esquecer a concordância do particípio: ''Les fleurs sont cueillis'' (errado) em vez de ''Les fleurs sont cueillies'' (correto).","Usar o auxiliar ''avoir'' em vez de ''être'': ''Le livre a été lu'' é passado, não presente; no presente, use ''est lu''.","Inverter sujeito e objeto: ''Le chien est promené par le maître'' (errado) em vez de ''Le chien est promené par le maître'' (correto – sujeito é o cão).","Omitir o complemento agente quando necessário: ''La maison est construite'' pode ser válido, mas se o agente for importante, use ''par''."]'::jsonb, '["O particípio passado dos verbos regulares em -er termina em -é, em -ir termina em -i, e em -re termina em -u. Ex.: mangé, fini, vendu.","Os verbos pronominais usam ''être'' como auxiliar no passado composto, mas na voz passiva, ''être'' é sempre o auxiliar no presente.","Com os tempos compostos da voz passiva, use ''avoir été'' + particípio, mas isso é para outros níveis.","Para transformar uma frase ativa em passiva, o objeto direto da ativa vira sujeito da passiva e o sujeito da ativa vira complemento agente introduzido por ''par'' (ou ''de'' com certos verbos).","O complemento agente pode ser omitido se não for importante."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

