insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-71ef7643fd31', 'fr', 'B1', 'O Subjuntivo Presente em Francês', 'Neste módulo, você vai aprender a usar o subjuntivo presente em francês. O subjuntivo é um modo verbal usado para expressar dúvida, desejo, emoção, necessidade, e ações incertas. Para o nível B1, vamos focar nos usos mais frequentes, como depois de expressões como ''il faut que'', ''je veux que'', e depois de verbos de opinião na negativa, como ''ne pas penser que''.', 'O subjuntivo presente é formado a partir da 3ª pessoa do plural do presente do indicativo. Para verbos regulares, eliminamos a terminação ''-ent'' e adicionamos as terminações do subjuntivo: -e, -es, -e, -ions, -iez, -ent. Exemplo com ''parler'' (eles falam: ils parlent) → que je parle, que tu parles, qu''il parle, que nous parlions, que vous parliez, qu''ils parlent. Para verbos irregulares, como ''être'' e ''avoir'', a formação é diferente: que je sois, que tu sois, qu''il soit, que nous soyons, que vous soyez, qu''ils soient; que j''aie, que tu aies, qu''il ait, que nous ayons, que vous ayez, qu''ils aient.', '["Depois de expressões impessoais como ''il faut que'', ''il est important que'', para indicar necessidade ou importância.","Depois de verbos de vontade como ''vouloir que'', ''désirer que'', ''souhaiter que'', para expressar desejo.","Depois de verbos de emoção como ''être content que'', ''regretter que'', para expressar sentimentos.","Depois de verbos de opinião na forma negativa ou interrogativa, como ''ne pas penser que'', ''douter que'', para indicar incerteza."]'::jsonb, '["Usar o indicativo em vez do subjuntivo depois de ''il faut que''. Errado: Il faut que tu es là. Correto: Il faut que tu sois là.","Esquecer de usar ''que'' antes do sujeito. Errado: Je veux tu viennes. Correto: Je veux que tu viennes.","Confundir as terminações do subjuntivo com as do indicativo, especialmente em verbos do tipo ''-er''.","Usar o subjuntivo depois de verbos de opinião na afirmativa. Errado: Je pense qu''il vienne. Correto: Je pense qu''il vient."]'::jsonb, '["O subjuntivo é usado principalmente em orações subordinadas introduzidas por ''que''.","Muitas vezes, o subjuntivo é precedido por expressões impessoais como ''il est nécessaire que''.","Alguns verbos têm subjuntivo irregular, como ''faire'' (que je fasse) e ''aller'' (que j''aille).","Para formar a base do subjuntivo, use a 3ª pessoa do plural do presente do indicativo.","O subjuntivo é raro em frases afirmativas simples, mas é obrigatório após certos conectores como ''bien que'' e ''pour que''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

