insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b1-c0e70b6f421d', 'fr', 'B1', 'A Voz Passiva no Francês (B1)', 'A voz passiva é usada para destacar a ação ou o objeto que a recebe, em vez de quem a realiza. Nesta lição, você aprenderá a formar a voz passiva em diferentes tempos verbais e a usá-la corretamente.', 'A voz passiva é formada com o verbo ''être'' no tempo desejado + o particípio passado do verbo principal + ''par'' (ou ''de'') + o agente. Exemplo: ''Le gâteau est mangé par Paul.'' O particípio passado concorda em gênero e número com o sujeito.', '["Quando o agente é desconhecido ou irrelevante.","Para destacar a ação ou o resultado.","Em textos científicos, jornalísticos e administrativos.","Para evitar mencionar quem fez a ação."]'::jsonb, '["Usar o verbo ''avoir'' como auxiliar.","Fazer a concordância do particípio passado incorretamente.","Esquecer de usar ''par'' antes do agente.","Usar a voz passiva quando o francês prefere a voz ativa (ex.: ''on'')."]'::jsonb, '["Com verbos de sentimento e percepção, usa-se ''de'' em vez de ''par''.","A voz passiva é mais comum na escrita do que na fala.","O agente pode ser omitido se não for importante."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

