insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-aaaae07314b8', 'fr', 'B1', 'Futur et Conditionnel : Exprimer l''Avenir et l''Hypothèse', 'Bonjour à tous ! Aujourd''hui, nous allons explorer deux temps essentiels en français : le futur simple et le conditionnel présent. Ces temps vous permettront de parler de vos projets, de faire des hypothèses et de formuler des souhaits avec plus de précision. Imaginez que vous planifiez un voyage à Paris : vous pourrez dire « Je visiterai la Tour Eiffel » (futur) ou « Si j''avais plus de temps, je visiterais le Louvre » (conditionnel). Le futur simple est utilisé pour exprimer des actions qui se dérouleront plus tard. Le conditionnel, lui, est utilisé pour exprimer des actions possibles mais incertaines, souvent introduites par « si ». Par exemple, dans la phrase « Si j''étais riche, je voyagerais autour du monde », la condition est « si j''étais riche », et la conséquence est « je voyagerais ». La formation du futur simple est généralement régulière : on ajoute les terminaisons -ai, -as, -a, -ons, -ez, -ont à l''infinitif (par exemple, « parler » devient « je parlerai »). Cependant, certains verbes sont irréguliers, comme « être » (je serai) et « avoir » (j''aurai). Le conditionnel présent se forme avec le radical du futur et les terminaisons de l''imparfait (-ais, -ais, -ait, -ions, -iez, -aient). Par exemple, « je parlerais ». Il est important de ne pas confondre le conditionnel avec le futur : « Je mangerais » (conditionnel) exprime une condition, tandis que « Je mangerai » (futur) exprime une certitude. Dans les phrases avec « si », on utilise généralement le présent ou le passé après « si », et le futur ou le conditionnel dans l''autre partie, selon le sens. Par exemple, « Si tu viens, nous mangerons ensemble » (futur après si, le présent après si), ou « Si tu venais, nous mangerions ensemble » (conditionnel après le si, le passé après si). Pratiquons ensemble pour maîtriser ces nuances ! Pensez à vos rêves : que ferez-vous l''année prochaine ? Que feriez-vous si vous gagniez au loto ?', 'Complétez la phrase : « Demain, nous ____ (aller) à la plage. »', '["allons","irons","irions","allions"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase indica uma ação futura (amanhã), portanto usa-se o futuro simples: ''irons''. ''Allons'' é presente, ''irions'' é condicional, ''allions'' é imperfeito.","options":["allons","irons","irions","allions"],"prompt":"Complétez la phrase : « Demain, nous ____ (aller) à la plage. »"},{"answer_index":1,"explanation_pt_br":"Depois de ''si'', usamos imperfeito (avais) e o condicional na outra parte (aiderais). As outras opções misturam incorretamente os tempos.","options":["Si j''aurai le temps, je t''aiderai.","Si j''avais le temps, je t''aiderais.","Si j''aurais le temps, je t''aiderais.","Si j''avais le temps, je t''aiderai."],"prompt":"Choisissez la phrase correcte au conditionnel :"},{"answer_index":0,"explanation_pt_br":"O futuro simples de ''finir'' (2º grupo) usa a terminação -ai: ''finirai''. ''Finirais'' é condicional, ''finira'' é 3ª pessoa do singular, ''finirons'' é 1ª do plural.","options":["finirai","finirais","finira","finirons"],"prompt":"Quelle est la terminaison correcte pour le futur simple avec le verbe « finir » à la première personne du singulier ?"},{"answer_index":2,"explanation_pt_br":"Para expressar uma hipótese com ''si'', usamos imperfeito (''faisait'') e condicional (''sortirions''). ''Sortirons'' é futuro, ''ferait'' é condicional e deve ser usado na outra parte.","options":["S''il fait beau, nous sortirons.","S''il ferait beau, nous sortirions.","S''il faisait beau, nous sortirions.","S''il fera beau, nous sortirons."],"prompt":"Transformez la phrase au conditionnel : « Il fait beau, nous sortons. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-3145ee1a6a19', 'fr', 'B1', 'Le subjonctif au quotidien', 'Le subjonctif est un mode verbal très utilisé en français pour exprimer des sentiments, des doutes, des souhaits ou des actions incertaines. Pour les apprenants brésiliens, il peut sembler difficile car le portugais utilise souvent l''indicatif dans des contextes où le français exige le subjonctif. Cependant, avec un peu de pratique, vous pouvez l''utiliser naturellement dans des situations quotidiennes. Dans cette leçon, nous allons explorer comment et quand utiliser le subjonctif, en nous concentrant sur les verbes les plus fréquents. Nous verrons aussi les erreurs courantes à éviter. Après la lecture, vous aurez l''occasion de vérifier votre compréhension avec un quiz rapide. Bonne étude !', 'Quel sentiment exprime la phrase : « Je suis content que tu sois là » ?', '["Le doute","La certitude","Le regret","La joie"]'::jsonb, 3, '[{"answer_index":3,"explanation_pt_br":"La phrase exprime un sentiment de joie, car « content » est une émotion positive. Le subjonctif est utilisé après des expressions de sentiments.","options":["Le doute","La certitude","Le regret","La joie"],"prompt":"Quel sentiment exprime la phrase : « Je suis content que tu sois là » ?"},{"answer_index":1,"explanation_pt_br":"Après « il faut que », on utilise le subjonctif. Le verbe « faire » au subjonctif présent est « fasses ».","options":["Il faut que tu fais tes devoirs.","Il faut que tu fasses tes devoirs.","Il faut que tu feras tes devoirs.","Il faut que tu as fait tes devoirs."],"prompt":"Choisissez la phrase correcte qui utilise le subjonctif."},{"answer_index":1,"explanation_pt_br":"Le verbe « être » conjugué au subjonctif présent est « soyons ». Il est utilisé après « bien que ».","options":["continuons","soyons","fatigués","Bien que"],"prompt":"Quel verbe est conjugué au subjonctif présent dans cette phrase : « Bien que nous soyons fatigués, nous continuons » ?"},{"answer_index":0,"explanation_pt_br":"Au subjonctif présent, pour les verbes en -er, la terminaison pour ils/elles est -ent. Donc « parlent » est correct.","options":["parlent","parlons","parlez","parle"],"prompt":"Quelle est la terminaison correcte du verbe « parler » au subjonctif présent pour « ils » ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-354cacdee3a0', 'fr', 'B1', 'Et si on parlait des hypothèses ?', 'Faire des hypothèses, c''est imaginer ce qui pourrait être ou ce qui aurait pu être. En français, on utilise souvent les structures « si + présent » pour des hypothèses probables et « si + imparfait » pour des hypothèses imaginaires ou irréelles. Par exemple : « Si tu étudies, tu réussiras » (hypothèse probable) ou « Si j''avais le temps, je voyagerais » (hypothèse imaginaire).

Mais les hypothèses ne sont pas seulement grammaticales : dans la vie quotidienne, nous faisons constamment des hypothèses sans y penser. Par exemple, si vous voyez des nuages noirs, vous supposez qu''il va pleuvoir. Si vous ne recevez pas de réponse à un message, vous imaginez peut-être que la personne est occupée ou fâchée. Ces suppositions influencent nos décisions et nos émotions.

En classe, nous avons discuté de l''importance de vérifier nos hypothèses avant de les croire. Parfois, nous avons tendance à tirer des conclusions trop vite, ce qui peut causer des malentendus. Par exemple, si un ami ne vous dit pas bonjour, vous pourriez penser qu''il vous évite, mais peut-être qu''il est simplement préoccupé.

Pour pratiquer les hypothèses, nous avons fait un jeu de rôle : chaque étudiant devait inventer une situation imaginaire et utiliser « si + imparfait » pour décrire ce qu''il ferait. Marie a dit : « Si j''avais un million d''euros, j''achèterais une île ». Paul a répondu : « Si je pouvais voler, je rendrais visite à ma famille au Brésil tous les week-ends ». C''était amusant de voir les réponses créatives.

En conclusion, les hypothèses sont une partie essentielle de la communication. Elles nous permettent d''explorer des possibilités, de planifier et de comprendre le monde. Mais nous devons être attentifs : une hypothèse n''est pas une certitude. Il est important de vérifier les faits et de communiquer avec les autres pour éviter les malentendus.

Que feriez-vous si vous gagniez à la loterie ? Ou si vous pouviez changer une chose dans votre passé ? Ces questions nous aident à pratiquer les hypothèses en français et à réfléchir à nos valeurs.', 'Quelle structure utilise-t-on pour une hypothèse imaginaire ?', '["Si + présent","Si + imparfait","Si + plus-que-parfait","Si + futur simple"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Pour une hypothèse imaginaire, on utilise ''si + imparfait'' suivi du conditionnel présent, comme dans ''Si j''avais le temps, je voyagerais''.","options":["Si + présent","Si + imparfait","Si + plus-que-parfait","Si + futur simple"],"prompt":"Quelle structure utilise-t-on pour une hypothèse imaginaire ?"},{"answer_index":1,"explanation_pt_br":"Le texte dit que si on voit des nuages noirs, on suppose qu''il va pleuvoir.","options":["Il va faire beau.","Il va pleuvoir.","Il va neiger.","Il va faire du vent."],"prompt":"Selon le texte, que peut-on supposer si on voit des nuages noirs ?"},{"answer_index":1,"explanation_pt_br":"Le texte mentionne que Marie a dit : ''Si j''avais un million d''euros, j''achèterais une île''.","options":["Si j''étais riche, j''achèterais une voiture.","Si j''avais un million d''euros, j''achèterais une île.","Si je pouvais voler, je voyagerais dans l''espace.","Si j''étais président, je changerais les lois."],"prompt":"Quel exemple d''hypothèse est donné dans le jeu de rôle ?"},{"answer_index":1,"explanation_pt_br":"Le texte dit que tirer des conclusions trop vite peut causer des malentendus, donc vérifier nos hypothèses est important.","options":["Pour gagner du temps.","Pour éviter les malentendus.","Pour être plus créatif.","Pour améliorer notre mémoire."],"prompt":"Pourquoi est-il important de vérifier nos hypothèses ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-edc078117650', 'fr', 'B1', 'La Famille Élargie et les Relations', 'Dans la vie, la famille ne se limite pas toujours aux parents et aux enfants. En français, on utilise le terme « famille élargie » pour parler des grands-parents, des oncles, des tantes, des cousins, et même des beaux-parents. Comprendre ces liens est essentiel pour bien communiquer en société.

La famille élargie comprend plusieurs générations. Par exemple, les grands-parents sont les parents de vos parents. Vos oncles et tantes sont les frères et sœurs de vos parents. Vos cousins sont les enfants de vos oncles et tantes. Il y a aussi les liens par alliance : votre belle-famille est la famille de votre conjoint ou de votre conjointe.

Les relations familiales peuvent être complexes. Par exemple, votre beau-frère peut être le frère de votre femme ou le mari de votre sœur. Votre belle-sœur peut être la sœur de votre mari ou la femme de votre frère. Pour clarifier, on peut dire « beau-frère par alliance » ou « beau-frère par sang ». Cela aide à éviter les confusions.

Dans la culture française, la famille élargie joue souvent un rôle important. Les repas de famille sont des occasions de se retrouver et de partager. On célèbre les anniversaires, les mariages et les fêtes religieuses ensemble. Les grands-parents gardent parfois leurs petits-enfants et transmettent les traditions.

Aujourd’hui, les familles sont diverses. Il y a des familles recomposées, où les enfants vivent avec un parent et son nouveau conjoint. On parle alors de « demi-frères » ou « demi-sœurs ». Il y a aussi des familles monoparentales. Il est important de respecter toutes ces configurations familiales.

Pour parler de votre famille, vous pouvez utiliser des phrases comme : « J’ai deux cousins du côté de ma mère » ou « Ma tante paternelle habite à Lyon ». Les adjectifs « paternel » et « maternel » précisent de quel côté de la famille on parle.

En résumé, la famille élargie est un réseau de soutien et d’affection. Apprendre à nommer ces relations vous aidera à mieux comprendre et à mieux vous exprimer en français.', 'Qui sont les grands-parents ?', '["Les parents de vos parents.","Les frères et sœurs de vos parents.","Les enfants de vos cousins.","Les parents de vos amis."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Os avós são os pais dos seus pais. As outras opções se referem a tios, primos e pais de amigos.","options":["Les parents de vos parents.","Les frères et sœurs de vos parents.","Les enfants de vos cousins.","Les parents de vos amis."],"prompt":"Qui sont les grands-parents ?"},{"answer_index":0,"explanation_pt_br":"A irmã da sua mãe é sua tia. Prima é filha de tio ou tia; avó é a mãe dos seus pais; cunhada é irmã do cônjuge ou esposa do irmão.","options":["Votre tante.","Votre cousine.","Votre grand-mère.","Votre belle-sœur."],"prompt":"Si votre mère a une sœur, qui est-elle pour vous ?"},{"answer_index":0,"explanation_pt_br":"Uma família recomposta é formada quando um dos pais tem um novo cônjuge, criando meio-irmãos ou enteados. As outras opções descrevem famílias numerosas, extensas ou divorciadas.","options":["Une famille où les enfants vivent avec un parent et son nouveau conjoint.","Une famille avec beaucoup d''enfants.","Une famille qui vit dans la même maison que les grands-parents.","Une famille où les parents sont divorcés."],"prompt":"Qu''est-ce qu''une famille recomposée ?"},{"answer_index":0,"explanation_pt_br":"O irmão do seu cônjuge é seu cunhado (beau-frère). Seu irmão é por sangue, meio-irmão compartilha um dos pais, e primo é filho de tio.","options":["Votre beau-frère.","Votre frère.","Votre demi-frère.","Votre cousin."],"prompt":"Comment appelle-t-on le frère de votre conjoint ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-9560fd484343', 'fr', 'B1', 'La Technologie au Quotidien', 'La technologie fait désormais partie intégrante de notre vie quotidienne. Que ce soit pour travailler, communiquer ou se divertir, nous utilisons des outils numériques sans toujours en avoir conscience. Cet article propose de réfléchir à ces usages et à leur impact.

D''abord, les logiciels libres jouent un rôle important. Par exemple, Matomo est une alternative à Google Analytics qui permet de mesurer l''audience d''un site web tout en respectant la vie privée des visiteurs. Contrairement aux outils propriétaires, les logiciels libres offrent une transparence sur leur code source, ce qui renforce la confiance des utilisateurs.

Ensuite, le développement web a beaucoup évolué. Grâce à des bibliothèques comme DOMDocument en PHP, il est possible de manipuler des documents HTML ou XML de manière séparée du reste du programme. Cela rend le code plus clair et plus facile à maintenir, une préoccupation majeure pour les développeurs.

Un autre exemple concret est la plateforme Arduino. Ces cartes électroniques permettent à des débutants de créer des projets interactifs. Avec des capteurs et des actionneurs, on peut contrôler des lumières, des moteurs ou encore des robots. L''environnement de programmation est simplifié, ce qui encourage l''apprentissage par la pratique.

Cependant, cette omniprésence du numérique soulève des questions. Comment protéger nos données personnelles ? Comment éviter la dépendance aux écrans ? Il est essentiel de développer un esprit critique face aux technologies. En tant qu''utilisateurs, nous devons être conscients des enjeux éthiques et sociaux.

En conclusion, la technologie offre des opportunités incroyables, mais elle demande aussi une certaine vigilance. En comprenant comment fonctionnent les outils et en choisissant des alternatives respectueuses, nous pouvons tirer le meilleur parti du numérique tout en préservant notre autonomie et notre vie privée.', 'Quel est l''avantage des logiciels libres comme Matomo ?', '["Ils sont plus chers mais plus fiables.","Ils respectent la vie privée des utilisateurs.","Ils sont uniquement utilisés par les développeurs.","Ils ne permettent pas de mesurer l''audience."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto menciona que o Matomo respeita a privacidade dos visitantes, ao contrário de outras ferramentas.","options":["Ils sont plus chers mais plus fiables.","Ils respectent la vie privée des utilisateurs.","Ils sont uniquement utilisés par les développeurs.","Ils ne permettent pas de mesurer l''audience."],"prompt":"Quel est l''avantage des logiciels libres comme Matomo ?"},{"answer_index":1,"explanation_pt_br":"O texto afirma que DOMDocument é usado para manipular documentos HTML ou XML separadamente do resto do programa.","options":["Elle permet de séparer le code CSS du HTML.","Elle permet de manipuler des documents HTML et XML.","Elle sert à créer des logiciels libres.","Elle est utilisée pour mesurer l''audience d''un site."],"prompt":"Quel est le rôle de la bibliothèque DOMDocument en PHP ?"},{"answer_index":1,"explanation_pt_br":"O texto diz que com Arduino, iniciantes podem criar projetos interativos com sensores e motores.","options":["Télécharger des logiciels libres.","Créer des projets interactifs.","Mesurer l''audience d''un site.","Développer des applications web."],"prompt":"Que peut-on faire avec une carte Arduino ?"},{"answer_index":1,"explanation_pt_br":"O texto menciona que uma das pesquisas principais dos desenvolvedores é separar as linguagens de programação para simplificar seus scripts.","options":["La vitesse de leurs scripts.","La séparation des langages de programmation.","Le coût des logiciels.","La publicité en ligne."],"prompt":"Quelle est la préoccupation principale des développeurs selon l''article ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-418093a541f2', 'fr', 'B1', 'Dis ce qu’ils ont dit !', 'Au travail, au marché ou entre amis, on répète souvent ce que quelqu’un a dit. En français, pour rapporter les paroles de quelqu’un, on utilise le discours indirect (ou rapporté). Au niveau B1, on sait déjà faire des phrases simples comme « Il dit qu’il est fatigué ». Mais quand on raconte au passé, il faut changer les temps et parfois les mots comme « ici » ou « demain ». Dans cette leçon, on va voir comment transformer une phrase au présent en phrase au passé. Par exemple, si Paul dit : « Je suis content », et que je raconte ça plus tard, je dis : « Paul a dit qu’il était content ». Vous voyez ? Le verbe « être » passe du présent au imparfait. Et « je » devient « il ». C’est logique ! Le verbe introducteur est au passé, donc le verbe de la phrase change aussi. Il y a d’autres changements : « je » devient « il » ou « elle », « nous » devient « ils » ou « elles », et les adverbes de temps et de lieu changent : « aujourd’hui » devient « ce jour-là », « ici » devient « là-bas », « demain » devient « le lendemain ». Attention : si le verbe introducteur est au présent (par exemple « il dit »), alors on ne change pas le temps du verbe de la phrase, mais on change quand même le pronom et les adverbes. La différence est importante ! Par exemple, « Il dit : “Je viens demain.” » devient « Il dit qu’il vient le lendemain. » Mais si on utilise un verbe introducteur au passé, comme « il a dit », alors on change le temps du verbe : « Il a dit qu’il viendrait le lendemain. » (ou qu’il viendrait). Ici, on va surtout utiliser le passé composé et l’imparfait. Le passé composé devient le plus-que-parfait, le présent devient l’imparfait, et le futur simple devient le conditionnel présent. C’est un peu compliqué, mais avec la pratique, ça devient naturel. Souvenez-vous de la règle : quand le verbe introducteur est au passé, on recule le temps du verbe rapporté.', 'Quand on rapporte une phrase au passé, que se passe-t-il avec le verbe de la phrase rapportée ?', '["Il reste au même temps.","Il change de temps selon une règle.","Il change toujours au conditionnel.","Il devient infinitif."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Quando o verbo introdutor está no passado, o verbo da frase relatada muda para um tempo anterior: presente vira imperfeito, passado composto vira mais-que-perfeito, futuro vira condicional.","options":["Il reste au même temps.","Il change de temps selon une règle.","Il change toujours au conditionnel.","Il devient infinitif."],"prompt":"Quand on rapporte une phrase au passé, que se passe-t-il avec le verbe de la phrase rapportée ?"},{"answer_index":1,"explanation_pt_br":"No discurso indireto, se o verbo original estava no futuro, quando o verbo introdutor está no passado, usa-se o condicional presente.","options":["Le futur simple","Le conditionnel présent","L''imparfait","Le plus-que-parfait"],"prompt":"Quel temps utilise-t-on pour rapporter une action qui était future au moment du discours, quand le verbe introducteur est au passé ?"},{"answer_index":0,"explanation_pt_br":"No discurso indireto no passado, ''aujourd''hui'' vira ''ce jour-là''.","options":["ce jour-là","ce jour","cet aujourd''hui","la veille"],"prompt":"Comment transforme-t-on « aujourd''hui » dans le discours rapporté au passé ?"},{"answer_index":1,"explanation_pt_br":"O verbo introdutor ''a dit'' está no passado, então o presente ''suis'' vira imperfeito ''était''.","options":["Marie dit qu’elle était fatiguée.","Marie a dit qu’elle était fatiguée.","Marie a dit qu’elle est fatiguée.","Marie dit qu’elle a été fatiguée."],"prompt":"Quelle phrase est correcte si hier, Marie a dit : « Je suis fatiguée » ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-288cda7ea7bb', 'fr', 'B1', 'La Voix Passive : Comprendre et Utiliser', 'La voix passive est une structure grammaticale très utilisée en français, surtout dans les textes écrits, les journaux, et les discours formels. Elle permet de mettre l''accent sur l''action ou sur l''objet de l''action plutôt que sur la personne qui la réalise. Par exemple, dans la phrase « Le gâteau est mangé par Paul », l''attention est portée sur le gâteau, pas sur Paul.

Pour former la voix passive, on utilise l''auxiliaire « être » suivi du participe passé du verbe. L''auxiliaire doit être conjugué au même temps que le verbe actif correspondant. Par exemple, si le verbe actif est au présent, l''auxiliaire sera au présent ; s''il est au passé composé, l''auxiliaire sera au passé composé. Le participe passé s''accorde en genre et en nombre avec le sujet du verbe passif.

Il est important de noter que la voix passive ne peut être utilisée qu''avec des verbes transitifs directs, c''est-à-dire des verbes qui ont un complément d''objet direct. Par exemple, « manger » est transitif direct : « Paul mange une pomme » devient « La pomme est mangée par Paul ». En revanche, « dormir » est intransitif, donc on ne peut pas le mettre à la voix passive.

Dans beaucoup de cas, le complément d''agent (introduit par « par » ou « de ») peut être omis, surtout s''il est évident ou sans importance. Par exemple, « La Tour Eiffel a été construite en 1889 » est une phrase passive sans complément d''agent, car il n''est pas nécessaire de préciser qui l''a construite.

La voix passive est souvent utilisée pour décrire des processus, des faits scientifiques, ou des événements historiques, où l''agent est inconnu ou non pertinent. Par exemple, « Le vin est produit dans plusieurs régions de France » ou « Ce livre a été traduit en plusieurs langues ».

Cependant, il y a des erreurs courantes à éviter. L''une d''elles est d''utiliser le mauvais auxiliaire : il faut toujours utiliser « être », jamais « avoir ». Une autre erreur est de mal accorder le participe passé. Par exemple, on dit « Les lettres ont été écrites » (avec un « s » car « lettres » est féminin pluriel), et non « écrit » ou « écrite ».

Enfin, la voix passive peut être utilisée avec différents temps : présent (« est fait »), imparfait (« était fait »), futur (« sera fait »), passé composé (« a été fait »), etc. Elle est très utile pour varier le style et pour mettre en valeur l''information importante dans une phrase.', 'Quelle phrase est à la voix passive ?', '["Le chien mange sa pâtée.","La pâtée est mangée par le chien.","Le chien a mangé sa pâtée.","Le chien mangeait sa pâtée."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A voz passiva em francês é formada com o auxiliar ''être'' + particípio passado. A frase ''La pâtée est mangée par le chien'' tem ''est mangée'' (être no presente + particípio passado), enquanto as outras estão na voz ativa.","options":["Le chien mange sa pâtée.","La pâtée est mangée par le chien.","Le chien a mangé sa pâtée.","Le chien mangeait sa pâtée."],"prompt":"Quelle phrase est à la voix passive ?"},{"answer_index":0,"explanation_pt_br":"Na voz passiva, o objeto direto (''des fruits'') torna-se o sujeito, e o verbo ''vendre'' fica no particípio passado ''vendu'', concordando com ''fruits'' (masculino plural) → ''vendus''. Usa-se ''sont'' (présent de être).","options":["Des fruits sont vendus au marché.","Des fruits vendent au marché.","Des fruits sont vendre au marché.","Des fruits ont vendu au marché."],"prompt":"Choisissez la forme passive correcte de la phrase : « On vend des fruits au marché »."},{"answer_index":0,"explanation_pt_br":"No presente da voz passiva, usa-se ''est'' + particípio passado. ''Préparé'' concorda com ''gâteau'' (masculino singular).","options":["est préparé","est préparer","a préparé","prépare"],"prompt":"Complétez : « Ce gâteau _____ par le chef. » (présent)"},{"answer_index":1,"explanation_pt_br":"Para passar a voz passiva no passé composé, usamos ''ont été'' + particípio passado. O particípio ''fini'' concorda com ''exercices'' (masculino plural) → ''finis''.","options":["Les exercices ont fini les élèves.","Les exercices ont été finis par les élèves.","Les exercices ont fini par les élèves.","Les exercices sont fini par les élèves."],"prompt":"Mettez à la voix passive : « Les élèves ont fini les exercices. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-cb57b8393a1f', 'fr', 'B1', 'Le gérondif et les connecteurs', 'Le gérondif est une forme verbale très utile en français. Il se forme avec « en » + le participe présent. Par exemple, « en marchant » signifie « enquanto caminha ». On l''utilise pour montrer une action qui se passe en même temps qu''une autre, ou pour expliquer comment quelque chose est fait. Par exemple, « Il écoute la musique en travaillant » veut dire qu''il fait deux choses en même temps. Le gérondif est aussi utilisé avec des verbes comme « continuer » ou « finir » pour montrer une progression.

Les connecteurs sont des mots qui relient les idées dans une phrase ou entre des phrases. Ils aident à organiser un texte et à montrer des relations logiques. Par exemple, « mais » montre une opposition, « donc » montre une conséquence, « parce que » montre une cause, et « alors que » montre un contraste. En utilisant des connecteurs, on peut rendre un discours plus clair et plus fluide.

Prenons un exemple avec le gérondif et un connecteur : « En finissant ses devoirs, il a pu sortir jouer. » Ici, « en finissant » est un gérondif qui exprime la condition ou la simultanéité, et le connecteur implicite est « alors ». Les connecteurs comme « ensuite », « puis », « enfin » sont souvent utilisés pour structurer un récit.

Il est important de ne pas confondre le gérondif avec le participe présent utilisé comme adjectif. Par exemple, « un homme marchant dans la rue » est un participe présent, pas un gérondif, car il n''y a pas le « en ». Le gérondif est invariable, tandis que le participe présent peut s''accorder quand il est adjectif.

Dans la vie quotidienne, on utilise souvent le gérondif pour donner des conseils ou expliquer des processus. Par exemple, « En ajoutant du sel, vous améliorez le goût. » Les connecteurs, eux, sont essentiels pour argumenter. Par exemple, « Je pense que ce film est bon, mais je préfère le livre. »

En résumé, le gérondif et les connecteurs sont des outils précieux pour enrichir votre français. Avec de la pratique, vous les utiliserez naturellement. N''oubliez pas : en parlant, en écrivant, vous pouvez améliorer votre expression.', 'Comment se forme le gérondif en français ?', '["En + participe présent","Avoir + participe passé","Être + infinitif","En + infinitif"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O gérondif é formado por ''en'' + particípio presente. As outras opções não correspondem à formação correta.","options":["En + participe présent","Avoir + participe passé","Être + infinitif","En + infinitif"],"prompt":"Comment se forme le gérondif en français ?"},{"answer_index":0,"explanation_pt_br":"O gérondif é usado principalmente para expressar ações simultâneas. As outras opções não são funções típicas do gérondif.","options":["Exprimer une action simultanée","Exprimer une action future","Exprimer une action passée","Exprimer une action hypothétique"],"prompt":"Quelle est la fonction principale du gérondif dans une phrase ?"},{"answer_index":0,"explanation_pt_br":"''Donc'' é um conectivo lógico que expressa consequência. As outras palavras não são conectivos.","options":["donc","manger","rapide","maison"],"prompt":"Quel mot est un connecteur logique dans la liste suivante ?"},{"answer_index":0,"explanation_pt_br":"''En marchant'' indica que a ação de refletir acontece ao mesmo tempo que a de caminhar. Portanto, ''pendant que je marche'' é a interpretação correta.","options":["Pendant que je marche","Après avoir marché","Avant de marcher","Pour marcher"],"prompt":"Dans la phrase « En marchant, je réfléchis », que signifie le gérondif « en marchant » ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-aa253f56e538', 'fr', 'B1', 'Hier ou Autrefois : Passé Composé vs Imparfait', 'Hier, pendant que je marchais dans la rue, j''ai rencontré un vieil ami. Cette rencontre m''a rappelé notre enfance. Quand nous étions petits, nous jouions souvent au parc après l''école. Un jour, nous avons trouvé un chaton abandonné. Nous l''avons appelé Minou et nous l''avons ramené chez moi. Ce souvenir est resté gravé dans ma mémoire.

Pour raconter une histoire en français, il est important de choisir entre le passé composé et l''imparfait. L''imparfait décrit une action qui dure dans le passé, une habitude ou une situation. Par exemple, « Quand j''étais jeune, je jouais au tennis. » Le passé composé, lui, raconte une action ponctuelle et terminée. Par exemple, « Hier, j''ai joué au tennis. »

En général, on utilise l''imparfait pour le décor de l''histoire (le temps, les personnes, les descriptions) et le passé composé pour les événements qui font avancer l''histoire. Imaginons que vous racontiez une promenade : « Il faisait beau (imparfait), les oiseaux chantaient (imparfait), quand soudain j''ai vu (passé composé) un écureuil. » L''imparfait pose le contexte, le passé composé introduit l''action principale.

Il y a des mots qui aident à choisir. Les expressions comme « souvent », « toujours », « autrefois », « quand j''étais petit » indiquent souvent l''imparfait. Les expressions comme « soudain », « tout à coup », « un jour », « hier » indiquent souvent le passé composé. Attention : une action qui se répète dans le passé se met à l''imparfait. Une action qui se produit une seule fois et qui est terminée se met au passé composé.

Prenons un autre exemple : « Tous les étés, nous allions à la plage (imparfait). Mais l''été dernier, nous avons décidé de rester à la maison (passé composé). » Ici, l''habitude s''oppose à une décision ponctuelle. Pour bien maîtriser cette différence, il faut pratiquer. Avec le temps, cela devient plus naturel. Alors, quand vous racontez une histoire, posez-vous la question : est-ce que je décris le contexte ou est-ce que je raconte un événement ? C''est la clé pour choisir le bon temps.

Maintenant, testez vos connaissances avec les questions suivantes. Lisez attentivement chaque phrase et choisissez le temps qui convient. Bonne chance !', 'Choisissez la phrase correcte :', '["Quand j''étais enfant, je jouais souvent au parc.","Quand j''étais enfant, j''ai joué souvent au parc.","Quand j''étais enfant, je jouais souvent au parc et j''ai joué.","Quand j''étais enfant, je joue souvent au parc."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"L''imparfait est utilisé pour exprimer une habitude dans le passé. ''Jouais'' est la bonne forme. ''Ai joué'' indique une action ponctuelle, et ''joue'' est le présent.","options":["Quand j''étais enfant, je jouais souvent au parc.","Quand j''étais enfant, j''ai joué souvent au parc.","Quand j''étais enfant, je jouais souvent au parc et j''ai joué.","Quand j''étais enfant, je joue souvent au parc."],"prompt":"Choisissez la phrase correcte :"},{"answer_index":1,"explanation_pt_br":"Le passé composé est utilisé pour une action ponctuelle et terminée, indiquée par ''hier''. ''Regardais'' serait pour une description, ''regarde'' présent, ''avais regardé'' plus-que-parfait.","options":["regardais","ai regardé","regarde","avais regardé"],"prompt":"Complétez la phrase : ''Hier, je _______ un film intéressant.''"},{"answer_index":0,"explanation_pt_br":"L''action en cours (imparfait) est interrompue par une action ponctuelle (passé composé). La première phrase respecte cette règle.","options":["Pendant que je prenais le café, le téléphone a sonné.","Pendant que j''ai pris le café, le téléphone sonnait.","Pendant que je prenais le café, le téléphone sonnait.","Pendant que j''ai pris le café, le téléphone a sonné."],"prompt":"Choisissez la phrase correcte :"},{"answer_index":0,"explanation_pt_br":"L''expression ''tous les samedis'' indique une habitude passée, donc l''imparfait ''allions'' est correct.","options":["allions","sommes allés","allons","irions"],"prompt":"Complétez la phrase : ''Quand nous étions petits, nous _______ à la piscine tous les samedis.''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b1-f7428acd9b83', 'fr', 'B1', 'Introduction au Plus-que-parfait', 'Le plus-que-parfait est un temps du passé qui exprime une action antérieure à une autre action passée. En français, on le forme avec l''imparfait de l''auxiliaire (avoir ou être) suivi du participe passé du verbe. Par exemple, « Quand je suis arrivé, il avait déjà mangé » (When I arrived, he had already eaten). Dans cette phrase, ''avait mangé'' est au plus-que-parfait, indiquant que l''action de manger s''est produite avant l''arrivée.

Pour former le plus-que-parfait, on utilise l''imparfait de l''auxiliaire : j''avais, tu avais, il/elle avait, nous avions, vous aviez, ils/elles avaient (pour avoir) et j''étais, tu étais, il/elle était, nous étions, vous étiez, ils/elles étaient (pour être). Le participe passé s''accorde avec le sujet quand on utilise être, et avec le complément d''objet direct (COD) placé avant, quand on utilise avoir. Par exemple, « Elles étaient parties » (They had left) - accord avec le sujet féminin pluriel.

On utilise le plus-que-parfait pour exprimer une action qui s''est produite avant une autre action dans le passé. Par exemple, « J''avais déjà fini mes devoirs quand il est arrivé » (I had already finished my homework when he arrived). Il est souvent utilisé dans les récits pour raconter des événements antérieurs. Il peut aussi exprimer un regret dans une condition avec ''si'' : « Si j''avais su, je serais venu » (If I had known, I would have come).

Une erreur courante est de confondre le plus-que-parfait avec le passé composé. Le passé composé exprime une action passée simple, tandis que le plus-que-parfait exprime une action antérieure à une autre. Par exemple, « J''ai mangé » (I ate) n''indique pas d''antériorité, mais « J''avais mangé » (I had eaten) indique que l''action s''est produite avant un autre événement.

Pour bien utiliser le plus-que-parfait, il faut identifier l''action principale du passé et l''action antérieure. On place le plus-que-parfait dans la subordonnée ou dans la phrase qui exprime l''action antérieure. Par exemple, « Quand nous sommes arrivés, ils étaient déjà partis » (When we arrived, they had already left). Ici, ''étaient partis'' est le plus-que-parfait, car le départ est antérieur à l''arrivée.

En résumé, le plus-que-parfait est un temps essentiel pour raconter des histoires et exprimer des relations temporelles dans le passé. En le maîtrisant, vous pourrez parler de manière plus précise et nuancée. Entraînez-vous à identifier les actions antérieures et à former ce temps avec les auxiliaires corrects.', 'Quelle est la fonction principale du plus-que-parfait en français ?', '["Exprimer une action qui se passe en ce moment","Exprimer une action antérieure à une autre action passée","Exprimer une action future par rapport au passé","Exprimer une action habituelle dans le présent"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O plus-que-parfait é usado para expressar uma ação que ocorreu antes de outra ação no passado.","options":["Exprimer une action qui se passe en ce moment","Exprimer une action antérieure à une autre action passée","Exprimer une action future par rapport au passé","Exprimer une action habituelle dans le présent"],"prompt":"Quelle est la fonction principale du plus-que-parfait en français ?"},{"answer_index":0,"explanation_pt_br":"O plus-que-parfait é formado com o imperfeito do auxiliar (avoir ou être) seguido do particípio passado.","options":["Avec l''imparfait de l''auxiliaire et le participe passé","Avec le présent de l''auxiliaire et le participe passé","Avec le passé simple de l''auxiliaire et le participe passé","Avec le conditionnel de l''auxiliaire et le participe passé"],"prompt":"Comment forme-t-on le plus-que-parfait ?"},{"answer_index":2,"explanation_pt_br":"O plus-que-parfait indica que a ação de comer ocorreu antes da chegada.","options":["Une action simultanée à l''arrivée","Une action postérieure à l''arrivée","Une action antérieure à l''arrivée","Une action habituelle dans le passé"],"prompt":"Dans la phrase « Quand je suis arrivé, il avait déjà mangé », que exprime ''avait mangé'' ?"},{"answer_index":1,"explanation_pt_br":"A única frase que usa o plus-que-parfait corretamente é ''J''avais fini'', indicando ação anterior a outra no passado.","options":["J''ai fini mes devoirs avant que tu arrives","J''avais fini mes devoirs avant que tu arrives","Je finissais mes devoirs avant que tu arrives","Je finirai mes devoirs avant que tu arrives"],"prompt":"Choisissez la phrase correcte au plus-que-parfait :"}]'::jsonb, 0, true)
