insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b1-8a18a8652ea8-exercise-02', 'it', 'B1', 'Scegliere la forma corretta', 'Escolha a opção que completa corretamente a frase, prestando atenção ao uso do período hipotético.', 'Se studio, (passo / passerei) l''esame. -> passo', 'Se avessi tempo, (vado / andrei) al cinema.', '["vado","andrei","andavo","andrò"]'::jsonb, 1, 2, true, 'generated-grammar-it-b1-8a18a8652ea8')
