insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b1-8a18a8652ea8-exercise-03', 'it', 'B1', 'Riscrivere la frase', 'Reescreva a frase usando o segundo tipo do período hipotético (possibilità).', 'Se piove, prendo l''ombrello. -> Se piovesse, prenderei l''ombrello.', 'Se ho fame, mangio un panino.', '["Se avessi fame, mangerei un panino.","Se ho fame, mangerei un panino.","Se avessi fame, mangio un panino.","Se avrò fame, mangerò un panino."]'::jsonb, 0, 3, true, 'generated-grammar-it-b1-8a18a8652ea8')
