insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b1-8a18a8652ea8-exercise-04', 'it', 'B1', 'Completare con il congiuntivo', 'Complete a frase com o congiuntivo imperfetto do verbo entre parênteses.', 'Se (avere) ________ tempo, verrei. -> avessi', 'Se (potere) ________, ti aiuterei volentieri.', '["potessi","posso","potrei","potevo"]'::jsonb, 0, 4, true, 'generated-grammar-it-b1-8a18a8652ea8')
