insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b1-8a18a8652ea8-exercise-05', 'it', 'B1', 'Dialogo: scegliere la risposta giusta', 'Leia o diálogo e escolha a resposta mais adequada.', 'A: Che fai se piove? B: Se piove, (resto / resterei) a casa. -> resto', 'A: Mi passi il sale, per favore? B: Certo, ...', '["te lo do","te lo dessi","te lo darei","te lo davo"]'::jsonb, 0, 5, true, 'generated-grammar-it-b1-8a18a8652ea8')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-c2c9274e5602', 'it', 'B1', 'Pronomi Combinati', 'Nesta lição, você vai aprender a usar os pronomes combinados (me lo, te lo, glielo, etc.) para expressar ações que envolvem duas pessoas ou coisas de forma natural. Esses pronomes são muito comuns na conversação diária e ajudam a evitar repetições.', 'Os pronomes combinados são formados pela união de um pronome de objeto indireto (mi, ti, gli, le, ci, vi, loro) com um pronome de objeto direto (lo, la, li, le, ne). A combinação segue a ordem: primeiro o objeto indireto, depois o direto. Observe as transformações: mi + lo = me lo; ti + la = te la; gli/le + lo = glielo; ci + li = ce li; vi + le = ve le. O pronome ''loro'' é exceção: permanece separado (es. ''lo do a loro'').', '["Quando queremos dizer que fazemos algo para alguém: ''Compro un regalo per Maria'' → ''Glielo compro''.","Para evitar repetir o objeto: ''Hai le chiavi? Sì, te le do''.","Em respostas curtas: ''Hai chiamato Paolo? Sì, gli ho parlato'' → ''Sì, gli ho parlato''.","Com o verbo ''dare'' e outros verbos de transferência: ''Ti do il libro'' → ''Te lo do''.","No imperativo: ''Dimmelo!'' (Diga-me isso!)"]'::jsonb, '["Confundir a ordem: dizer ''lo mi do'' em vez de ''me lo do''.","Esquecer a mudança de forma: ''mi lo'' é incorreto; o correto é ''me lo''.","Usar ''gli'' antes de ''lo'' sem a forma combinada ''glielo''.","Colocar o pronome depois do verbo em tempos compostos, quando deve vir antes do auxiliar: ''ho glielo dato'' (errado) vs ''glielo ho dato'' (certo).","Não usar o pronome combinado quando deveria ser usado, resultando em frases repetitivas: ''Do il libro a lui'' em vez de ''Glielo do''."]'::jsonb, '["Os pronomes combinados são muito usados na fala e na escrita informal.","No passato prossimo, o particípio passado concorda com o objeto direto: ''Glielo ho detto'' (dito o quê? ''lo'' é masculino singular).","Com ''loro'' (a eles/elas), a forma é sempre separada: ''do loro il libro'' ou ''lo do a loro''.","No imperativo, o pronome é anexado ao verbo: ''Dimmelo!'' (diga-me isso), ''Faglielo!'' (faça-o para ele)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
