insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-9f45b6e73ee9', 'it', 'B1', 'La forma passiva e il ''si'' impersonale', 'Nesta unidade, você vai aprender a usar a forma passiva e o ''si'' impessoal em italiano. Essas estruturas são muito comuns no dia a dia e ajudam a falar de ações sem dizer quem as faz, ou para dar ênfase à ação em vez de quem a realiza. Vamos ver como se formam e quando usá-las.', 'A forma passiva é formada pelo verbo ''essere'' (no tempo certo) seguido do particípio passado do verbo principal. O particípio concorda com o sujeito em gênero e número. Exemplo: ''La pizza è mangiata da Marco'' (A pizza é comida por Marco). O ''si'' impessoal é formado com ''si'' + verbo na terceira pessoa do singular (ou plural, se o objeto for plural). Exemplo: ''Si mangia bene in Italia'' (Come-se bem na Itália).', '["Usamos a forma passiva quando queremos focar na ação ou no objeto, não em quem faz a ação.","Usamos o ''si'' impessoal para expressar generalizações ou ações de pessoas em geral, como ''Si dice che...'' (Diz-se que...).","A forma passiva é comum em notícias e textos formais.","O ''si'' impessoal é usado frequentemente em instruções e receitas."]'::jsonb, '["Confundir o ''si'' impessoal com o ''si'' reflexivo.","Esquecer de fazer a concordância do particípio passado na forma passiva.","Usar a forma passiva quando se deveria usar o ''si'' impessoal (ou vice-versa)."]'::jsonb, '["No ''si'' impessoal, se o objeto for plural, o verbo vai para o plural: ''Si vendono case'' (Vendem-se casas).","Na forma passiva, o agente (quem faz a ação) é introduzido por ''da'' (por).","O ''si'' impessoal é usado com verbos transitivos e intransitivos, mas com intransitivos o sujeito é sempre singular."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

