insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-2437eed0afd8', 'it', 'B1', 'Discorso Indiretto al Passato', 'O discorso indiretto (referto) é usado para relatar o que alguém disse, sem usar aspas. No nível B1, é importante saber mudar os tempos verbais, especialmente ao passar do presente para o passado. Esta lição explica como formar o discurso indireto no passado, com foco nas mudanças de tempos, pronomes e advérbios de tempo.', 'Para formar o discurso indireto, geralmente usamos um verbo introdutório como ''dire'', ''chiedere'', ''rispondere'' etc., seguido da conjunção ''che'' e a informação relatada. Quando o verbo introdutório está no passado (passato prossimo ou imperfetto), o tempo verbal na oração subordinada muda: o presente vira imperfetto, o passato prossimo vira trapassato prossimo, e o futuro vira condizionale passato. Além disso, pronomes e advérbios de tempo e lugar podem mudar (ex.: ''oggi'' vira ''quel giorno'').', '["Relatar o que alguém disse em uma conversa (ex.: ''Marco ha detto che era stanco.'')","Contar o que foi perguntado (ex.: ''Mi ha chiesto se avevo fame.'')","Expressar opiniões ou pensamentos relatados (ex.: ''Pensavo che sarebbe venuto.'')","Relatar promessas ou intenções (ex.: ''Ha detto che sarebbe partito l''indomani.'')"]'::jsonb, '["Não mudar o tempo verbal quando o verbo introdutor está no passado (ex.: ''Ha detto che è stanco'' em vez de ''era stanco'').","Esquecer de mudar pronomes (ex.: ''Ha detto: Io vengo'' vira ''Ha detto che lui veniva'', não ''io veniva'').","Manter advérbios de tempo sem mudança (ex.: ''oggi'' deve virar ''quel giorno'', não permanecer ''oggi'').","Confundir o uso de ''che'' e ''se'' para perguntas indiretas (ex.: ''Mi ha chiesto se...'' para perguntas sim/não)."]'::jsonb, '["No discurso indireto, as perguntas diretas introduzidas por ''se'' (se) para respostas sim/não ou por palavras interrogativas (dove, quando, perché, etc.) para perguntas abertas.","A mudança de ''io'' para ''lui/lei'' é essencial quando quem fala não é o sujeito da frase relativa.","O[''passato remoto''] não é usado em discurso indireto no italiano moderno, prefira o passato prossimo.","As expressões de tempo como ''ieri'' podem virar ''il giorno prima'' e ''domani'' vira ''il giorno dopo'' ou ''l''indomani''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

