insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-b629344bb7e8', 'it', 'B1', 'Il Gerundio Italiano: Come e Quando Usarlo', 'Nesta lição, você vai aprender a usar o gerúndio italiano, uma forma verbal muito comum para expressar ações em andamento ou simultâneas. Vamos ver como formá-lo, em quais situações usá-lo e como evitar erros comuns. Ao final, cinco exercícios vão ajudar você a praticar.', 'Para formar o gerúndio, pegue a raiz do verbo e adicione as terminações: -ando para verbos -are (es. parlare → parlando), -endo para verbos -ere e -ire (es. leggere → leggendo, partire → partendo). Verbos irregulares como fare → facendo, dire → dicendo, bere → bevendo. Com os pronomes, o gerúndio pode ser acompanhado de pronomes como ''lo'', ''la'', etc.', '["Per esprimere un''azione in corso: ''Sto mangiando una pizza''.","Per esprimere un''azione simultanea: ''Camminando, ho visto un amico''.","Dopo il verbo ''stare'' per formare il presente progressivo: ''Stai studiando?''","Per esprimere una condizione: ''Correndo, ti stancherà''.","In frasi subordinate per indicare modo o causa: ''Ridendo, mi ha raccontato tutto''."]'::jsonb, '["Confondere il gerundio con l''infinito: ''Sto mangiare'' invece di ''Sto mangiando''.","Usare il gerundio dopo preposizioni come ''di'' – in italiano si usa l''infinito: ''Penso di andare'' (non ''Penso di andando'').","Dimenticare l''accordo del participio passato nei tempi composti? (Nota: il gerundio non si accorda, ma il participio sì).","Formare il gerundio dei verbi irregolari in modo sbagliato: ''facendo'' non ''fando''.","Usare il gerundio per azioni future in modo errato – il gerundio non si usa per il futuro progressivo in italiano, si usa il futuro semplice."]'::jsonb, '["In italiano, il gerundio è invariabile: non cambia con il soggetto.","Il gerundio composto (avendo + participio) si usa per azioni completate: ''Avendo finito, sono uscito''.","Attenzione alla posizione dei pronomi: di solito si attaccano al gerundio (es. ''mangiandolo''), ma con ''stare'' si può separare: ''sto mangiandolo'' o ''lo sto mangiando''.","Nella lingua parlata, il presente progressivo con ''stare'' è molto comune."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

