insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-dbead6a96651', 'it', 'B1', 'Passato Prossimo vs Imperfetto', 'Nesta lição, você vai aprender a diferença entre o Passato Prossimo e o Imperfetto, dois tempos verbais do passado em italiano. O Passato Prossimo é usado para ações concluídas e pontuais, enquanto o Imperfetto descreve ações habituais, em progresso ou cenários no passado. Vamos explorar como formar cada tempo e quando usá-los, com muitos exemplos e exercícios.', 'O Passato Prossimo é formado com o presente do verbo essere ou avere + o particípio passado do verbo principal. Por exemplo: ''io ho mangiato'' (eu comi), ''lei è andata'' (ela foi). O Imperfetto é formado com a raiz do verbo + as terminações -vo, -vi, -va, -vamo, -vate, -vano. Por exemplo: ''io mangiavo'' (eu comia), ''lei andava'' (ela ia).', '["Usamos o Passato Prossimo para ações concluídas em um momento específico: ''Ieri ho comprato il pane.''","Usamos o Imperfetto para ações habituais no passado: ''Da bambino giocavo sempre al parco.''","Usamos o Imperfetto para descrever o cenário de uma história: ''Era una giornata calda e il sole splendeva.''","Usamos o Passato Prossimo para uma sequência de ações concluídas: ''Sono uscito, ho incontrato Marco e abbiamo preso un caffè.''","Com expressões como ''mentre'' (enquanto), usamos Imperfetto para a ação em andamento e Passato Prossimo para a ação interrompida: ''Mentre leggevo, è arrivato Paolo.''"]'::jsonb, '["Usar o Passato Prossimo para ações habituais: ''Da giovane ho giocato a calcio.'' (errado) -> ''Da giovane giocavo a calcio.'' (correto)","Usar o Imperfetto para ações pontuais: ''Ieri andavo al cinema.'' (errado) -> ''Ieri sono andato al cinema.'' (correto)","Confundir a escolha de essere ou avere no Passato Prossimo: ''Io ho andato'' (errado) -> ''Io sono andato'' (correto)","Esquecer a concordância do particípio passado com o sujeito quando se usa essere: ''Lei è andato'' (errado) -> ''Lei è andata'' (correto)"]'::jsonb, '["O Passato Prossimo é o tempo mais comum para falar de ações passadas concluídas.","O Imperfetto é frequentemente usado em narrativas para descrever o contexto.","Alguns verbos, como ''essere'', são irregulares no particípio passado: ''stato''.","A escolha entre essere e avere depende do verbo: verbos intransitivos geralmente usam essere.","Praticar com exemplos do cotidiano ajuda a fixar a diferença."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

