insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-24c4454d6730', 'it', 'B1', 'Il Condizionale Presente: Cortesia, Desideri e Consigli', 'O condizionale presente é um tempo verbal usado para expressar cortesia, desejos, conselhos e situações hipotéticas. É essencial para comunicar de forma educada e para falar sobre sonhos e possibilidades no presente.', 'Para formar o condizionale presente, pegue o infinitivo do verbo e adicione as terminações: -ei, -esti, -ebbe, -emmo, -este, -ebbero. Para verbos regulares, use o infinitivo sem a vogal final para a maioria dos casos (por exemplo, ''parlare'' -> ''parlerei''). Verbos irregulares, como ''essere'' (sarei), ''avere'' (avrei), ''dovere'' (dovrei), ''potere'' (potrei), ''volere'' (vorrei), ''venire'' (verrei) e ''bere'' (berrei), têm formas próprias que devem ser memorizadas.', '["Para fazer pedidos educados: ''Vorrei un caffè, per favore.''","Para expressar desejos: ''Mi piacerebbe viaggiare in Italia.''","Para dar conselhos de forma gentil: ''Dovresti riposare un po''.''","Para falar de situações hipotéticas: ''Se avessi tempo, andrei al cinema.''"]'::jsonb, '["Confundir o condizionale com o futuro: ''Domani andrò'' (futuro) vs. ''Andrei'' (condizionale).","Usar o condizionale em vez do subjuntivo em algumas frases: ''Penso che sia'' (subjuntivo), não ''Penso che sarebbe''.","Esquecer as formas irregulares: ''Vorrei'' não é ''Voglierei''.","Aplicar as terminações do futuro: ''Parlarò'' é errado; o correto é ''Parlerei''."]'::jsonb, '["O condizionale presente é frequentemente usado na forma polida com ''potrei'' e ''vorrei''.","A diferença entre ''vorrei'' e ''voglio'' é que ''vorrei'' é mais educado.","Para formar o condizionale de verbos terminados em -care e -gare, adiciona-se um ''h'' para manter o som: ''cercare'' -> ''cercherei''.","Em frases condicionais, usa-se frequentemente o congiuntivo na subordinada: ''Se avessi tempo, andrei...''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

