insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-ce514b8e80a5', 'it', 'B1', 'Il Gerundio: Come e Quando Usarlo', 'O gerúndio italiano é uma forma verbal muito usada para expressar ações em andamento, modo, causa e condição. Nesta lição, você vai aprender como formar o gerúndio (presente e passado) e quando usá-lo, especialmente com os verbos ''stare'' e ''continuare''. Vamos praticar com exercícios para você se sentir confiante!', 'O gerúndio presente forma-se com as terminações: -ando para verbos -are (parlare -> parlando), -endo para verbos -ere (leggere -> leggendo) e -ire (dormire -> dormendo). Alguns verbos irregulares: fare -> facendo, dire -> dicendo, bere -> bevendo. O gerúndio passado usa o gerúndio de ''essere'' ou ''avere'' + particípio passado: avendo parlato, essendo andato/a. ', '["Ação em andamento com ''stare'': Sto mangiando. (Estou comendo.)","Modo: Cammina zoppicando. (Ele anda mancando.)","Causa: Essendo stanco, sono rimasto a casa. (Porque estava cansado, fiquei em casa.)","Condição: Continuando così, imparerai presto. (Continuando assim, você aprenderá logo.)"]'::jsonb, '["Usar o gerúndio em vez do infinitivo após preposições: ''Prima di uscire'' (não ''prima di uscendo'').","Confundir o gerúndio com o particípio presente: ''studente'' vs ''studiando''.","Esquecer que o gerúndio não concorda com o sujeito, exceto no passado com ''essere'': ''essendo andata'' (feminino singular).","Usar ''stare'' + gerúndio para ações habituais: ''Vado spesso al cinema'' (não ''sto andando spesso'')."]'::jsonb, '["O gerúndio é invariável no presente, independentemente do gênero e número.","Com ''stare'' e ''continuare'', o gerúndio indica uma ação que está em progresso ou que continua.","O gerúndio passado é usado para ações completas que precedem a ação principal.","Em frases com gerúndio, o sujeito é geralmente o mesmo da oração principal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

