insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-54c573fd5e7b', 'it', 'B1', 'Connettivi discorsivi: e, ma, perché, quindi, anche se', 'Nesta lição, você vai aprender a usar conectivos discursivos comuns em italiano para unir ideias e dar fluidez ao seu discurso. Esses conectivos ajudam a expressar adição, contraste, causa, consequência e condição, tornando sua comunicação mais clara e natural.', 'Os conectivos são palavras invariáveis que ligam frases ou partes de frases. Os principais são: ''e'' (adição), ''ma'' (contraste), ''perché'' (causa), ''quindi'' (consequência) e ''anche se'' (condição/concessão). Eles podem aparecer no início da frase ou entre duas orações, e não mudam de forma.', '["Per aggiungere informazioni simili: ''Mi piace il caffè e il tè.''","Per esprimere un contrasto: ''Vorrei uscire, ma fa freddo.''","Per dare una ragione: ''Sto a casa perché sono stanco.''","Per indicare una conseguenza: ''Ho studiato molto, quindi sono preparato.''","Per introdurre una condizione o concessione: ''Vengo con te anche se ho molto lavoro.''"]'::jsonb, '["Confondere ''ma'' e ''però'': in italiano, ''però'' è più colloquiale, ma ''ma'' è più comune.","Usare la virgola davanti a ''e'' quando unisce due elementi semplici: ''Pane e burro'' (senza virgola).","Posizionare ''anche se'' alla fine della frase: Di solito va all''inizio o dopo la frase principale.","Dimenticare che ''perché'' può essere usato sia per causa che per fine, ma in questo livello usiamo solo per causa."]'::jsonb, '["Quando ''anche se'' introduce una condizione, il verbo dopo ''se'' va al congiuntivo, ma a livello B1 spesso si usa l''indicativo.","I connettivi possono essere usati in contesti formali e informali, ma alcuni come ''quindi'' sono neutri.","Pratica l''uso dei connettivi per collegare le tue idee in modo più efficace."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

