insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-42ceed3104e4', 'it', 'B1', 'Il Congiuntivo Presente: Uso Frequente', 'Nesta lição, você vai aprender a usar o congiuntivo presente em contextos frequentes da língua italiana. Esse modo verbal é essencial para expressar opiniões, desejos, dúvidas e emoções, especialmente em frases subordinadas. Você verá como conjugá-lo, quando usá-lo e como evitar erros comuns.', 'Para conjugar o congiuntivo presente, use a raiz do verbo no presente do indicativo (primeira pessoa do singular) e adicione as terminações específicas. Para os verbos regulares, as terminações são: -i, -i, -i, -iamo, -iate, -ino (para verbos -are, -ere, -ire). Por exemplo: ''parlare'' -> che io parli, che tu parli, che lui/lei parli, che noi parliamo, che voi parliate, che loro parlino. Verbos irregulares comuns incluem ''essere'' (che io sia), ''avere'' (che io abbia), ''fare'' (che io faccia) e ''andare'' (che io vada).', '["Dopo verbi di opinione: ''Penso che...'', ''Credo che...''","Dopo verbi di desiderio: ''Voglio che...'', ''Spero che...''","Dopo verbi di dubbio: ''Dubito che...'', ''Non sono sicuro che...''","Dopo verbi di emozione: ''Mi dispiace che...'', ''Sono felice che...''","Dopo congiunzioni come ''benché'' e ''sebbene''","Dopo espressioni impessoali: ''È importante che...'', ''Bisogna che...''"]'::jsonb, '["Usare l''indicativo dopo ''che'' quando serve il congiuntivo","Confondere le desinenze del congiuntivo con quelle dell''indicativo","Dimenticare che il congiuntivo si usa solo in frasi subordinate","Usare ''che'' senza verbo che richiede congiuntivo"]'::jsonb, '["O congiuntivo presente é usado principalmente em orações subordinadas introduzidas por ''che''.","Preste atenção aos verbos irregulares: eles são muito comuns no italiano falado.","Depois de ''se'' (se), use apenas o indicativo ou o congiuntivo, dependendo do contexto.","Na linguagem informal, às vezes o congiuntivo é substituído pelo indicativo, mas é importante saber a forma correta."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

