insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-81d747245f0b', 'it', 'B1', 'La forma passiva e il "si" impersonale', 'Nesta lição, você vai aprender a usar a forma passiva e o "si" impessoal em italiano. Essas estruturas são muito comuns no dia a dia para falar de ações sem dizer quem as faz. Vamos ver como formar frases como "La pizza viene mangiata" ou "Si parla italiano".', 'Forma passiva: si usa il verbo essere (o venire) + participio passato. Esempio: "La casa viene costruita" (a casa está sendo construída). Il "si" impersonale: si usa "si" + verbo alla terza persona singolare. Esempio: "Si mangia bene in Italia" (come-se bem na Itália).', '["Para destacar a ação em vez de quem a pratica: \"La lettera è stata scritta\".","Para falar de regras ou costumes gerais: \"Si paga alla cassa\".","Para descrever processos: \"Il caffè viene preparato con la moka\".","Para expressar opiniões impessoais: \"Si dice che...\" (Dizem que...)."]'::jsonb, '["Usar o verbo no plural com o si impessoal: *\"Si mangiano bene\"* (errado) em vez de \"Si mangia bene\".","Confundir o passivo com o impessoal: \"Si vende frutta\" (impessoal) vs \"La frutta è venduta\" (passivo).","Esquecer a concordância do particípio passado: \"Le porte sono aperte\" (não \"aperto\")."]'::jsonb, '["No impessoal, o verbo fica sempre na terceira pessoa do singular.","No passivo, o tempo do verbo essere indica o tempo da ação.","Com o si impessoal, se houver um complemento objeto, o verbo pode concordar com ele em alguns casos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

