insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-a288f9371b7b', 'it', 'B1', 'Combined Pronouns in Italian', 'Nesta lição, você vai aprender a combinar pronomes oblíquos átonos (mi, ti, lo, la, gli, le, ci, vi) com pronomes de objeto indireto (mi, ti, gli, le, ci, vi) para formar os chamados ''pronomi combinati''. Essa estrutura é muito usada na língua italiana para evitar repetições e tornar frases mais naturais, especialmente com verbos como ''dare'', ''dire'', ''mandare''.', 'A formação dos pronomes combinados segue regras específicas. Primeiro, escolha o pronome de objeto indireto (a quem), e depois o pronome de objeto direto (o quê). A ordem é sempre: objeto indireto + objeto direto. Quando o objeto direto é ''lo'', ''la'', ''li'' ou ''le'', o objeto indireto ''mi'', ''ti'', ''ci'', ''vi'' muda para ''me'', ''te'', ''ce'', ''ve'' (ex: ''me lo'', ''te la'', ''ce li'', ''ve le''). Já ''gli'' se combina sem mudança: ''gli lo'' vira ''glielo'' (escrito junto). ''Le'' (para ela) também vira ''glie'' + lo/la/li/le (ex: ''glielo'').', '["Substituir dois objetos por pronomes: ''Mario dà un libro a me'' -> ''Mario me lo dà''.","Expressar ações de dar, enviar, dizer com objetos diretos e indiretos.","Responder perguntas como ''A chi lo dai?'' -> ''Te lo do''."]'::jsonb, '["Esquecer de mudar ''mi'' para ''me'' antes de ''lo/la/li/le''.","Colocar o pronome direto antes do indireto (ex: ''lo mi'' em vez de ''me lo'').","Separar ''glielo'' quando deveria ser junto."]'::jsonb, '["Os pronomes combinados são sempre escritos juntos quando o indireto é ''gli'' ou ''le''.","Atenção: ''glielo'' pode ser ''a ele'' ou ''a ela'' no singular, e ''glieli'' para o plural.","Para ''ci'' e ''vi'', lembre-se de ''ce'' e ''ve'' antes de lo/la/li/le."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

