insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-b7b12e821607', 'it', 'B1', 'Il Discorso Indiretto', 'Vamos aprender a usar o discurso indiretto (referir-se ao que alguém disse sem usar aspas). Essa habilidade é essencial para relatar conversas, opiniões e informações no dia a dia, no trabalho e nos estudos.', 'Para transformar uma frase direta em indireta, geralmente mudamos o verbo introdutor (ex.: dice, ha detto) e ajustamos o tempo verbal, os pronomes e os advérbios. A regra mais comum: se o verbo introdutor está no presente, o tempo verbal permanece o mesmo; se está no passado (especialmente passato prossimo), fazemos uma ''marcha atrás'' nos tempos: presente -> imperfetto; futuro -> condizionale; passato prossimo -> trapassato prossimo. Ex.: ''Mario dice: "Sono stanco"'' -> ''Mario dice che è stanco''. ''Mario ha detto: "Sono stanco"'' -> ''Mario ha detto che era stanco''.', '["Para relatar o que alguém disse em uma conversa, preservando o significado original.","Para transmitir perguntas, pedidos ou conselhos de forma indireta, usando ''se'' ou ''di''.","Para citar informações de notícias, livros, pessoas famosas, etc.","Para expressar opiniões ou crenças relatadas, como ''Penso che'' ou ''Credo che''."]'::jsonb, '["Esquecer de ajustar o tempo verbal quando o verbo introdutor está no passado (ex.: usar ''è'' em vez de ''era'').","Manter os pronomes pessoais e possessivos na forma original sem adaptá-los ao novo contexto.","Confundir a introdução de perguntas indiretas: usar ''che'' em vez de ''se'' para perguntas sim/não.","Não alterar advérbios de tempo e lugar, como ''oggi'' -> ''quel giorno'', ''qui'' -> ''lì''."]'::jsonb, '["Se o verbo introdutor estiver no presente (dice, domanda), o tempo do discurso indireto geralmente não muda.","Quando o verbo introdutor está no passato prossimo (ha detto), aplica-se a ''concordância dos tempos'': presente vira imperfetto, futuro vira condizionale, passato prossimo vira trapassato prossimo.","Para ordens e pedidos, usa-se a estrutura ''verbo + di + infinitivo'' (ex.: Mi ha detto di chiudere la porta).","Nas perguntas indiretas, a ordem da frase é declarativa (sem inversão) e não usamos ponto de interrogação.","Atenção aos elementos deíticos: ''oggi'' -> ''quel giorno'', ''domani'' -> ''il giorno dopo'', ''ieri'' -> ''il giorno prima''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

