insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-c4a71f16e40b', 'it', 'B1', 'Connettivi Discorsivi', 'Nesta lição, você vai aprender a usar conectivos discursivos em italiano para organizar suas ideias, conectar frases e tornar sua fala e escrita mais fluidas. Conectivos como ''infatti'', ''quindi'', ''però'' e ''tuttavia'' ajudam a expressar causa, consequência, contraste e adição, essenciais para se comunicar de forma clara e eficaz.', 'Os conectivos são palavras ou expressões que unem orações ou partes do discurso. Em italiano, eles são usados no início, meio ou fim das frases. Eles não mudam de forma, pois são invariáveis. Alguns conectivos têm sinônimos: ''quindi'' e ''perciò''; ''ma'' e ''però''; ''inoltre'' e ''anche''. É importante escolher o conectivo certo para o tipo de relação que se quer expressar (causa, consequência, oposição, etc.).', '["Per esprimere causa: ''Non sono uscito perché pioveva.''","Per esprimere conseguenza: ''Ho studiato molto, quindi ho superato l''esame.''","Per esprimere contrasto: ''Vorrei venire, però devo lavorare.''","Per aggiungere informazioni: ''Mi piace l''Italia. Inoltre, sto imparando l''italiano.''","Per spiegare o giustificare: ''Non ho fame. Infatti, ho appena mangiato.''","Per esprimere alternativa: ''Puoi venire domani oppure puoi chiamarmi.''"]'::jsonb, '["Confondere ''perché'' (causa) con ''perciò'' (conseguenza): ''Sono stanco perché ho lavorato'' (certo), ma non ''Sono stanco perciò ho lavorato''.","Usare ''ma'' e ''però'' nella stessa frase: ''Ma però non sono d''accordo'' (errore comune, si usa uno solo).","Posizionare ''infatti'' alla fine della frase: ''Ho fame, sono stanco infatti'' (in realtà ''infatti'' di solito viene prima della spiegazione).","Dimenticare la virgola dopo i connettivi all''inizio della frase: ''Tuttavia non sono d''accordo'' (in realtà si mette la virgola: ''Tuttavia, non sono d''accordo'').","Usare ''quindi'' come ''dunque'' in contesti informali senza variazione."]'::jsonb, '["I connettivi sono invariabili, non cambiano con il genere o numero.","Alcuni connettivi sono più formali: ''tuttavia'', ''pertanto'', ''dunque''.","La virgola dopo un connettivo all''inizio di una frase è comune ma non obbligatoria.","In italiano, i connettivi possono essere usati all''inizio di una frase per dare enfasi.","Pratica con dialoghi quotidiani per memorizzare i connettivi più comuni."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

