insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-f276ef5c5534', 'it', 'B1', 'Passato Prossimo vs Imperfetto', 'Nesta lição, você vai aprender a diferença entre o passato prossimo e o imperfetto, dois tempos verbais do passado em italiano. O passato prossimo é usado para ações concluídas e pontuais, enquanto o imperfetto descreve ações habituais, contínuas ou de fundo no passado. Vamos explorar como formá-los e quando usá-los com exemplos práticos.', 'O passato prossimo é formado com o presente do verbo avere ou essere + o particípio passado do verbo principal. Por exemplo: ''ho mangiato'' (comi), ''sono andato/a'' (fui). O imperfetto é formado com o radical do verbo + as terminações -avo, -avi, -ava, -avamo, -avate, -avano (para verbos em -are), -evo, -evi, -eva, -evamo, -evate, -evano (para -ere), -ivo, -ivi, -iva, -ivamo, -ivate, -ivano (para -ire). Por exemplo: ''mangiavo'' (eu comia), ''andavo'' (eu ia).', '["Usamos o passato prossimo para ações concluídas em um momento específico: ''Ieri ho comprato un libro.''","Usamos o imperfetto para ações habituais no passado: ''Da bambino giocavo sempre in giardino.''","Usamos o imperfetto para descrever o cenário ou uma ação em andamento: ''Era una bella giornata e il sole splendeva.''","Usamos o passato prossimo para ações que aconteceram em sequência: ''Ho aperto la porta e sono entrato.''"]'::jsonb, '["Usar o passato prossimo para ações habituais: ''Ieri mangiavo spesso pizza'' (errado, deveria ser ''mangiavo'', pois é habitual).","Usar o imperfetto para ações pontuais: ''Ieri andavo al cinema'' (errado, deveria ser ''sono andato'').","Confundir a escolha do auxiliar: ''Ho andato'' em vez de ''sono andato''.","Esquecer a concordância do particípio passado com o sujeito em verbos com essere: ''Maria è andato'' (errado, deveria ser ''è andata'').","Usar o imperfetto para uma ação que interrompe outra: ''Quando mangiava, ha squillato il telefono'' (correto: a ação que interrompe é passato prossimo)."]'::jsonb, '["O imperfetto também é usado para expressar cortesia: ''Volevo un caffè'' (Eu queria um café).","Alguns verbos mudam de significado dependendo do tempo: ''sapevo'' (eu sabia) vs ''ho saputo'' (eu fiquei sabendo).","Na narração, o imperfetto fornece o contexto, e o passato prossimo os eventos principais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

