insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-437ce66c7e18', 'it', 'B1', 'Il Condizionale Presente: Desideri, Consigli e Cortesia', 'O condizionale presente em italiano é usado para expressar desejos, pedidos educados, conselhos e situações hipotéticas. Nesta lição, você aprenderá a formar e usar esse tempo verbal em contextos do dia a dia, melhorando sua comunicação de forma cortês e natural.', 'Para formar o condizionale presente, adicione as terminaiões -ei, -esti, -ebbe, -emmo, -este, -ebbero ao radical do verbo. Para verbos regulares, o radical é o infinitivo sem -are, -ere, -ire. Exemplos: parlare -> parlerei, parleresti, parlerebbe, parleremmo, parlereste, parlerebbero; credere -> crederei, crederesti, crederebbe, crederemmo, credereste, crederebbero; partire -> partirei, partiresti, partirebbe, partiremmo, partireste, partirebbero. Alguns verbos irregulares: essere -> sarei, saresti, sarebbe, saremmo, sareste, sarebbero; avere -> avrei, avresti, avrebbe, avremmo, avreste, avrebbero; fare -> farei, faresti, farebbe, faremmo, fareste, farebbero; andare -> andrei, andresti, andrebbe, andremmo, andreste, andrebbero.', '["Para expressar desejos e vontades: Vorrei un caffè, per favore. (Eu gostaria de um café, por favor.)","Para fazer pedidos educados: Mi potresti aiutare? (Você poderia me ajudar?)","Para dar conselhos: Dovresti riposare di più. (Você deveria descansar mais.)","Para expressar situações hipotéticas: Se avessi tempo, viaggerei. (Se eu tivesse tempo, viajaria.)"]'::jsonb, '["Confundir o condizionale com o futuro: ''Vorrei'' (eu gostaria) não é ''vorrò'' (eu quererei).","Usar o condizionale no lugar do congiuntivo em frases com ''se'': ''Se avessi tempo, viaggerei'' (correto), não ''se avrei tempo''.","Esquecer as terminações específicas do condizionale, usando as do futuro.","Aplicar as terminações do condizionale a verbos irregulares sem as devidas alterações no radical."]'::jsonb, '["O condizionale presente é frequentemente usado para ser educado e cortês.","Em frases condicionais com ''se'', o condizionale é usado na oração principal, enquanto a condição usa o congiuntivo imperfetto.","Não há equivalente direto em português; use o futuro do pretérito (eu gostaria) ou a expressão ''poderia''.","Pratique com verbos comuns do dia a dia para se acostumar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

