insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-ca73b74c5e35', 'it', 'B1', 'Condizionale Presente: realtà e possibilità', 'Nesta unidade, você vai aprender a usar o condizionale presente para falar de situações reais e possíveis. O condizionale é usado para expressar cortesia, desejos, conselhos e hipóteses. Vamos praticar com exercícios para você se sentir seguro(a) ao usar esse tempo verbal no dia a dia.', 'Para formar o condizionale presente, você pega o infinitivo do verbo e adiciona as terminações: -ei, -esti, -ebbe, -emmo, -este, -ebbero. Para verbos da primeira conjugação (-are), a vogal temática ''a'' muda para ''e'' (ex: parlare -> parlerei). Para verbos da segunda e terceira conjugação, mantém-se a vogal do infinitivo (ex: credere -> crederei, dormire -> dormirei). Alguns verbos têm formas irregulares, como ''andare'' -> andrei, ''dovere'' -> dovrei, ''potere'' -> potrei, ''sapere'' -> saprei, ''vedere'' -> vedrei, ''venire'' -> verrei.', '["Para fazer pedidos de forma educada: ''Vorrei un caffè, per favore.''","Para expressar desejos: ''Mi piacerebbe visitare Roma.''","Para dar conselhos: ''Dovresti riposare un po''.''","Para falar de possibilidades: ''Potrei venire domani, ma non sono sicuro.''","Para expressar uma opinião de forma suave: ''Direi che è una buona idea.''"]'::jsonb, '["Confundir o condizionale com o futuro: ''Domani andrò'' (futuro) vs ''Andrei volentieri'' (condizionale).","Usar o condizionale após ''se'' em frases condicionais da realidade: ''Se ho tempo, vengo'' (não ''verrei'').","Esquecer de trocar ''a'' por ''e'' nos verbos -are: ''parlerei'' (não ''parlaria'').","Usar o condizionale para ações que acontecerão com certeza: ''Domani verrò'' (não ''verrei'')."]'::jsonb, '["O condizionale presente é frequentemente usado com verbos modais como ''dovere'', ''potere'', ''volere''.","É comum em frases com ''se'' para expressar condições possíveis: ''Se potessi, verrei.''","Lembre-se de que a terminação é sempre a mesma para todas as conjugações.","Para formar o condizionale composto (passado), use o condizionale de ''avere'' ou ''essere'' + particípio passado."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

