insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-62e1bc069e81', 'it', 'B1', 'Pronomi combinati', 'Nesta lição, você vai aprender a usar os pronomes combinados em italiano, que são a união de pronomes de objeto direto e indireto. Eles são muito comuns na conversa do dia a dia e ajudam a falar de forma mais natural e fluida. Vamos ver como se formam, quando usar e os erros mais comuns.', 'Os pronomes combinados são formados pela combinação de um pronome de objeto indireto (mi, ti, gli, le, ci, vi) com um pronome de objeto direto (lo, la, li, le) ou com a partícula ''ne''. A combinação segue essas regras: O pronome de objeto indireto muda de forma: ''mi'' vira ''me'', ''ti'' vira ''te'', ''ci'' vira ''ce'', ''vi'' vira ''ve'', ''gli'' vira ''glie'', ''le'' vira ''glie'' também. O pronome de objeto direto permanece o mesmo: ''lo'', ''la'', ''li'', ''le''. Exemplos: ''me lo'', ''te la'', ''ce li'', ''ve le'', ''glielo'', ''gliela'', ''glieli'', ''gliele''. Quando o verbo está no infinitivo, no gerúndio ou no imperativo, os pronomes combinados podem ser unidos ao final do verbo, formando uma única palavra. Exemplos: ''comprarmelo'' (comprar para mim), ''scrivendogliela'' (escrevendo para ele/ela).', '["Para responder perguntas, substituindo o objeto direto e indireto: ''Hai dato il libro a Marco?'' - ''Sì, glielo ho dato.'' (Sim, eu o dei a ele.)","Para expressar ações do dia a dia de forma mais concisa: ''Mi passi il sale?'' - ''Certo, te lo passo.'' (Claro, eu o passo para você.)","Em pedidos com imperativo: ''Compraglielo!'' (Compre-o para ele/ela!)","Com verbos modais, como ''potere'', ''volere'', ''dovere'', o pronome pode vir antes do verbo modal ou depois do infinitivo: ''Lo devo fare'' ou ''Devo farlo''.","Em frases negativas, o pronome vem antes do verbo: ''Non glielo do.'' (Eu não o dou a ele/ela.)"]'::jsonb, '["Usar a forma errada do pronome indireto antes do direto: ''mi lo'' em vez de ''me lo''.","Usar ''gli'' ao invés de ''glie'' antes de ''lo'', ''la'', ''li'', ''le'': ''gli lo'' em vez de ''glielo''.","Esquecer de combinar os pronomes quando ambos estão presentes, separando-os: ''gli lo do'' em vez de ''glielo do''.","Não usar o hífen ou a união quando o pronome combinado é anexado ao verbo no infinitivo: ''per comprarlo per me'' em vez de ''per comprarmelo''.","Esquecer de colocar o pronome combinado antes do verbo em tempos compostos: ''Ho glielo detto'' em vez de ''Glielo ho detto''."]'::jsonb, '["A forma ''glie'' é usada para ambos ''a lui'' e ''a lei'' antes dos pronomes diretos, mas o contexto esclarece o significado.","A combinação com ''ne'' também é possível: ''me ne'', ''te ne'', ''se ne'', ''ce ne'', ''ve ne'', ''gliene''.","No imperativo formal (Lei), os pronomes vêm sempre antes do verbo, mas no informal (tu) podem ser anexados ao final.","Em construções com verbo servile (come ''potere'', ''volere'', ''dovere''), os pronomes combinados podem ser colocados antes do verbo servile ou depois do infinitivo, mas nunca entre os dois."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

