insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-8ec6ec1b0620', 'it', 'B1', 'Il Congiuntivo Presente: Uso Frequente', 'Nesta lição, você vai aprender o congiuntivo presente, um modo verbal muito usado em italiano para expressar dúvida, opinião, desejo e emoção. Vamos focar nos verbos mais frequentes e nas situações do dia a dia, como dar opiniões, fazer pedidos e falar sobre sentimentos. Ao final, você será capaz de reconhecer e usar esse tempo verbal com confiança.', 'Para formar o congiuntivo presente, pegue a primeira pessoa do singular do presente do indicativo (io) e troque as terminações:

- Verbi in -ARE: parlare → che io parli, che tu parli, che lui/lei parli, che noi parliamo, che voi parliate, che loro parlino.
- Verbi in -ERE: credere → che io creda, che tu creda, che lui/lei creda, che noi crediamo, che voi crediate, che loro credano.
- Verbi in -IRE: partire → che io parta, che tu parta, che lui/lei parta, che noi partiamo, che voi partiate, che loro partano.

Alguns verbos são irregulares: essere → che io sia, avere → che io abbia, fare → che io faccia, andare → che io vada, venire → che io venga, potere → che io possa, dovere → che io debba, volere → che io voglia, bere → che io beva, dire → che io dica.', '["Dopo verbi di opinione: pensare, credere, sembrare (ex: Penso che sia una buona idea).","Dopo verbi di desiderio e volontà: volere, desiderare, preferire (ex: Voglio che tu venga).","Dopo espressioni di emozione e sentimento: essere contento, dispiaciuto, avere paura (ex: Sono contento che tu sia qui).","Dopo congiunzioni come benché, sebbene, affinché, prima che (ex: Sebbene sia stanco, vado a lavorare).","Dopo espressioni impessoali come è possibile, è necessario, bisogna che (ex: È necessario che tu studi)."]'::jsonb, '["Usar o indicativo em vez do congiuntivo após ''penso che'' ou ''credo che'' (ex: *Penso che è giusto → Penso che sia giusto).","Confundir a conjugação do congiuntivo com o indicativo, especialmente nas formas ''parli'' e ''parla''.","Esquecer que, com congiunções como ''benché'' e ''sebbene'', o verbo deve estar no congiuntivo (ex: *Benchè sono stanco → Benchè sia stanco).","Aplicar o congiuntivo em frases afirmativas com ''che'' quando não é necessário (ex: *So che tu sia stanco, quando deveria ser ''So che tu sei stanco'')."]'::jsonb, '["O congiuntivo é usado com mais frequência na língua escrita e em situações formais, mas também é comum na fala cotidiana, especialmente em frases como ''Penso che sia bello''.","Lembre-se de que o congiuntivo presente é usado para ações presentes ou futuras, não para ações passadas (para essas, use o congiuntivo imperfetto).","Prestar atenção aos verbos irregulares é essencial, pois eles são muito comuns em contextos de opinião e desejo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

