insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-d074f6ae704b', 'it', 'B1', 'Pronomi Combinati', 'Nesta lição, você vai aprender a usar os pronomes combinados em italiano. Eles são usados para substituir dois objetos em uma frase, como ''a Maria'' e ''o livro'', evitando repetições. Por exemplo, em vez de dizer ''do il libro a Maria'', você pode dizer ''glielo do'' (eu o dou a ela). Vamos ver como formar essas combinações e em quais contextos usá-las.', 'Os pronomes combinados são formados pela união de um pronome de objeto indireto (mi, ti, gli, le, ci, vi, loro) com um pronome de objeto direto (lo, la, li, le, ne). A combinação segue a ordem: primeiro o indireto, depois o direto. Quando o indireto é ''mi'', ''ti'', ''ci'' ou ''vi'', a vogal final muda para ''e'' antes do direto: me lo, te lo, ce lo, ve lo. Quando o indireto é ''gli'' ou ''le'', eles se tornam ''glie'' e se juntam ao direto: glielo, gliela, glieli, gliele. Exemplo: ''do il libro a Maria'' -> ''glielo do'' (glie + lo). O pronome ''ne'' também pode ser combinado: ''me ne'', ''te ne'', ''gliene'', etc.', '["Para substituir dois objetos em uma frase: ''Compro il pane per i bambini'' -> ''Compro loro il pane'' ou ''Lo compro loro'', mas mais comum: ''glielo compro''.","Para responder perguntas: ''Hai dato il libro a Paolo?'' -> ''Sì, glielo ho dato.''","Para evitar repetição em conversas: ''Hai visto Maria? Le ho parlato'' -> ''Le ho parlato'' (mas se você também menciona o que falou: ''glielo ho detto'').","Com verbos modais: ''Devo dare questo a lui'' -> ''Glielo devo dare'' ou ''Devo darglielo''."]'::jsonb, '["Confundir a ordem: colocar o direto antes do indireto (ex: ''lo gli do'' em vez de ''glielo do'').","Manter a forma original do indireto: dizer ''le lo'' em vez de ''glielo''.","Não mudar a vogal: dizer ''mi lo'' em vez de ''me lo''.","Usar ''loro'' como pronome combinado: ''loro lo'' não é usado; em vez disso, use ''glielo'' para ''a eles'' também.","Esquecer de usar o pronome combinado com verbos no infinitivo: ''per darglielo'' em vez de ''per dare lo a lui''."]'::jsonb, '["O pronome combinado ''glielo'' pode significar ''a ele'', ''a ela'' ou ''a eles/elas'' dependendo do contexto.","Em tempos compostos (com ''avere''), o particípio passado concorda com o pronome direto: ''li ho comprati'' -> ''glieli ho comprati''.","Com ''ecco'' + pronome combinado: ''Eccoglielo'' (aqui está para ele) é uma forma comum.","Quando ''ne'' é combinado, ele expressa quantidade: ''me ne dai due?'' (você me dá dois?)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

