insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b1-1ff8b2edf04e', 'it', 'B1', 'Verbi Pronominali Frequenti (B1)', 'Neste nível, você vai aprender a usar verbos pronominais frequentes, como ''andarsene'', ''prendersela'', ''farcela'', ''cavarsela'', que são muito usados na conversa do dia a dia. Esses verbos têm pronomes especiais que mudam o significado do verbo original.', 'A formação dos verbos pronominais envolve o verbo + uma ou duas particelle pronominali (ci, ne, la, le). Exemplos: andare + ne + se = andarsene; prendere + se + la = prendersela; fare + ce + la = farcela; cavare + se + la = cavarsela. A conjugação segue os tempos verbais, mas com os pronomes sempre presentes. Por exemplo: io me ne vado (andarsene), tu te la prendi (prendersela), lui ce la fa (farcela), noi ce la caviamo (cavarsela).', '["Andarsene: ir embora, partir. Ex.: Me ne vado perché sono stanco.","Prendersela: ficar chateado/bravo com alguém. Ex.: Non prendertela con me!","Farcela: conseguir, ter sucesso. Ex.: Ce la farai all''esame!","Cavarsela: dar um jeito, sobreviver, sair de uma situação difícil. Ex.: Lui se la cava sempre."]'::jsonb, '["Esquecer o pronome: dizer ''vado'' em vez de ''me ne vado''.","Colocar o pronome no lugar errado na frase: ''vado me ne'' em vez de ''me ne vado''.","Confundir ''farcela'' com ''farci'' (fazer a nós mesmos).","Usar ''andarsene'' com objeto direto: ''me ne vado la casa'' em vez de ''me ne vado da casa''."]'::jsonb, '["Esses verbos têm significados idiomáticos, então é importante aprender as expressões completas.","No passato prossimo, o particípio passado concorda com o sujeito, mas não muda com os pronomes. Ex.: Mi sono pentito / Mi sono pentita.","Em contextos informais, o pronome ''ci'' pode ser omitido em alguns dialetos, mas o padrão é mantê-lo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

