insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b1-1ff8b2edf04e-exercise-05', 'it', 'B1', 'Passato prossimo di ''andarsene''', 'Lembre-se da forma com o pronome e o auxiliar.', 'Ieri sera, Marco e Anna se ne sono andati molto presto.', 'Qual è il passato prossimo di ''andarsene'' per ''io''?', '["Mi ne sono andato","Me ne sono andato","Mi sono ne andato","Sono me ne andato"]'::jsonb, 1, 5, true, 'generated-grammar-it-b1-1ff8b2edf04e')
